    o.type = type; o.frequency.value = freq;
    g.gain.setValueAtTime(vol, audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
    o.connect(g); g.connect(audioCtx.destination);
    o.start(); o.stop(audioCtx.currentTime + dur);
  } catch(e){}
}

// ===== Render Tickers =====
const tickerList = document.getElementById('tickerList');
function renderTickers(){
  tickerList.innerHTML = '';
  stocks.forEach(s => {
    const change = s.price - s.open;
    const pct = (change/s.open*100);
    const up = change >= 0;
    const row = document.createElement('div');
    row.className = `ticker-row p-2 rounded-lg flex justify-between items-center ${selected.sym===s.sym?'active':''}`;
    row.innerHTML = `
      <div>
        <div class="font-bold text-sm">${s.sym}</div>
        <div class="text-[10px] text-gray-500 truncate" style="max-width:120px">${s.name}</div>
      </div>
      <div class="text-right">
        <div class="font-semibold num text-sm" data-price="${s.sym}">$${s.price.toFixed(2)}</div>
        <div class="text-[11px] num ${up?'text-green-400':'text-red-400'}">${up?'+':''}${pct.toFixed(2)}%</div>
      </div>
    `;
    row.onclick = () => { selected = s; renderTickers(); renderChart(); updateChartHeader(); };
    tickerList.appendChild(row);
  });
}

// ===== Chart =====
const canvas = document.getElementById('chart');
const ctx = canvas.getContext('2d');
function resizeCanvas() {
  const dpr = window.devicePixelRatio || 1;
  canvas.width = canvas.clientWidth * dpr;
  canvas.height = canvas.clientHeight * dpr;
  ctx.setTransform(dpr,0,0,dpr,0,0);
}
window.addEventListener('resize', () => { resizeCanvas(); renderChart(); });

function renderChart(){
  resizeCanvas();
  const w = canvas.clientWidth, h = canvas.clientHeight;
  ctx.clearRect(0,0,w,h);
  const data = selected.history;
  const min = Math.min(...data), max = Math.max(...data);
  const range = max - min || 1;
  const pad = 10;
  const up = data[data.length-1] >= data[0];
  const color = up ? '#16c784' : '#ea3943';

  // grid
  ctx.strokeStyle = 'rgba(255,255,255,0.04)';
  ctx.lineWidth = 1;
  for (let i=0;i<5;i++){
    const y = pad + (h-2*pad) * i/4;
    ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(w,y); ctx.stroke();
    ctx.fillStyle = '#475569'; ctx.font = '10px Inter';
    const val = max - range * i/4;
    ctx.fillText('$'+val.toFixed(2), 4, y-2);
  }

  // line + fill
  ctx.beginPath();
  data.forEach((p,i)=>{
    const x = (i/(data.length-1)) * w;
    const y = pad + (1 - (p-min)/range) * (h-2*pad);
    if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  });
  const grad = ctx.createLinearGradient(0,0,0,h);
  grad.addColorStop(0, color+'55');
  grad.addColorStop(1, color+'00');
  ctx.lineTo(w,h); ctx.lineTo(0,h); ctx.closePath();
  ctx.fillStyle = grad; ctx.fill();

  ctx.beginPath();
  data.forEach((p,i)=>{
    const x = (i/(data.length-1)) * w;
    const y = pad + (1 - (p-min)/range) * (h-2*pad);
    if (i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  });
  ctx.strokeStyle = color; ctx.lineWidth = 2; ctx.stroke();

  // last point
  const lx = w, ly = pad + (1 - (data[data.length-1]-min)/range) * (h-2*pad);
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.arc(lx-3,ly,4,0,Math.PI*2); ctx.fill();
  ctx.fillStyle = color+'33';
  ctx.beginPath(); ctx.arc(lx-3,ly,9,0,Math.PI*2); ctx.fill();
}

function updateChartHeader(){
  document.getElementById('chartSymbol').textContent = selected.sym;
  document.getElementById('chartName').textContent = selected.name;
  document.getElementById('chartPrice').textContent = '$'+selected.price.toFixed(2);
  const ch = selected.price - selected.open;
  const pct = ch/selected.open*100;
  const el = document.getElementById('chartChange');
  el.textContent = `${ch>=0?'+':''}${ch.toFixed(2)} (${pct>=0?'+':''}${pct.toFixed(2)}%)`;
  el.className = 'text-sm font-semibold num ' + (ch>=0?'text-green-400':'text-red-400');
  document.getElementById('statOpen').textContent = '$'+selected.open.toFixed(2);
  document.getElementById('statHigh').textContent = '$'+selected.high.toFixed(2);
  document.getElementById('statLow').textContent = '$'+selected.low.toFixed(2);
  document.getElementById('statVol').textContent = (selected.volume/1e6).toFixed(2)+'M';
}

// ===== Price Ticks =====
function tick(){
  stocks.forEach(s => {
    // Geometric Brownian Motion-ish
    const drift = 0.00005;
    const shock = (Math.random()-0.5) * s.vol;
    const old = s.price;
    s.price = Math.max(0.5, s.price * (1 + drift + shock));
    s.high = Math.max(s.high, s.price);
    s.low = Math.min(s.low, s.price);
    s.history.push(s.price);
    if (s.history.length > 80) s.history.shift();
    s.volume += Math.floor(Math.random()*200000);

    // flash row
    const el = document.querySelector(`[data-price="${s.sym}"]`);
    if (el){
      el.textContent = '$'+s.price.toFixed(2);
      el.parentElement.parentElement.classList.remove('flash-up','flash-down');
      void el.offsetWidth;
      el.parentElement.parentElement.classList.add(s.price>=old?'flash-up':'flash-down');
    }
  });
  updateChartHeader();
  renderChart();
  updatePortfolio();
  renderHoldings();
}

// ===== Portfolio =====
function updatePortfolio(){
  let pv = 0;
  Object.entries(state.holdings).forEach(([sym,h])=>{
    const s = stocks.find(x=>x.sym===sym);
    if (s) pv += s.price * h.shares;
  });
  const nw = state.cash + pv;
  const pl = nw - state.initial;
  document.getElementById('cashDisplay').textContent = '$'+state.cash.toLocaleString('en-US',{minimumFractionDigits:2, maximumFractionDigits:2});
  document.getElementById('portfolioValue').textContent = '$'+pv.toLocaleString('en-US',{minimumFractionDigits:2, maximumFractionDigits:2});
  document.getElementById('netWorth').textContent = '$'+nw.toLocaleString('en-US',{minimumFractionDigits:2, maximumFractionDigits:2});
  const plEl = document.getElementById('totalPL');
  plEl.textContent = (pl>=0?'+':'')+'$'+pl.toLocaleString('en-US',{minimumFractionDigits:2, maximumFractionDigits:2});
  plEl.className = 'text-lg font-bold num ' + (pl>=0?'text-green-400':'text-red-400');
  save();
}

function renderHoldings(){
  const c = document.getElementById('holdingsTab');
  const entries = Object.entries(state.holdings).filter(([,h])=>h.shares>0);
  if (!entries.length) {
    c.innerHTML = '<div class="text-center text-gray-500 text-sm py-8">No positions yet.<br/>Start trading!</div>';
    return;
  }
  c.innerHTML = entries.map(([sym,h])=>{
    const s = stocks.find(x=>x.sym===sym);
    const value = s.price * h.shares;
    const cost = h.avgCost * h.shares;
    const pl = value - cost;
    const plp = pl/cost*100;
    return `<div class="panel2 p-2.5 cursor-pointer hover:bg-gray-700" onclick="selectSym('${sym}')">
      <div class="flex justify-between">
        <div>
          <div class="font-bold text-sm">${sym}</div>
          <div class="text-[10px] text-gray-400">${h.shares} sh @ $${h.avgCost.toFixed(2)}</div>
        </div>
        <div class="text-right">
          <div class="font-semibold text-sm num">$${value.toFixed(2)}</div>
          <div class="text-[10px] num ${pl>=0?'text-green-400':'text-red-400'}">${pl>=0?'+':''}$${pl.toFixed(2)} (${plp.toFixed(2)}%)</div>
        </div>
      </div>
    </div>`;
  }).join('');
}

function renderHistory(){
  const c = document.getElementById('historyTab');
  if (!state.history.length) {
    c.innerHTML = '<div class="text-center text-gray-500 text-sm py-8">No transactions yet.</div>';
    return;
  }
  c.innerHTML = state.history.slice().reverse().map(t=>`
    <div class="panel2 p-2.5">
      <div class="flex justify-between items-center">
        <div>
          <span class="text-xs font-bold px-1.5 py-0.5 rounded ${t.type==='buy'?'bg-green-900 text-green-300':'bg-red-900 text-red-300'}">${t.type.toUpperCase()}</span>
          <span class="font-bold text-sm ml-1">${t.sym}</span>
        </div>
        <div class="text-right">
          <div class="text-sm num">${t.shares} @ $${t.price.toFixed(2)}</div>
          <div class="text-[10px] text-gray-500">${t.time}</div>
        </div>
      </div>
    </div>
  `).join('');
}

function selectSym(sym){
  selected = stocks.find(s=>s.sym===sym);
  renderTickers(); renderChart(); updateChartHeader();
}

// ===== Trade Modal =====
function openTrade(mode){
  tradeMode = mode;
  const modal = document.getElementById('tradeModal');
  modal.classList.remove('hidden');
  document.getElementById('modalTitle').textContent = `${mode==='buy'?'Buy':'Sell'} ${selected.sym}`;
  document.getElementById('modalPrice').textContent = '$'+selected.price.toFixed(2);
  const confirm = document.getElementById('modalConfirm');
  if (mode==='buy'){
    document.getElementById('modalAvailLabel').textContent = 'Available Cash';
    document.getElementById('modalAvail').textContent = '$'+state.cash.toFixed(2);
    confirm.className = 'w-full mt-4 py-3 rounded-lg btn btn-buy text-base';
    confirm.textContent = 'Confirm Buy';
  } else {
    const owned = state.holdings[selected.sym]?.shares || 0;
    document.getElementById('modalAvailLabel').textContent = 'Shares Owned';
    document.getElementById('modalAvail').textContent = owned + ' sh';
    confirm.className = 'w-full mt-4 py-3 rounded-lg btn btn-sell text-base';
    confirm.textContent = 'Confirm Sell';
  }
  document.getElementById('qtyInput').value = 1;
  updateModalTotal();
  document.getElementById('modalError').classList.add('hidden');
}
function closeModal(){ document.getElementById('tradeModal').classList.add('hidden'); }
function updateModalTotal(){
  const q = parseFloat(document.getElementById('qtyInput').value)||0;
  document.getElementById('modalTotal').textContent = '$'+(q*selected.price).toFixed(2);
}
function setPct(p){
  let q;
  if (tradeMode==='buy') q = Math.floor((state.cash*p)/selected.price);
  else q = Math.floor((state.holdings[selected.sym]?.shares||0)*p);
  document.getElementById('qtyInput').value = Math.max(0,q);
  updateModalTotal();
}
document.getElementById('qtyInput').addEventListener('input', updateModalTotal);

document.getElementById('modalConfirm').onclick = () => {
  const q = parseInt(document.getElementById('qtyInput').value)||0;
  const err = document.getElementById('modalError');
  err.classList.add('hidden');
  if (q<=0){ err.textContent='Enter a valid quantity.'; err.classList.remove('hidden'); return; }
  const total = q*selected.price;
  if (tradeMode==='buy'){
    if (total > state.cash){ err.textContent='Insufficient cash.'; err.classList.remove('hidden'); return; }
    state.cash -= total;
    const h = state.holdings[selected.sym] || {shares:0, avgCost:0};
    const newShares = h.shares + q;
    h.avgCost = (h.avgCost*h.shares + total)/newShares;
    h.shares = newShares;
    state.holdings[selected.sym] = h;
    beep(800, 0.1, 'square');
  } else {
    const h = state.holdings[selected.sym];
    if (!h || h.shares < q){ err.textContent='Not enough shares.'; err.classList.remove('hidden'); return; }
    state.cash += total;
    h.shares -= q;
    if (h.shares===0) delete state.holdings[selected.sym];
    beep(500, 0.1, 'square');
  }
  state.history.push({type:tradeMode, sym:selected.sym, shares:q, price:selected.price, time:new Date().toLocaleTimeString()});
  updatePortfolio(); renderHoldings(); renderHistory();
  closeModal();
};

// ===== Tabs =====
document.querySelectorAll('.tab').forEach(t => {
  t.onclick = () => {
    document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));
    t.classList.add('active');
    const tab = t.dataset.tab;
    document.getElementById('holdingsTab').classList.toggle('hidden', tab!=='holdings');
    document.getElementById('historyTab').classList.toggle('hidden', tab!=='history');
    if (tab==='history') renderHistory();
  };
});

// ===== Reset =====
document.getElementById('resetBtn').onclick = () => {
  if (!confirm('Reset portfolio? This will erase all positions and history.')) return;
  state = { cash: 100000, holdings: {}, history: [], initial: 100000 };
  save(); updatePortfolio(); renderHoldings(); renderHistory();
};

// ===== Save =====
function save(){ localStorage.setItem('qt_state', JSON.stringify(state)); }

// ===== Clock =====
setInterval(()=>{ document.getElementById('clock').textContent = new Date().toLocaleTimeString(); },1000);

// ===== Init =====
renderTickers();
renderChart();
updateChartHeader();
updatePortfolio();
renderHoldings();
setInterval(tick, 1500);

document.getElementById('tradeModal').addEventListener('click', e=>{
  if (e.target.id==='tradeModal') closeModal();
});
</script>
</body>
</html>
