  ctx.beginPath(); ctx.arc(W/2,H/2,50,0,Math.PI*2); ctx.stroke();
  // goals
  ctx.fillStyle='rgba(255,255,255,0.3)';
  ctx.fillRect(0, GOAL_TOP, 10, GOAL_BOT-GOAL_TOP);
  ctx.fillRect(W-10, GOAL_TOP, 10, GOAL_BOT-GOAL_TOP);
  // penalty area
  ctx.strokeRect(10, H/2-100, 80, 200);
  ctx.strokeRect(W-90, H/2-100, 80, 200);
}
function drawCircle(o){ ctx.beginPath(); ctx.fillStyle=o.color; ctx.arc(o.x,o.y,o.r,0,Math.PI*2); ctx.fill(); ctx.strokeStyle='#000'; ctx.lineWidth=2; ctx.stroke();}

function update(dt){
  if(!game.running) return;
  game.time -= dt;
  if(game.time <= 0){ endGame(); return; }

  // player input
  const p = game.player;
  let dx=0, dy=0;
  const k = game.keys;
  if(k['ArrowUp']||k['w']) dy-=1;
  if(k['ArrowDown']||k['s']) dy+=1;
  if(k['ArrowLeft']||k['a']) dx-=1;
  if(k['ArrowRight']||k['d']) dx+=1;
  if(game.joy.active){ dx += game.joy.x; dy += game.joy.y; }
  const len = Math.hypot(dx,dy);
  if(len>0){ dx/=len; dy/=len; }
  const speed = 200;
  p.x += dx*speed*dt; p.y += dy*speed*dt;
  p.x = Math.max(p.r, Math.min(W-p.r, p.x));
  p.y = Math.max(p.r, Math.min(H-p.r, p.y));

  // AI movement - chase ball or defend
  const ai = game.ai;
  const b = game.ball;
  let targetX = b.x, targetY = b.y;
  // if ball on opponent side, attack to player goal (left)
  if(b.x > W*0.4){ targetX = b.x - 20; }
  else { targetX = Math.max(W*0.55, b.x); targetY = H/2;}
  const adx = targetX-ai.x, ady = targetY-ai.y;
  const al = Math.hypot(adx,ady);
  if(al>1){ ai.x += (adx/al)*160*dt; ai.y += (ady/al)*160*dt; }
  ai.x = Math.max(ai.r, Math.min(W-ai.r, ai.x));
  ai.y = Math.max(ai.r, Math.min(H-ai.r, ai.y));

  // AI shoot if near ball and on player side
  const aiToBall = Math.hypot(ai.x-b.x, ai.y-b.y);
  if(aiToBall < ai.r + b.r + 4 && ai.x > b.x){
    // shoot toward left goal
    const tx = 0, ty = H/2;
    const sdx = tx-b.x, sdy = ty-b.y;
    const sl = Math.hypot(sdx,sdy);
    b.vx = (sdx/sl)*420; b.vy = (sdy/sl)*420;
    beep(300,0.05,'square');
  }

  // ball physics
  b.x += b.vx*dt; b.y += b.vy*dt;
  b.vx *= 0.985; b.vy *= 0.985;
  if(b.y < b.r+10){ b.y=b.r+10; b.vy*=-0.7; }
  if(b.y > H-b.r-10){ b.y=H-b.r-10; b.vy*=-0.7; }

  // Goals
  if(b.x < 15 && b.y>GOAL_TOP && b.y<GOAL_BOT){
    game.score[1]++; goalSound(); updateScore(); resetPositions();
  } else if(b.x < b.r){ b.x=b.r; b.vx*=-0.7; }
  if(b.x > W-15 && b.y>GOAL_TOP && b.y<GOAL_BOT){
    game.score[0]++; goalSound(); updateScore(); resetPositions();
  } else if(b.x > W-b.r){ b.x=W-b.r; b.vx*=-0.7; }

  // Player-ball collision (dribble)
  const pdb = Math.hypot(p.x-b.x, p.y-b.y);
  if(pdb < p.r+b.r){
    const ang = Math.atan2(b.y-p.y, b.x-p.x);
    b.x = p.x + Math.cos(ang)*(p.r+b.r);
    b.y = p.y + Math.sin(ang)*(p.r+b.r);
    // soft push
    b.vx = b.vx*0.3 + dx*120; b.vy = b.vy*0.3 + dy*120;
  }
  // AI-ball collision
  const adb = Math.hypot(ai.x-b.x, ai.y-b.y);
  if(adb < ai.r+b.r){
    const ang = Math.atan2(b.y-ai.y, b.x-ai.x);
    b.x = ai.x + Math.cos(ang)*(ai.r+b.r);
    b.y = ai.y + Math.sin(ang)*(ai.r+b.r);
  }

  updateScore();
}

function shoot(){
  const p = game.player, b = game.ball;
  const d = Math.hypot(p.x-b.x, p.y-b.y);
  if(d < p.r+b.r+15){
    const tx = W, ty = H/2;
    const ang = Math.atan2(ty-b.y, tx-b.x);
    b.vx = Math.cos(ang)*500; b.vy = Math.sin(ang)*500;
    beep(600,0.08,'square');
  }
}

function render(){
  drawField();
  drawCircle(game.player);
  drawCircle(game.ai);
  // ball
  ctx.beginPath(); ctx.fillStyle='#fff'; ctx.arc(game.ball.x,game.ball.y,game.ball.r,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#000'; ctx.lineWidth=1; ctx.stroke();
}

function loop(now){
  if(!game) return;
  const dt = Math.min(0.05,(now-game.lastTime)/1000);
  game.lastTime = now;
  update(dt); render();
  if(game.running) requestAnimationFrame(loop);
}

function endGame(){
  game.running = false;
  const [a,b] = game.score;
  let res = 'SERI! 🤝';
  if(a>b) res = `MENANG! 🏆 ${myTeam}`;
  else if(b>a) res = `KALAH 😢`;
  document.getElementById('resultText').textContent = res;
  document.getElementById('finalScore').textContent = `${myTeam} ${a} - ${b} ${oppTeam}`;
  showScreen('overScreen');
}

// Controls
window.addEventListener('keydown', e=>{ if(game){ game.keys[e.key]=true; if(e.key===' '){ shoot(); e.preventDefault(); } }});
window.addEventListener('keyup', e=>{ if(game) game.keys[e.key]=false; });

// Touch joystick
const joy = document.getElementById('joystick'), stick = document.getElementById('stick');
function joyHandle(e){
  e.preventDefault();
  const t = e.touches ? e.touches[0] : e;
  const r = joy.getBoundingClientRect();
  const cx = r.left+r.width/2, cy=r.top+r.height/2;
  let dx = t.clientX-cx, dy=t.clientY-cy;
  const max = r.width/2;
  const l = Math.hypot(dx,dy);
  if(l>max){ dx=dx/l*max; dy=dy/l*max; }
  stick.style.left=(30+dx)+'px'; stick.style.top=(30+dy)+'px';
  if(game){ game.joy.x = dx/max; game.joy.y = dy/max; game.joy.active=true; }
}
function joyEnd(){ stick.style.left='30px'; stick.style.top='30px'; if(game){game.joy.active=false; game.joy.x=0; game.joy.y=0;} }
joy.addEventListener('touchstart', joyHandle); joy.addEventListener('touchmove', joyHandle); joy.addEventListener('touchend', joyEnd);
document.getElementById('shootBtn').addEventListener('touchstart', e=>{e.preventDefault(); shoot();});
document.getElementById('shootBtn').addEventListener('click', shoot);

document.getElementById('startBtn').onclick = ()=>{
  if(myTeam === oppTeam){ alert('Pilih lawan yang berbeda!'); return; }
  showScreen('gameScreen');
  initGame();
  requestAnimationFrame(loop);
};
document.getElementById('rematchBtn').onclick = ()=>{
  showScreen('gameScreen'); initGame(); requestAnimationFrame(loop);
};
document.getElementById('menuBtn').onclick = ()=> showScreen('startScreen');
</script>
</body>
</html>
