<script>
const AC = window.AudioContext || window.webkitAudioContext;
let actx;
function beep(f=440,d=0.1,t='sine',v=0.1){
  if(!actx) return;
  const o=actx.createOscillator(),g=actx.createGain();
  o.type=t;o.frequency.value=f;g.gain.value=v;
  o.connect(g);g.connect(actx.destination);
  o.start();g.gain.exponentialRampToValueAtTime(0.001,actx.currentTime+d);
  o.stop(actx.currentTime+d);
}

function terrainY(x){
  return Math.sin(x*0.008)*60 + Math.sin(x*0.021)*30 + Math.sin(x*0.005)*80 + Math.cos(x*0.013)*25;
}
function terrainSlope(x){
  const e=1; return (terrainY(x+e)-terrainY(x-e))/(2*e);
}

class Car {
  constructor(color){
    this.color=color;
    this.reset();
  }
  reset(){
    this.x=50; this.y=0; this.vx=0; this.vy=0;
    this.angle=0; this.wheelAngle=0;
    this.fuel=100; this.gas=0; this.brake=0;
    this.dead=false; this.distance=0; this.maxX=50;
    this.airTime=0;
  }
  update(dt){
    if(this.dead) return;
    const groundY=terrainY(this.x);
    const slope=terrainSlope(this.x);
    const targetAngle=Math.atan(slope);
    const onGround=this.y<=groundY+2;

    // gravity
    this.vy+=600*dt;

    if(onGround){
      this.airTime=0;
      this.y=groundY;
      // align angle gradually
      let diff=targetAngle-this.angle;
      while(diff>Math.PI)diff-=Math.PI*2;
      while(diff<-Math.PI)diff+=Math.PI*2;
      this.angle+=diff*Math.min(1,dt*10);

      // engine force along slope
      if(this.fuel>0){
        if(this.gas){
          const force=380;
          this.vx+=Math.cos(this.angle)*force*dt;
          this.vy+=Math.sin(this.angle)*force*dt*0.3;
          this.fuel-=dt*1.2;
        }
        if(this.brake){
          const force=300;
          this.vx-=Math.cos(this.angle)*force*dt;
          this.fuel-=dt*0.8;
        }
      }
      // friction
      this.vx*=Math.pow(0.5,dt);
      // gravity along slope
      this.vx+=Math.sin(this.angle)*400*dt;
      this.vy=0;
    } else {
      this.airTime+=dt;
      // air rotation control
      if(this.gas) this.angle-=dt*2.5;
      if(this.brake) this.angle+=dt*2.5;
    }

    this.wheelAngle+=this.vx*dt*0.1;
    this.x+=this.vx*dt;
    if(!onGround) this.y+=this.vy*dt;
    if(this.y<groundY) this.y=groundY;

    if(this.x<20){this.x=20;this.vx=Math.max(0,this.vx);}
    if(this.x>this.maxX){ this.maxX=this.x; }
    this.distance=Math.floor(this.maxX/10);

    // flip check
    let a=this.angle;
    while(a>Math.PI)a-=Math.PI*2;
    while(a<-Math.PI)a+=Math.PI*2;
    if(Math.abs(a)>Math.PI*0.75 && onGround){
      this.dead=true; this.deadReason='flipped'; beep(120,0.4,'sawtooth',0.2);
    }
    if(this.fuel<=0 && Math.abs(this.vx)<5 && onGround){
      this.dead=true; this.deadReason='no fuel'; beep(150,0.3,'square',0.15);
    }
  }
  draw(ctx,camX,camY,W,H){
    // background sky gradient drawn outside
    // draw terrain
    ctx.fillStyle='#3a8a3a';
    ctx.beginPath();
    ctx.moveTo(0,H);
    for(let sx=0;sx<=W;sx+=4){
      const wx=sx+camX;
      const wy=terrainY(wx);
      const sy=H/2-(wy-camY);
      ctx.lineTo(sx,sy);
    }
    ctx.lineTo(W,H);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle='#2a6a2a';
    ctx.lineWidth=3;
    ctx.beginPath();
    for(let sx=0;sx<=W;sx+=4){
      const wx=sx+camX;
      const wy=terrainY(wx);
      const sy=H/2-(wy-camY);
      if(sx===0)ctx.moveTo(sx,sy); else ctx.lineTo(sx,sy);
    }
    ctx.stroke();

    // distance markers
    ctx.fillStyle='#fff';
    ctx.font='12px sans-serif';
    for(let m=0;m<=4000;m+=500){
      const sx=m-camX;
      if(sx>-20&&sx<W+20){
        const wy=terrainY(m);
        const sy=H/2-(wy-camY);
        ctx.fillRect(sx-1,sy-30,2,30);
        ctx.fillText((m/10)+'m',sx+3,sy-15);
      }
    }

    // car
    const csx=this.x-camX;
    const csy=H/2-(this.y-camY);
    ctx.save();
    ctx.translate(csx,csy-12);
    ctx.rotate(-this.angle);
    // body
    ctx.fillStyle=this.color;
    ctx.fillRect(-22,-10,44,14);
    ctx.fillStyle='#222';
    ctx.fillRect(-14,-18,22,10);
    // wheels
    ctx.fillStyle='#111';
    ctx.beginPath(); ctx.arc(-15,8,7,0,Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(15,8,7,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='#888'; ctx.lineWidth=2;
    ctx.beginPath();ctx.moveTo(-15,8);ctx.lineTo(-15+Math.cos(this.wheelAngle)*5,8+Math.sin(this.wheelAngle)*5);ctx.stroke();
    ctx.beginPath();ctx.moveTo(15,8);ctx.lineTo(15+Math.cos(this.wheelAngle)*5,8+Math.sin(this.wheelAngle)*5);ctx.stroke();
    ctx.restore();

    if(this.dead){
      ctx.fillStyle='rgba(0,0,0,0.6)';
      ctx.fillRect(0,0,W,H);
      ctx.fillStyle='#ff5555';
      ctx.font='bold 26px sans-serif';
      ctx.textAlign='center';
      ctx.fillText('CRASHED ('+this.deadReason+')',W/2,H/2-10);
      ctx.fillStyle='#fff';
      ctx.font='16px sans-serif';
      ctx.fillText(this.distance+'m',W/2,H/2+18);
      ctx.textAlign='left';
    }
  }
}

const cars=[new Car('#3aa0ff'), new Car('#ff4a4a')];
const canvases=[document.getElementById('c1'),document.getElementById('c2')];
const ctxs=canvases.map(c=>c.getContext('2d'));

function resize(){
  canvases.forEach(c=>{
    c.width=c.clientWidth*devicePixelRatio;
    c.height=c.clientHeight*devicePixelRatio;
    c.getContext('2d').setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);
  });
}
window.addEventListener('resize',resize);
resize();

function bindBtn(id,player,key){
  const el=document.getElementById(id);
