  el.addEventListener('touchstart',e=>{e.preventDefault();set(1);if(!actx){actx=new AC();}},{passive:false});
  el.addEventListener('touchend',e=>{e.preventDefault();set(0);},{passive:false});
  el.addEventListener('touchcancel',e=>{e.preventDefault();set(0);},{passive:false});
  el.addEventListener('mousedown',e=>{set(1);if(!actx){actx=new AC();}});
  el.addEventListener('mouseup',()=>set(0));
  el.addEventListener('mouseleave',()=>set(0));
}
bindBtn('b1g',0,'gas');bindBtn('b1b',0,'brake');
bindBtn('b2g',1,'gas');bindBtn('b2b',1,'brake');

let running=false, last=0, engineT=0;
function loop(t){
  const dt=Math.min(0.033,(t-last)/1000||0);
  last=t;
  if(running){
    cars.forEach(c=>c.update(dt));
    engineT+=dt;
    if(engineT>0.08){
      engineT=0;
      cars.forEach((c,i)=>{ if(c.gas&&!c.dead&&c.fuel>0) beep(80+Math.abs(c.vx)*0.6,0.05,'sawtooth',0.03); });
    }
    // check end
    if(cars[0].dead && cars[1].dead){
      running=false;
      const o=document.getElementById('overlay');
      let txt;
      if(cars[0].distance>cars[1].distance) txt='🔵 Player 1 wins! '+cars[0].distance+'m vs '+cars[1].distance+'m';
      else if(cars[1].distance>cars[0].distance) txt='🔴 Player 2 wins! '+cars[1].distance+'m vs '+cars[0].distance+'m';
      else txt="It's a tie! "+cars[0].distance+'m';
      document.getElementById('winText').textContent=txt;
      document.getElementById('startBtn').textContent='REMATCH';
      o.style.display='flex';
      beep(660,0.2);setTimeout(()=>beep(880,0.3),200);
    }
  }
  // draw
  cars.forEach((c,i)=>{
    const ctx=ctxs[i];
    const W=canvases[i].clientWidth, H=canvases[i].clientHeight;
    // sky
    const g=ctx.createLinearGradient(0,0,0,H);
    g.addColorStop(0,'#87ceeb');g.addColorStop(1,'#cfe8f5');
    ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    // clouds
    ctx.fillStyle='rgba(255,255,255,0.7)';
    for(let k=0;k<5;k++){
      const cx=((k*300-c.x*0.3)%(W+200)+W+200)%(W+200)-100;
      ctx.beginPath();ctx.arc(cx,40+k*15,20,0,Math.PI*2);ctx.arc(cx+18,40+k*15,16,0,Math.PI*2);ctx.fill();
    }
    const camX=c.x-W*0.3;
    const camY=c.y-20;
    c.draw(ctx,camX,camY,W,H);
    document.getElementById('d'+(i+1)).textContent=c.distance+'m';
    document.getElementById('f'+(i+1)).textContent='⛽'+Math.max(0,Math.ceil(c.fuel));
  });
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

document.getElementById('startBtn').addEventListener('click',()=>{
  if(!actx){try{actx=new AC();}catch(e){}}
  cars.forEach(c=>c.reset());
  document.getElementById('overlay').style.display='none';
  running=true;
  beep(440,0.1);setTimeout(()=>beep(660,0.15),120);
});
</script>
</body>
