#dmgIndicator{position:absolute;top:0;left:0;width:100%;height:100%;box-shadow:inset 0 0 200px rgba(255,0,0,0);transition:box-shadow 0.3s;pointer-events:none}
#weapons{position:absolute;bottom:20px;right:20px;display:flex;flex-direction:column;gap:6px}
.weapon{background:rgba(0,0,0,0.7);padding:8px 14px;border:2px solid #444;border-radius:5px;color:#aaa;font-weight:bold;font-size:13px;pointer-events:auto;cursor:pointer}
.weapon.active{border-color:#0f0;color:#0f0;box-shadow:0 0 10px #0f0}
#weaponName{position:absolute;bottom:30px;left:50%;transform:translateX(-50%);font-size:22px;font-weight:bold;color:#fff;text-shadow:0 0 6px #000}
#startScreen,#gameOver{position:fixed;inset:0;background:linear-gradient(135deg,#1a0000,#000);z-index:100;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}
#startScreen h1,#gameOver h1{font-size:64px;background:linear-gradient(45deg,#ff3300,#ffcc00);-webkit-background-clip:text;-webkit-text-fill-color:transparent;margin-bottom:20px;letter-spacing:4px}
#startScreen p{font-size:18px;margin:8px;color:#ccc;max-width:600px}
.btn{margin-top:30px;padding:14px 40px;font-size:20px;background:linear-gradient(45deg,#ff3300,#ff6600);color:#fff;border:none;border-radius:8px;cursor:pointer;font-weight:bold;letter-spacing:2px;box-shadow:0 4px 20px rgba(255,51,0,0.6)}
.btn:hover{transform:scale(1.05)}
#gameOver{display:none}
.controls{margin-top:20px;background:rgba(255,255,255,0.05);padding:15px 25px;border-radius:10px;border:1px solid #333}
.controls span{color:#0f0;font-weight:bold}
#killFeed{position:absolute;top:60px;right:15px;font-size:14px;text-align:right}
.kill{background:rgba(0,0,0,0.6);padding:5px 10px;margin-bottom:4px;border-left:3px solid #f33;animation:fade 4s forwards}
@keyframes fade{0%,70%{opacity:1}100%{opacity:0}}
</style>
