<body>
<div id="startScreen">
<h1>⚡ BATTLE STRIKE 3D ⚡</h1>
<p>Survive the warzone. Eliminate enemies. Switch weapons. Use scope for long range.</p>
<div class="controls">
<p><span>WASD</span> Move | <span>MOUSE</span> Aim | <span>CLICK</span> Shoot | <span>RIGHT CLICK</span> Scope</p>
<p><span>1-5</span> Switch Weapon | <span>R</span> Reload | <span>SHIFT</span> Sprint | <span>SPACE</span> Jump</p>
</div>
<button class="btn" id="startBtn">START MISSION</button>
</div>
<div id="gameOver">
<h1>MISSION FAILED</h1>
<p id="finalScore">Kills: 0</p>
<button class="btn" id="restartBtn">RESPAWN</button>
</div>
<div id="hud">
<div id="topbar">
<div class="stat" id="health">❤ HP: 100</div>
<div class="stat" id="score">💀 Kills: 0</div>
<div class="stat" id="ammo">🔫 30/90</div>
</div>
<div id="crosshair"></div>
<div id="scopeOverlay"></div>
<div id="hitMarker">✕</div>
<div id="dmgIndicator"></div>
<div id="weaponName">AK-47</div>
<div id="weapons"></div>
<div id="killFeed"></div>
</div>

<script type="importmap">
{"imports":{"three":"https://unpkg.com/three@0.160.0/build/three.module.js"}}
