      }
    }
    if(player.y>cv.height){ state.lives--; updateHUD(); player.x=80;player.y=200;player.vy=0; if(state.lives<=0)gameOver(); }

    // orbs collect
    orbs=orbs.filter(o=>{
      o.t+=0.08;
      const dx=(player.x+16)-o.x,dy=(player.y+16)-o.y;
      if(dx*dx+dy*dy<400){state.orbs++;updateHUD();ping(1200);for(let i=0;i<10;i++)particles.push({x:o.x,y:o.y,vx:(Math.random()-.5)*4,vy:(Math.random()-.5)*4,life:30,c:'#ffd86b'});return false;}
      return true;
    });
    if(orbs.length<3){for(let i=0;i<6;i++) orbs.push({x:100+Math.random()*780,y:120+Math.random()*220,r:10,t:Math.random()*6});}

    // enemies
    enemies.forEach(en=>{
      en.x+=en.vx; if(en.x<100||en.x>800)en.vx*=-1;
      if(rect(player,en)){state.lives--;updateHUD();player.vx=-en.vx*6;player.vy=-8;if(state.lives<=0)gameOver();}
    });

    // particles
    particles=particles.filter(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=0.1;p.life--;return p.life>0;});
  }

  function draw(){
    // bg gradient based on emotion
    const grad=ctx.createLinearGradient(0,0,0,cv.height);
    const palettes={joy:['#ffb3d9','#9b6cff','#5fe9ff'],sad:['#3a4d8c','#5670b8','#8fb3d9'],anger:['#5a1a2a','#a83a3a','#ffb347'],curious:['#2a1a5a','#7c3fa6','#c5a8ff']};
    const pal=palettes[state.emotion];
    grad.addColorStop(0,pal[0]);grad.addColorStop(.5,pal[1]);grad.addColorStop(1,pal[2]);
    ctx.fillStyle=grad;ctx.fillRect(0,0,cv.width,cv.height);

    // parallax islands
    ctx.globalAlpha=.4;
    for(let i=0;i<5;i++){ctx.fillStyle='rgba(255,255,255,.2)';ctx.beginPath();ctx.ellipse(120+i*180,120+Math.sin(Date.now()/1000+i)*8,70,18,0,0,Math.PI*2);ctx.fill();}
    ctx.globalAlpha=1;

    // platforms
    for(const p of platforms){
      if(p.kind==='fire'){
        const g=ctx.createLinearGradient(p.x,p.y,p.x,p.y+p.h);
        g.addColorStop(0,'#ffd86b');g.addColorStop(1,'#ff3d3d');ctx.fillStyle=g;
      } else {
        ctx.fillStyle=state.emotion==='joy'?'#7df5c4':'rgba(255,255,255,.85)';
      }
      ctx.fillRect(p.x,p.y,p.w,p.h);
      ctx.fillStyle='rgba(255,255,255,.4)';ctx.fillRect(p.x,p.y,p.w,3);
    }

    // orbs
    for(const o of orbs){
      const yy=o.y+Math.sin(o.t)*4;
      const rg=ctx.createRadialGradient(o.x,yy,1,o.x,yy,18);
      rg.addColorStop(0,'#fff');rg.addColorStop(.4,'#ffd86b');rg.addColorStop(1,'rgba(255,216,107,0)');
      ctx.fillStyle=rg;ctx.beginPath();ctx.arc(o.x,yy,18,0,Math.PI*2);ctx.fill();
    }

    // enemies
    enemies.forEach(en=>{
      ctx.font='28px serif';ctx.fillText('👾',en.x,en.y+22);
    });

    // particles
    for(const p of particles){ctx.fillStyle=p.c;ctx.globalAlpha=p.life/40;ctx.fillRect(p.x,p.y,4,4);}
    ctx.globalAlpha=1;

    // player
    ctx.fillStyle=player.color;
    ctx.shadowColor=player.color;ctx.shadowBlur=20;
    ctx.beginPath();ctx.arc(player.x+17,player.y+17,18,0,Math.PI*2);ctx.fill();
    ctx.shadowBlur=0;
    ctx.font='28px serif';ctx.fillText(player.emoji,player.x+2,player.y+27);
  }

  let running=true;
  function loop(){if(!running)return;update();draw();requestAnimationFrame(loop);}
  loop();

  function startGame(){state.orbs=0;state.lives=3;updateHUD();resetWorld();player.x=80;player.y=200;running=true;document.getElementById('gameCanvas').scrollIntoView({behavior:'smooth',block:'center'});}
  function gameOver(){
    running=false;
    setTimeout(()=>{
      alert('🌟 Your dream fades... Orbs collected: '+state.orbs+'\nThe realm awaits your return!');
      running=true; startGame(); loop();
    },50);
  }

  // audio
  let ac;
  function ping(freq){
    try{
      ac=ac||new (window.AudioContext||window.webkitAudioContext)();
      const o=ac.createOscillator(),g=ac.createGain();
      o.type='sine';o.frequency.value=freq;
      g.gain.value=0.05;g.gain.exponentialRampToValueAtTime(0.0001,ac.currentTime+0.25);
      o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+0.25);
    }catch(e){}
  }

  updateHUD();
</script>
</body>
</html>
