        <button class="win" onclick="battleAction('attack')" ${G.battleEnded?'disabled':''}>🐾 Pounce</button>
        <button class="win" onclick="battleAction('heavy')" ${G.battleEnded?'disabled':''}>💥 Bite (risky)</button>
        <button class="win" onclick="battleAction('flee')" ${G.battleEnded?'disabled':''}>🏃 Flee</button>
      </div>
    </div>
    <div class="fieldset">
      <legend>📜 Combat Log</legend>
      <div class="log">${G.log.slice(0,12).map(l=>"&gt; "+l).join("<br>")}</div>
    </div>`;
}

function shakeEl(id) {
  const el = document.getElementById(id);
  if (el) { el.classList.add("shake","flash"); setTimeout(()=>el.classList.remove("shake","flash"),400); }
}

function battleAction(action) {
  if (G.battleEnded) return;
  const c = G.cat, e = G.enemy;

  if (action === "flee") {
    if (Math.random() < 0.5 + (c.spd - e.spd)*0.05) {
      log(c.name + " fled successfully!");
      beep(400,0.1); G.battleEnded = true;
      G.state = "manage"; render(); return;
    } else {
      log("Couldn't escape!");
    }
  }

  const playerFirst = c.spd >= e.spd ? true : Math.random() < 0.3;
  const acts = [];

  const playerAttack = () => {
    if (e.hp <= 0) return;
    let dmg, hitChance = 0.9, crit = 1;
    if (action === "heavy") { dmg = Math.floor(c.atk * 1.8); hitChance = 0.6; }
    else { dmg = c.atk; }
    if (Math.random() > hitChance) { log(c.name + " missed!"); return; }
    if (Math.random() < 0.15) { crit = 2; }
    dmg = Math.max(1, Math.floor(dmg * crit) - Math.floor(Math.random()*2));
    e.hp = Math.max(0, e.hp - dmg);
    hit();
    shakeEl("enemySide");
    log(c.name + (crit>1?" CRIT! ":" hit ") + e.name + " for " + dmg + "!");
  };

  const enemyAttack = () => {
    if (c.hp <= 0) return;
    if (Math.random() > 0.85) { log(e.name + " missed!"); return; }
    let dmg = Math.max(1, e.atk - Math.floor(Math.random()*2));
    if (Math.random() < 0.1) dmg *= 2;
    c.hp = Math.max(0, c.hp - dmg);
    hit();
    shakeEl("playerSide");
    log(e.name + " bit " + c.name + " for " + dmg + "!");
  };

  if (playerFirst) { playerAttack(); enemyAttack(); }
  else { enemyAttack(); playerAttack(); }

  render();

  if (e.hp <= 0) {
    G.battleEnded = true;
    const gold = 10 + G.floor * 5 + Math.floor(Math.random()*10);
    const xp = 5 + G.floor * 2;
    G.gold += gold;
    c.xp += xp;
    log("🏆 VICTORY! +" + gold + "🪙 +" + xp + " XP");
    beep(700,0.1); setTimeout(()=>beep(900,0.1),100); setTimeout(()=>beep(1200,0.2),200);
    checkLevelUp();
    G.floor++;
    setTimeout(()=>{ G.state = "manage"; render(); }, 1200);
  } else if (c.hp <= 0) {
    G.battleEnded = true;
    log("💀 " + c.name + " has fallen...");
    beep(150,0.5,"sawtooth",0.15);
    setTimeout(()=>{ G.state = "gameover"; render(); }, 1500);
  }
}

function renderGameOver() {
  setTitle("Game Over");
  screen.innerHTML = `
    <div class="center">
      <h2 class="blink">💀 GAME OVER 💀</h2>
      <div class="cat-art">
   /\\_/\\  
  ( x.x ) 
   > _ <  
==========
${G.cat.name} the ${G.cat.breed}
fell on Floor ${G.floor}
Reached Level ${G.cat.level}
==========</div>
      <p>Press F to pay respects.</p>
      <button class="win" onclick="startGame()">↻ Try Again</button>
    </div>`;
}

render();
</script>
</body>
</html>
