  #hint { position: absolute; bottom: 16px; left: 50%; transform: translateX(-50%); color: rgba(255,255,255,0.7); font-size: 13px; text-align:center; z-index:4; pointer-events:none; }
</style>
</head>
<body>
<div id="game">
  <canvas id="cv"></canvas>
  <div class="planks"></div>
  <div id="hud">
    <div class="stars-hud">
      <span class="star-icon" id="s0">★</span>
      <span class="star-icon" id="s1">★</span>
      <span class="star-icon" id="s2">★</span>
    </div>
    <div style="color:#fff; font-size:18px; font-weight:bold;">Level 1</div>
  </div>
  <div id="hint">✂️ Swipe across ropes to cut them</div>
  <div id="msg">
    <h1 id="msgTitle">Level Complete!</h1>
    <p id="msgText">Great job!</p>
    <button id="restart">Play Again</button>
  </div>
</div>
<script>
const canvas = document.getElementById('cv');
const ctx = canvas.getContext('2d');
let W, H, DPR;
function resize(){
  DPR = window.devicePixelRatio || 1;
  W = canvas.clientWidth = window.innerWidth;
  H = canvas.clientHeight = window.innerHeight;
  canvas.width = W * DPR; canvas.height = H * DPR;
  ctx.setTransform(DPR,0,0,DPR,0,0);
}
window.addEventListener('resize', () => { resize(); setupLevel(); });
resize();

// Audio
const AC = window.AudioContext || window.webkitAudioContext;
let audio;
function sfx(freq, dur=0.1, type='sine', vol=0.2){
  try{
    if(!audio) audio = new AC();
    const o = audio.createOscillator(); const g = audio.createGain();
    o.type = type; o.frequency.value = freq;
    g.gain.setValueAtTime(vol, audio.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, audio.currentTime+dur);
    o.connect(g); g.connect(audio.destination);
    o.start(); o.stop(audio.currentTime+dur);
  }catch(e){}
}

// Verlet physics
class Point {
  constructor(x,y,pinned=false){ this.x=x; this.y=y; this.px=x; this.py=y; this.pinned=pinned; }
  update(dt){
    if(this.pinned) return;
    const vx=(this.x-this.px)*0.99, vy=(this.y-this.py)*0.99;
    this.px=this.x; this.py=this.y;
    this.x+=vx; this.y+=vy + 0.5*dt*dt;
  }
}
class Stick {
  constructor(a,b,len){ this.a=a; this.b=b; this.len=len||Math.hypot(a.x-b.x,a.y-b.y); this.cut=false; }
  solve(){
    if(this.cut) return;
    const dx=this.b.x-this.a.x, dy=this.b.y-this.a.y;
    const d=Math.hypot(dx,dy)||0.0001;
    const diff=(d-this.len)/d*0.5;
    const ox=dx*diff, oy=dy*diff;
    if(!this.a.pinned) { this.a.x+=ox; this.a.y+=oy; }
    if(!this.b.pinned) { this.b.x-=ox; this.b.y-=oy; }
  }
}

let ropes=[]; // each rope: {points:[], sticks:[], color}
let candy; // Point
let stars=[]; // {x,y,collected}
let omnom; // {x,y,r,mouth open}
let won=false, lost=false, gameOver=false;
let particles=[];

function makeRope(anchorX, anchorY, target, segments=12){
  const dx=(target.x-anchorX)/segments, dy=(target.y-anchorY)/segments;
  const points=[]; const sticks=[];
  for(let i=0;i<=segments;i++){
    const p = new Point(anchorX+dx*i, anchorY+dy*i, i===0);
    points.push(p);
  }
  // last point: attach to candy by referencing candy point - we'll add stick to candy
  for(let i=0;i<segments;i++){
    sticks.push(new Stick(points[i], points[i+1]));
  }
  return {points, sticks, anchorX, anchorY, attach:null};
}

function setupLevel(){
  ropes=[]; stars=[]; particles=[];
  won=false; lost=false; gameOver=false;
  document.getElementById('msg').style.display='none';
  for(let i=0;i<3;i++) document.getElementById('s'+i).classList.remove('on');

  candy = new Point(W*0.3, H*0.3);

  // Two ropes initially holding candy from different anchors
  const ropeLen1 = H*0.18;
  const ropeLen2 = H*0.18;

  const r1 = makeRopeToCandy(W*0.25, H*0.12, candy, ropeLen1, 10);
  const r2 = makeRopeToCandy(W*0.55, H*0.12, candy, ropeLen2, 10);
  ropes.push(r1, r2);

  // Om Nom at bottom right area
  omnom = { x: W*0.75, y: H*0.78, r: Math.min(W,H)*0.07, mouth:0, happy:0 };

  // Stars - medium difficulty placement
  stars.push({x: W*0.5, y: H*0.45, r: 16, collected:false});
  stars.push({x: W*0.65, y: H*0.6, r: 16, collected:false});
  stars.push({x: W*0.4, y: H*0.7, r: 16, collected:false});
}

function makeRopeToCandy(ax, ay, candyPoint, len, segments){
  const points=[]; const sticks=[];
  const dx=(candyPoint.x-ax)/segments, dy=(candyPoint.y-ay)/segments;
  for(let i=0;i<segments;i++){
    points.push(new Point(ax+dx*i, ay+dy*i, i===0));
  }
  // sticks between rope points
  for(let i=0;i<segments-1;i++){
    sticks.push(new Stick(points[i], points[i+1], len/segments));
  }
  // last stick connects last rope point to candy
  const lastStick = new Stick(points[segments-1], candyPoint, len/segments);
  sticks.push(lastStick);
  return {points, sticks, anchorX:ax, anchorY:ay};
}

// Input - swipe to cut
let lastTouch=null;
function getPos(e){
  const t = e.touches ? e.touches[0] : e;
  const r = canvas.getBoundingClientRect();
  return {x: t.clientX - r.left, y: t.clientY - r.top};
}
let trail=[];
function onStart(e){ e.preventDefault(); lastTouch=getPos(e); trail=[lastTouch]; }
function onMove(e){
  e.preventDefault();
  if(!lastTouch) return;
  const p=getPos(e);
  trail.push(p);
  if(trail.length>10) trail.shift();
  // check segment intersection with each stick
  for(const rope of ropes){
    for(const s of rope.sticks){
      if(s.cut) continue;
      if(segIntersect(lastTouch.x,lastTouch.y,p.x,p.y, s.a.x,s.a.y, s.b.x,s.b.y)){
        s.cut=true;
        sfx(800,0.08,'square',0.15);
        // spawn particles
        const mx=(s.a.x+s.b.x)/2, my=(s.a.y+s.b.y)/2;
        for(let i=0;i<6;i++) particles.push({x:mx,y:my,vx:(Math.random()-0.5)*3,vy:(Math.random()-0.5)*3,life:30,c:'#d4a574'});
      }
    }
  }
  lastTouch=p;
}
function onEnd(e){ lastTouch=null; trail=[]; }
canvas.addEventListener('touchstart', onStart, {passive:false});
canvas.addEventListener('touchmove', onMove, {passive:false});
canvas.addEventListener('touchend', onEnd, {passive:false});
canvas.addEventListener('mousedown', onStart);
canvas.addEventListener('mousemove', e=>{ if(lastTouch) onMove(e); });
canvas.addEventListener('mouseup', onEnd);

function segIntersect(x1,y1,x2,y2,x3,y3,x4,y4){
  const d=(x1-x2)*(y3-y4)-(y1-y2)*(x3-x4);
  if(d===0) return false;
  const t=((x1-x3)*(y3-y4)-(y1-y3)*(x3-x4))/d;
  const u=((x1-x3)*(y1-y2)-(y1-y3)*(x1-x2))/d;
  return t>=0 && t<=1 && u>=0 && u<=1;
}

document.getElementById('restart').addEventListener('click', setupLevel);

function update(){
  if(gameOver) return;
  const dt = 1;
  // update candy
  candy.update(dt);
  // bounds for candy
  if(candy.y > H+50){ lose(); }

  // update ropes
  for(const rope of ropes){
    for(const p of rope.points) p.update(dt);
  }
  // solve constraints
  for(let iter=0; iter<8; iter++){
    for(const rope of ropes){
      for(const s of rope.sticks) s.solve();
    }
    // pin anchors
    for(const rope of ropes){
      if(rope.points[0]){ rope.points[0].x=rope.anchorX; rope.points[0].y=rope.anchorY; }
    }
  }

  // collect stars
  for(let i=0;i<stars.length;i++){
    const s=stars[i];
    if(!s.collected){
      const d=Math.hypot(candy.x-s.x, candy.y-s.y);
      if(d < s.r+18){
        s.collected=true;
        document.getElementById('s'+i).classList.add('on');
        sfx(1200,0.15,'sine',0.2);
        sfx(1600,0.15,'sine',0.15);
        for(let k=0;k<10;k++) particles.push({x:s.x,y:s.y,vx:(Math.random()-0.5)*4,vy:(Math.random()-0.5)*4,life:40,c:'#ffd633'});
      }
    }
  }

  // check om nom
  const d = Math.hypot(candy.x-omnom.x, candy.y-omnom.y);
  if(d < omnom.r+18 && !won){ winLevel(); }
  if(d < omnom.r*2.2) omnom.mouth = Math.min(1, omnom.mouth+0.1);
  else omnom.mouth = Math.max(0, omnom.mouth-0.05);

  if(omnom.happy>0) omnom.happy--;

  // particles
  particles.forEach(p=>{p.x+=p.vx; p.y+=p.vy; p.vy+=0.1; p.life--;});
  particles = particles.filter(p=>p.life>0);
}

function winLevel(){
  won=true; gameOver=true;
  sfx(600,0.1); setTimeout(()=>sfx(800,0.1),100); setTimeout(()=>sfx(1200,0.2),200);
  omnom.happy=60;
  const stars = document.querySelectorAll('.star-icon.on').length;
  document.getElementById('msgTitle').textContent = 'Yum! Level Complete!';
  document.getElementById('msgText').textContent = `You earned ${stars} of 3 stars!`;
  setTimeout(()=>{ document.getElementById('msg').style.display='block'; }, 800);
}
function lose(){
  if(lost) return;
  lost=true; gameOver=true;
  sfx(200,0.3,'sawtooth',0.2);
  document.getElementById('msgTitle').textContent = 'Oh no!';
  document.getElementById('msgText').textContent = 'The candy fell! Try again.';
  document.getElementById('msg').style.display='block';
}

function draw(){
  ctx.clearRect(0,0,W,H);

  // anchors
  for(const rope of ropes){
    ctx.fillStyle='#1a0f08';
    ctx.beginPath(); ctx.arc(rope.anchorX, rope.anchorY, 10, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle='#8b6f47';
    ctx.beginPath(); ctx.arc(rope.anchorX, rope.anchorY, 7, 0, Math.PI*2); ctx.fill();
  }

  // stars
  for(const s of stars){
    if(s.collected) continue;
    drawStar(s.x, s.y, 5, s.r, s.r*0.5, '#ffd633');
  }

  // ropes
  for(const rope of ropes){
    for(const s of rope.sticks){
      if(s.cut) continue;
      ctx.strokeStyle='#c9a06b';
      ctx.lineWidth=3;
      ctx.beginPath(); ctx.moveTo(s.a.x, s.a.y); ctx.lineTo(s.b.x, s.b.y); ctx.stroke();
    }
  }

  // Om Nom
  drawOmNom(omnom);

  // candy
  drawCandy(candy.x, candy.y);

  // particles
  for(const p of particles){
    ctx.fillStyle=p.c;
    ctx.globalAlpha = p.life/40;
    ctx.beginPath(); ctx.arc(p.x,p.y,3,0,Math.PI*2); ctx.fill();
  }
  ctx.globalAlpha=1;

  // trail
  if(trail.length>1){
    ctx.strokeStyle='rgba(255,255,255,0.6)';
    ctx.lineWidth=3; ctx.lineCap='round';
    ctx.beginPath();
    ctx.moveTo(trail[0].x, trail[0].y);
    for(let i=1;i<trail.length;i++) ctx.lineTo(trail[i].x, trail[i].y);
    ctx.stroke();
  }
}

function drawStar(cx,cy,spikes,outer,inner,color){
  let rot=Math.PI/2*3, x=cx, y=cy, step=Math.PI/spikes;
  ctx.beginPath(); ctx.moveTo(cx,cy-outer);
  for(let i=0;i<spikes;i++){
    x=cx+Math.cos(rot)*outer; y=cy+Math.sin(rot)*outer; ctx.lineTo(x,y); rot+=step;
    x=cx+Math.cos(rot)*inner; y=cy+Math.sin(rot)*inner; ctx.lineTo(x,y); rot+=step;
  }
  ctx.lineTo(cx,cy-outer); ctx.closePath();
  ctx.fillStyle=color; ctx.shadowColor=color; ctx.shadowBlur=10; ctx.fill();
  ctx.shadowBlur=0;
}

function drawCandy(x,y){
  ctx.save();
  ctx.translate(x,y);
  // wrappers
  ctx.fillStyle='#e74c3c';
  ctx.beginPath(); ctx.moveTo(-22,0); ctx.lineTo(-12,-8); ctx.lineTo(-12,8); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(22,0); ctx.lineTo(12,-8); ctx.lineTo(12,8); ctx.closePath(); ctx.fill();
  // candy body
  ctx.fillStyle='#ff6b5d';
  ctx.beginPath(); ctx.arc(0,0,14,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#c0392b'; ctx.lineWidth=2; ctx.stroke();
  // stripe
  ctx.strokeStyle='#fff'; ctx.lineWidth=2;
  ctx.beginPath(); ctx.moveTo(-8,-5); ctx.lineTo(8,5); ctx.stroke();
  ctx.restore();
}

function drawOmNom(o){
  ctx.save();
  ctx.translate(o.x, o.y);
  const r=o.r;
  const bounce = o.happy>0 ? Math.sin(o.happy*0.5)*3 : 0;
  ctx.translate(0,bounce);
  // body
  ctx.fillStyle='#7ec850';
  ctx.beginPath(); ctx.arc(0,0,r,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#5fa83a';
  ctx.beginPath(); ctx.arc(0,r*0.3,r*0.8,0,Math.PI,false); ctx.fill();
  // eyes
  ctx.fillStyle='#fff';
  ctx.beginPath(); ctx.arc(-r*0.35,-r*0.5,r*0.35,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(r*0.35,-r*0.5,r*0.35,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#000';
  ctx.beginPath(); ctx.arc(-r*0.3,-r*0.45,r*0.15,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(r*0.3,-r*0.45,r*0.15,0,Math.PI*2); ctx.fill();
  // mouth
  ctx.fillStyle='#3a1010';
  const m = 0.15 + o.mouth*0.5;
  ctx.beginPath(); ctx.ellipse(0, r*0.3, r*0.5, r*m, 0, 0, Math.PI*2); ctx.fill();
  if(o.mouth>0.3){
    ctx.fillStyle='#fff';
    ctx.fillRect(-r*0.3, r*0.3-r*m*0.6, r*0.1, r*0.1);
    ctx.fillRect(-r*0.1, r*0.3-r*m*0.6, r*0.1, r*0.1);
    ctx.fillRect(r*0.1, r*0.3-r*m*0.6, r*0.1, r*0.1);
  }
  ctx.restore();
}

function loop(){
  update();
  draw();
  requestAnimationFrame(loop);
}
setupLevel();
loop();
</script>
</body>
</html>
