<script>
// ============ SETUP ============
const cvs = document.getElementById('game');
const ctx = cvs.getContext('2d');
const W = cvs.width, H = cvs.height;

const keys = {};
window.addEventListener('keydown', e => {
  keys[e.key.toLowerCase()] = true;
  if ([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase())) e.preventDefault();
});
window.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });

// touch
document.querySelectorAll('.tbtn').forEach(b=>{
  const k = b.dataset.k;
  const map = {left:'arrowleft', right:'arrowright', jump:' ', dash:'shift', attack:'x'};
  const press = e=>{ e.preventDefault(); keys[map[k]] = true; };
  const rel = e=>{ e.preventDefault(); keys[map[k]] = false; };
  b.addEventListener('touchstart', press);
  b.addEventListener('touchend', rel);
  b.addEventListener('mousedown', press);
  b.addEventListener('mouseup', rel);
  b.addEventListener('mouseleave', rel);
});

// ============ AUDIO ============
let AC = null;
function audio(){ if(!AC) AC = new (window.AudioContext||window.webkitAudioContext)(); return AC; }
function beep(freq, dur=0.1, type='square', vol=0.15){
  try{
    const a = audio();
    const o = a.createOscillator(), g = a.createGain();
    o.type = type; o.frequency.value = freq;
    g.gain.value = vol;
    o.connect(g); g.connect(a.destination);
    o.start(); 
    g.gain.exponentialRampToValueAtTime(0.0001, a.currentTime+dur);
    o.stop(a.currentTime+dur);
  }catch(e){}
}
function sfx(name){
  switch(name){
    case 'jump': beep(520,0.12,'square',0.12); break;
    case 'coin': beep(880,0.08,'triangle',0.18); setTimeout(()=>beep(1320,0.1,'triangle',0.15),60); break;
    case 'hurt': beep(180,0.25,'sawtooth',0.2); break;
    case 'attack': beep(300,0.08,'square',0.13); break;
    case 'kill': beep(200,0.08,'square',0.15); setTimeout(()=>beep(140,0.18,'sawtooth',0.15),50); break;
    case 'power': beep(660,0.1,'triangle',0.2); setTimeout(()=>beep(990,0.15,'triangle',0.2),100); break;
    case 'dash': beep(400,0.1,'sawtooth',0.12); break;
    case 'win': [523,659,784,1047].forEach((f,i)=>setTimeout(()=>beep(f,0.18,'triangle',0.2), i*120)); break;
    case 'lose': [400,300,200,150].forEach((f,i)=>setTimeout(()=>beep(f,0.25,'sawtooth',0.2), i*150)); break;
    case 'checkpoint': beep(700,0.1,'triangle',0.2); setTimeout(()=>beep(880,0.12,'triangle',0.2),80); setTimeout(()=>beep(1100,0.18,'triangle',0.2),160); break;
  }
}

// background music - simple north african style loop
let musicNodes = [];
function startMusic(){
  stopMusic();
  try{
    const a = audio();
    // Bass-ish drone
    const scale = [220, 246.94, 261.63, 293.66, 329.63, 349.23, 392, 440]; // A minor-ish
    const melody = [0,2,3,5,3,2,0,2, 3,5,7,5,3,2,0,-1];
    let step=0;
    const tick = ()=>{
      if(!musicPlaying) return;
      const note = melody[step % melody.length];
      const f = scale[((note%scale.length)+scale.length)%scale.length] * (note>=scale.length?2:1);
      const o = a.createOscillator(), g = a.createGain();
      o.type='triangle'; o.frequency.value = f;
      g.gain.value = 0.0; o.connect(g); g.connect(a.destination);
      const t = a.currentTime;
      g.gain.linearRampToValueAtTime(0.06, t+0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t+0.28);
      o.start(t); o.stop(t+0.3);
      // bass
      if(step%2===0){
        const o2 = a.createOscillator(), g2 = a.createGain();
        o2.type='sine'; o2.frequency.value = scale[0]/2;
        g2.gain.value=0.0; o2.connect(g2); g2.connect(a.destination);
        g2.gain.linearRampToValueAtTime(0.09, t+0.02);
        g2.gain.exponentialRampToValueAtTime(0.0001, t+0.4);
        o2.start(t); o2.stop(t+0.42);
      }
      step++;
    };
    musicInterval = setInterval(tick, 230);
    musicPlaying = true;
  }catch(e){}
}
let musicInterval=null, musicPlaying=false;
function stopMusic(){ musicPlaying=false; if(musicInterval) clearInterval(musicInterval); musicInterval=null; }

