function genCoins(arr){ return arr.map(([x,y])=>({x,y,collected:false,t:Math.random()*Math.PI*2})); }

// ============ PLAYER ============
function newPlayer(){
  return {
    x:60, y:400, w:34, h:48, vx:0, vy:0, onGround:false, facing:1,
    invuln:0, attacking:0, dashCD:0, dashing:0, jumpHeld:false,
    shield:0, boost:0, anim:0
  };
}

// ============ LEVEL INIT ============
function startLevel(idx){
  levelIndex = idx;
  const lvls = buildLevels();
  level = lvls[idx];
  // deep copy moving platforms baseline
  level.platforms.forEach(p=>{ if(p.moving){ p.baseX=p.x; p.baseY=p.y; p.t=Math.random()*Math.PI*2; }});
  player = newPlayer();
  if(checkpointPos && checkpointPos.level === idx){
    player.x = checkpointPos.x; player.y = checkpointPos.y;
  }
  camera = {x:0,y:0};
  particles = [];
  state = 'play';
  if(!musicPlaying) startMusic();
}

// ============ COLLISION ============
function rectsOverlap(a,b){ return a.x<b.x+b.w && a.x+a.w>b.x && a.y<b.y+b.h && a.y+a.h>b.y; }

// ============ UPDATE ============
let sandstormTimer = 0, sandstormActive=false;

function update(){
  if(state!=='play') return;

  // sandstorm
  if(level.hazards && level.hazards.sandstorms){
    sandstormTimer++;
    if(sandstormTimer > 360){ sandstormActive=true; }
    if(sandstormTimer > 540){ sandstormActive=false; sandstormTimer=0; }
  } else sandstormActive=false;

  // player input
  const speed = player.dashing>0 ? 9 : 4.2;
  let ax = 0;
  if(keys['arrowleft']||keys['a']) ax = -1;
  if(keys['arrowright']||keys['d']) ax = 1;
  if(ax!==0){ player.vx = ax * speed; player.facing = ax; }
  else { player.vx *= 0.78; if(Math.abs(player.vx)<0.1) player.vx=0; }

  // sandstorm pushes left
  if(sandstormActive) player.vx -= 1.4;

  // jump
  const jump = keys[' ']||keys['arrowup']||keys['w'];
  if(jump && player.onGround && !player.jumpHeld){
    player.vy = player.boost>0 ? -16 : -13;
    player.onGround=false; player.jumpHeld=true; sfx('jump');
  }
  if(!jump) player.jumpHeld=false;

  // dash
  if((keys['shift']) && player.dashCD<=0 && player.dashing<=0){
    player.dashing = 14; player.dashCD = 50; player.invuln = Math.max(player.invuln, 14); sfx('dash');
  }
  if(player.dashing>0) player.dashing--;
  if(player.dashCD>0) player.dashCD--;

  // attack
  if((keys['x']||keys['j']) && player.attacking<=0){
    player.attacking = 18; sfx('attack');
  }
  if(player.attacking>0) player.attacking--;

  // power timers
  if(player.boost>0) player.boost--;
  if(player.shield>0) player.shield--;
  if(player.invuln>0) player.invuln--;

  // gravity
  player.vy += level.gravity;
  if(player.vy>16) player.vy=16;

  // movement & collisions with platforms (axis separated)
  // update moving platforms
  level.platforms.forEach(p=>{
    if(p.moving){
      p.t += 0.02 * p.moving.speed;
      if(p.moving.axis==='x'){ p.x = p.baseX + Math.sin(p.t)*p.moving.range; }
      else { p.y = p.baseY + Math.sin(p.t)*p.moving.range; }
    }
  });

  player.x += player.vx;
  collideAxis('x');
  player.y += player.vy;
  player.onGround = false;
  collideAxis('y');

  // bounds
  if(player.x<0) player.x=0;
  if(player.x+player.w>level.width) player.x=level.width-player.w;
  if(player.y>H+200){ damage(999); }

  // crates - solid
  if(level.crates){
    level.crates.forEach(c=>{
      if(c.broken) return;
      if(rectsOverlap(player,c)){
        // resolve simple - push out vertically if moving down
        if(player.vy>0 && player.y+player.h - player.vy <= c.y+2){
          player.y = c.y - player.h; player.vy=0; player.onGround=true;
        } else if(player.vy<0 && player.y - player.vy >= c.y+c.h-2){
          player.y = c.y+c.h; player.vy=0.5;
        } else if(player.vx>0){ player.x = c.x - player.w; player.vx=0; }
        else if(player.vx<0){ player.x = c.x + c.w; player.vx=0; }
      }
      // attack breaks crate
      if(player.attacking>0){
        const ar = attackRect();
        if(rectsOverlap(ar,c)){ c.broken=true; addParticles(c.x+c.w/2, c.y+c.h/2, '#a0651e', 14); totalScore+=20; sfx('kill'); }
      }
    });
  }

  // coins
  level.coins.forEach(c=>{
    if(c.collected) return;
    c.t += 0.1;
    const cr = {x:c.x-10,y:c.y-10,w:20,h:20};
    if(rectsOverlap(player,cr)){
      c.collected=true; totalCoins++; totalScore+=10; sfx('coin');
      addParticles(c.x,c.y,'#ffd84a',6);
    }
  });

  // powerups
  level.powerups.forEach(p=>{
    if(p.taken) return;
    const pr = {x:p.x-14,y:p.y-14,w:28,h:28};
    if(rectsOverlap(player,pr)){
      p.taken=true; sfx('power');
      if(p.type==='babouche'){ player.boost=420; }
      else { player.shield=480; }
      addParticles(p.x,p.y,'#ff66cc',16);
      totalScore+=50;
    }
  });

  // enemies
  level.enemies.forEach(e=>{
    if(e.dead) return;
    if(e.type==='beetle'){
      e.x += e.dir*1.2;
      if(e.x<e.range[0]) e.dir=1;
      if(e.x>e.range[1]) e.dir=-1;
    } else if(e.type==='pigeon'){
      e.x += e.dir*2.2;
      e.y = e.baseY + Math.sin(e.x*0.02)*22;
      if(e.x<e.range[0]) e.dir=1;
      if(e.x>e.range[1]) e.dir=-1;
    } else if(e.type==='bandit'){
      e.x += e.dir*1.8;
      if(e.x<e.range[0]) e.dir=1;
      if(e.x>e.range[1]) e.dir=-1;
    }
    const er = enemyRect(e);
    // attack
    if(player.attacking>0){
      const ar = attackRect();
      if(rectsOverlap(ar,er)){
        e.dead=true; totalScore+=100; sfx('kill');
        addParticles(er.x+er.w/2,er.y+er.h/2,'#ff5050',16);
      }
    }
    // stomp
    if(rectsOverlap(player,er)){
      if(player.vy>2 && player.y+player.h - er.y < 22){
        e.dead=true; player.vy=-9; totalScore+=80; sfx('kill');
        addParticles(er.x+er.w/2,er.y+er.h/2,'#ff5050',12);
      } else if(player.dashing>0){
        e.dead=true; totalScore+=80; sfx('kill');
        addParticles(er.x+er.w/2,er.y+er.h/2,'#ff5050',12);
      } else {
        damage(1);
      }
    }
  });

  // boss
  if(level.boss && !level.boss.dead){
    updateBoss(level.boss);
  }

  // checkpoint
  if(level.checkpoint && !level.checkpoint.taken){
    const cr = {x:level.checkpoint.x-20,y:level.checkpoint.y-50,w:40,h:80};
    if(rectsOverlap(player,cr)){
      level.checkpoint.taken=true;
      checkpointPos = {level:levelIndex,x:level.checkpoint.x,y:level.checkpoint.y-50};
      sfx('checkpoint');
      addParticles(level.checkpoint.x,level.checkpoint.y-30,'#5fff90',24);
    }
  }

  // goal
  if(level.goal){
    const gr = {x:level.goal.x-20,y:level.goal.y-60,w:50,h:80};
    if(rectsOverlap(player,gr)){ finishLevel(); }
  } else if(level.boss && level.boss.dead && level.boss.deadTimer>120){
    finishLevel(true);
  }

  // camera
  camera.x = player.x - W/2 + player.w/2;
  if(camera.x<0) camera.x=0;
  if(camera.x>level.width-W) camera.x = level.width-W;

  // particles
  particles.forEach(p=>{ p.x+=p.vx; p.y+=p.vy; p.vy+=0.2; p.life--; });
  particles = particles.filter(p=>p.life>0);

  player.anim++;
}

function attackRect(){
  const reach = 38;
  return {x: player.facing>0? player.x+player.w : player.x-reach, y:player.y+8, w:reach, h:player.h-12};
}

function enemyRect(e){
  if(e.type==='beetle') return {x:e.x-18,y:e.y-14,w:36,h:24};
  if(e.type==='pigeon') return {x:e.x-18,y:e.y-12,w:36,h:24};
  if(e.type==='bandit') return {x:e.x-16,y:e.y-32,w:32,h:48};
  return {x:e.x,y:e.y,w:20,h:20};
}

function collideAxis(axis){
  level.platforms.forEach(p=>{
    if(rectsOverlap(player,p)){
      if(axis==='x'){
        if(player.vx>0) player.x = p.x - player.w;
        else if(player.vx<0) player.x = p.x + p.w;
        player.vx=0;
      } else {
        if(player.vy>0){ player.y = p.y - player.h; player.vy=0; player.onGround=true; }
        else if(player.vy<0){ player.y = p.y + p.h; player.vy=0.5; }
      }
    }
  });
}

function damage(amt){
  if(player.invuln>0) return;
  if(player.shield>0){ player.shield=0; player.invuln=60; sfx('hurt'); addParticles(player.x+player.w/2,player.y+player.h/2,'#ffd84a',16); return; }
  lives--; sfx('hurt'); player.invuln=90;
  player.vy=-8; player.vx = -player.facing*5;
  if(lives<=0){
    state='gameover';
    document.getElementById('goStats').textContent = `Punteggio: ${totalScore} | Dinar: ${totalCoins}`;
    document.getElementById('gameOver').classList.remove('hidden');
    stopMusic(); sfx('lose');
  }
}

// ============ BOSS ============
function updateBoss(b){
  if(!b.state){ b.state='idle'; b.timer=0; b.cooldown=120; b.deadTimer=0; b.shakes=[]; }
  b.timer++;
  // move toward player slowly
  const dir = Math.sign((player.x+player.w/2)-(b.x));
  b.x += dir*0.8;
  // periodic jump
  if(!b.vy) b.vy=0;
  b.y += b.vy; b.vy += 0.5;
  if(b.y>380){ b.y=380; b.vy=0; }
  b.cooldown--;
  if(b.cooldown<=0){
    b.vy=-13; b.cooldown=100;
    // spawn shockwave projectiles
    if(!b.proj) b.proj=[];
    b.proj.push({x:b.x,y:380,vx:-4},{x:b.x,y:380,vx:4});
  }
  if(b.proj){
    b.proj.forEach(pr=>{ pr.x+=pr.vx; });
    b.proj = b.proj.filter(pr=> pr.x>0 && pr.x<level.width);
    b.proj.forEach(pr=>{
      const pr2 = {x:pr.x-12,y:pr.y-12,w:24,h:24};
      if(rectsOverlap(player,pr2)) damage(1);
    });
  }
  // boss hitbox
  const br = {x:b.x-44,y:b.y-60,w:88,h:90};
  if(player.attacking>0){
    const ar = attackRect();
    if(rectsOverlap(ar,br) && !b.hitCd){
      b.hp--; b.hitCd=30; addParticles(b.x,b.y-30,'#ff5050',18); sfx('kill');
      totalScore+=50;
      if(b.hp<=0){ b.dead=true; b.deadTimer=0; sfx('win'); }
    }
  }
  if(b.hitCd) b.hitCd--;
  if(b.dead){
    b.deadTimer++;
    if(b.deadTimer%10===0) addParticles(b.x+(Math.random()-0.5)*60,b.y-30+(Math.random()-0.5)*60,'#ffd84a',6);
  }
  if(!b.dead && rectsOverlap(player,br)) damage(1);
}

function addParticles(x,y,color,n){
  for(let i=0;i<n;i++){
    particles.push({x,y,vx:(Math.random()-0.5)*5,vy:(Math.random()-0.5)*5-2,life:30+Math.random()*20,color});
  }
}

function finishLevel(boss=false){
  state='levelend';
  stopMusic();
  sfx('win');
  checkpointPos=null;
  const lvls = buildLevels();
  if(levelIndex>=lvls.length-1){
    state='win';
    document.getElementById('winStats').textContent = `Punteggio Finale: ${totalScore} | Dinar: ${totalCoins}`;
    document.getElementById('win').classList.remove('hidden');
    return;
  }
  document.getElementById('leTitle').textContent = `Livello ${levelIndex+1} Completato!`;
  document.getElementById('leStats').textContent = `Punteggio: ${totalScore} | Dinar: ${totalCoins} | Vite: ${lives}`;
  document.getElementById('levelEnd').classList.remove('hidden');
}

// ============ DRAWING ============
function drawSky(){
  const themes = {
    medina: ['#f5c97a','#e88a4d'],
    souk: ['#e8b56a','#c66a3a'],
    desert: ['#ffd98a','#e87a3a'],
    oasis: ['#9cd6f0','#e0c97a'],
    boss: ['#3a1a30','#8a3a4a']
  };
  const c = themes[level.theme] || themes.medina;
  const g = ctx.createLinearGradient(0,0,0,H);
  g.addColorStop(0,c[0]); g.addColorStop(1,c[1]);
  ctx.fillStyle=g; ctx.fillRect(0,0,W,H);
  // sun
  ctx.fillStyle='rgba(255,240,180,0.8)';
  ctx.beginPath(); ctx.arc(W-110,90,46,0,Math.PI*2); ctx.fill();
}

function drawBackground(){
  // distant silhouettes parallax
  const px = camera.x*0.3;
  if(level.theme==='medina' || level.theme==='souk'){
    ctx.fillStyle='rgba(180,90,40,0.55)';
    for(let i=0;i<14;i++){
      const x = i*220 - (px%220);
      const h = 110 + (i%3)*40;
      ctx.fillRect(x,H-160-h,160,h);
      // dome
      ctx.beginPath(); ctx.arc(x+80, H-160-h, 40, Math.PI, 0); ctx.fill();
      // minaret
      if(i%3===1){
        ctx.fillRect(x+70,H-160-h-90,20,90);
        ctx.beginPath(); ctx.arc(x+80,H-160-h-90,16,Math.PI,0); ctx.fill();
      }
    }
    // closer buildings
    const px2 = camera.x*0.55;
    ctx.fillStyle='rgba(220,140,70,0.75)';
    for(let i=0;i<12;i++){
      const x = i*280 - (px2%280);
      const h = 160 + (i%4)*30;
      ctx.fillRect(x,H-120-h,200,h);
      ctx.fillStyle='rgba(60,30,10,0.5)';
      // windows arches
      for(let j=0;j<3;j++){
        const wx = x+25+j*55, wy = H-120-h+40;
        ctx.beginPath(); ctx.moveTo(wx,wy+24); ctx.lineTo(wx,wy+8); ctx.arc(wx+12,wy+8,12,Math.PI,0); ctx.lineTo(wx+24,wy+24); ctx.closePath(); ctx.fill();
      }
      ctx.fillStyle='rgba(220,140,70,0.75)';
    }
  } else if(level.theme==='desert' || level.theme==='oasis'){
    // dunes
    ctx.fillStyle='rgba(230,180,100,0.6)';
    for(let i=0;i<10;i++){
      const x = i*300 - (px%300);
      ctx.beginPath();
      ctx.moveTo(x,H-160);
      ctx.quadraticCurveTo(x+150,H-280,x+300,H-160);
      ctx.lineTo(x+300,H); ctx.lineTo(x,H); ctx.closePath(); ctx.fill();
    }
    if(level.theme==='oasis'){
      // palm trees
      const px2 = camera.x*0.6;
      for(let i=0;i<6;i++){
        const x = i*420 - (px2%420) + 100;
        drawPalm(x, H-160);
      }
    } else {
      // pyramid/ruin
      ctx.fillStyle='rgba(190,140,70,0.7)';
      for(let i=0;i<5;i++){
        const x = i*500 - (px%500);
        ctx.beginPath(); ctx.moveTo(x,H-160); ctx.lineTo(x+90,H-260); ctx.lineTo(x+180,H-160); ctx.closePath(); ctx.fill();
      }
    }
  } else if(level.theme==='boss'){
    // dark souk interior
    ctx.fillStyle='rgba(40,20,30,0.6)';
    ctx.fillRect(0,0,W,H);
    ctx.fillStyle='rgba(255,180,60,0.15)';
    for(let i=0;i<8;i++){
      const x = i*140 - (px%140);
      ctx.beginPath(); ctx.arc(x+50,H-180,40,Math.PI,0); ctx.fill();
    }
  }
}

function drawPalm(x,baseY){
  ctx.fillStyle='#6b3a1a';
  ctx.fillRect(x-6,baseY-80,12,80);
  ctx.fillStyle='#2d8a3a';
  for(let i=0;i<6;i++){
    const a = i*(Math.PI/3) - Math.PI/2;
    ctx.beginPath();
    ctx.ellipse(x+Math.cos(a)*30,baseY-80+Math.sin(a)*15,35,10,a,0,Math.PI*2);
    ctx.fill();
  }
}

function drawGround(){
  // platforms
  level.platforms.forEach(p=>{
    const x = p.x - camera.x;
    if(x+p.w<0 || x>W) return;
    if(p.h>30){
      // ground tile
      ctx.fillStyle = level.theme==='desert'||level.theme==='oasis' ? '#e3b56a' : '#b56a2a';
      ctx.fillRect(x,p.y,p.w,p.h);
      ctx.fillStyle = level.theme==='desert'||level.theme==='oasis' ? '#c79548' : '#8a4818';
      ctx.fillRect(x,p.y,p.w,8);
      // tile lines
      ctx.strokeStyle='rgba(0,0,0,0.15)'; ctx.lineWidth=1;
      for(let i=40;i<p.w;i+=40){ ctx.beginPath(); ctx.moveTo(x+i,p.y); ctx.lineTo(x+i,p.y+p.h); ctx.stroke(); }
    } else {
      // floating platform - carpet style if moving, else stone
      if(p.moving){
        // flying carpet
        ctx.fillStyle='#c8345e';
        ctx.fillRect(x,p.y,p.w,p.h);
        ctx.fillStyle='#ffd84a';
        for(let i=0;i<p.w;i+=12){ ctx.fillRect(x+i,p.y+6,6,2); }
        ctx.fillStyle='#5a1030';
        ctx.fillRect(x,p.y,p.w,3);
        // tassels
        ctx.fillStyle='#ffd84a';
        ctx.fillRect(x-3,p.y+p.h,2,6); ctx.fillRect(x+p.w+1,p.y+p.h,2,6);
      } else {
        ctx.fillStyle='#a85a28';
        ctx.fillRect(x,p.y,p.w,p.h);
        ctx.fillStyle='#7a3a18';
        ctx.fillRect(x,p.y+p.h-4,p.w,4);
      }
    }
  });

  // crates
  if(level.crates) level.crates.forEach(c=>{
    if(c.broken) return;
    const x = c.x - camera.x;
    if(x+c.w<0 || x>W) return;
    ctx.fillStyle='#c98a44';
    ctx.fillRect(x,c.y,c.w,c.h);
    ctx.strokeStyle='#5a3010'; ctx.lineWidth=3;
    ctx.strokeRect(x+1,c.y+1,c.w-2,c.h-2);
    ctx.beginPath(); ctx.moveTo(x,c.y); ctx.lineTo(x+c.w,c.y+c.h); ctx.moveTo(x+c.w,c.y); ctx.lineTo(x,c.y+c.h); ctx.stroke();
  });
}

function drawCoin(c){
  const x = c.x - camera.x, y = c.y;
  if(x<-20||x>W+20) return;
  const sc = Math.abs(Math.sin(c.t));
  ctx.fillStyle='#ffd84a';
  ctx.beginPath(); ctx.ellipse(x,y,10*sc+2,12,0,0,Math.PI*2); ctx.fill();
  ctx.strokeStyle='#a8740a'; ctx.lineWidth=2; ctx.stroke();
  ctx.fillStyle='#a8740a'; ctx.font='bold 11px sans-serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
  if(sc>0.5) ctx.fillText('د',x,y);
}

function drawPowerup(p){
  const x = p.x - camera.x, y = p.y + Math.sin(Date.now()/300)*4;
  if(x<-30||x>W+30) return;
  // glow
  ctx.fillStyle='rgba(255,200,80,0.3)';
  ctx.beginPath(); ctx.arc(x,y,22,0,Math.PI*2); ctx.fill();
  if(p.type==='babouche'){
    // slipper
    ctx.fillStyle='#ffcc44';
    ctx.beginPath(); ctx.ellipse(x,y+6,18,8,0,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='#e07a1f';
    ctx.beginPath(); ctx.moveTo(x-12,y+2); ctx.quadraticCurveTo(x-18,y-8,x-4,y-6); ctx.quadraticCurveTo(x,y-2,x-12,y+2); ctx.fill();
    ctx.strokeStyle='#7a4010'; ctx.lineWidth=1.5; ctx.stroke();
  } else {
    // tajine
    ctx.fillStyle='#d04a2a';
    ctx.beginPath(); ctx.arc(x,y+4,16,Math.PI,Math.PI*2); ctx.fill();
    ctx.fillStyle='#e87a3a';
    ctx.beginPath(); ctx.moveTo(x-16,y+4); ctx.quadraticCurveTo(x,y-22,x+16,y+4); ctx.closePath(); ctx.fill();
    ctx.fillStyle='#7a2010';
    ctx.beginPath(); ctx.arc(x,y-18,4,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='#5a1010'; ctx.lineWidth=2; ctx.beginPath(); ctx.arc(x,y+4,16,Math.PI,Math.PI*2); ctx.stroke();
  }
}

function drawPlayer(){
  const x = player.x - camera.x + player.w/2;
  const y = player.y;
  const flicker = player.invuln>0 && Math.floor(player.invuln/4)%2===0;
  if(flicker) ctx.globalAlpha=0.5;

  // shield
  if(player.shield>0){
    ctx.strokeStyle='rgba(80,200,255,0.7)'; ctx.lineWidth=3;
    ctx.beginPath(); ctx.arc(x,y+24,30,0,Math.PI*2); ctx.stroke();
    ctx.fillStyle='rgba(80,200,255,0.15)'; ctx.fill();
  }

  ctx.save(); ctx.translate(x,y);
  if(player.facing<0) ctx.scale(-1,1);

  const walkBob = player.onGround && Math.abs(player.vx)>0.5 ? Math.sin(player.anim*0.3)*2 : 0;
  // legs
  ctx.fillStyle='#3a4a8a';
  const legSwing = player.onGround && Math.abs(player.vx)>0.5 ? Math.sin(player.anim*0.3)*4 : 0;
  ctx.fillRect(-10, 30, 8, 18-Math.abs(legSwing));
  ctx.fillRect(2, 30, 8, 18-Math.abs(legSwing/2));
  // babouche shoes
  ctx.fillStyle = player.boost>0 ? '#ff66cc' : '#ffcc44';
  ctx.beginPath(); ctx.ellipse(-6,48,7,3,0,0,Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(6,48,7,3,0,0,Math.PI*2); ctx.fill();
  // body - jellaba
  ctx.fillStyle='#f0e8c8';
  ctx.beginPath();
  ctx.moveTo(-13,30); ctx.lineTo(-15,10); ctx.quadraticCurveTo(0,4,15,10); ctx.lineTo(13,30); ctx.closePath();
  ctx.fill();
  ctx.strokeStyle='#a8741a'; ctx.lineWidth=2; ctx.stroke();
  // sash
  ctx.fillStyle='#c8345e'; ctx.fillRect(-14,22,28,5);
  // arms
  ctx.fillStyle='#f0e8c8';
  const armSwing = player.attacking>0 ? 18 : (legSwing/2);
  ctx.save(); ctx.translate(12, 14); ctx.rotate((armSwing)*0.06);
  ctx.fillRect(0,0,7,16); ctx.restore();
  ctx.save(); ctx.translate(-19, 14); ctx.rotate(-(armSwing)*0.06);
  ctx.fillRect(0,0,7,16); ctx.restore();
  // attack effect - scimitar
  if(player.attacking>0){
    ctx.strokeStyle='#fff'; ctx.lineWidth=4;
    ctx.beginPath();
    const ap = 1 - player.attacking/18;
    ctx.arc(18, 18, 22, -Math.PI/2 + ap*Math.PI, Math.PI/3 + ap*Math.PI);
    ctx.stroke();
    ctx.strokeStyle='rgba(255,220,120,0.7)'; ctx.lineWidth=2; ctx.stroke();
  }
  // head
  ctx.fillStyle='#e8b48a';
  ctx.beginPath(); ctx.arc(0, -4+walkBob, 11, 0, Math.PI*2); ctx.fill();
  ctx.strokeStyle='#7a4010'; ctx.lineWidth=1.5; ctx.stroke();
  // chechia (red hat)
  ctx.fillStyle='#c8201a';
  ctx.beginPath();
  ctx.moveTo(-11,-9+walkBob); ctx.quadraticCurveTo(0,-22+walkBob,11,-9+walkBob);
  ctx.closePath(); ctx.fill();
  ctx.strokeStyle='#600'; ctx.stroke();
  // tassel
  ctx.fillStyle='#000'; ctx.fillRect(-1,-22+walkBob,2,4);
  // eyes
  ctx.fillStyle='#fff'; ctx.beginPath(); ctx.arc(3,-4+walkBob,2.5,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#000'; ctx.beginPath(); ctx.arc(4,-4+walkBob,1.5,0,Math.PI*2); ctx.fill();
  // smile
  ctx.strokeStyle='#7a4010'; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.arc(2,0+walkBob,3,0.2,Math.PI-0.2); ctx.stroke();

  ctx.restore();
  ctx.globalAlpha=1;

  // dash trail
  if(player.dashing>0){
    ctx.fillStyle='rgba(255,200,80,0.4)';
    for(let i=1;i<=3;i++) ctx.fillRect(x - player.facing*i*10 - 16, y+8, 32, player.h-12);
  }
}

function drawEnemies(){
  level.enemies.forEach(e=>{
    if(e.dead) return;
    const x = e.x - camera.x, y = e.y;
    if(x<-50||x>W+50) return;
    if(e.type==='beetle'){
      ctx.fillStyle='#2a2a2a';
      ctx.beginPath(); ctx.ellipse(x,y,18,12,0,0,Math.PI*2); ctx.fill();
      ctx.fillStyle='#4a8a3a';
      ctx.beginPath(); ctx.ellipse(x,y-2,15,9,0,0,Math.PI*2); ctx.fill();
      ctx.strokeStyle='#1a3a1a'; ctx.lineWidth=2; ctx.beginPath(); ctx.moveTo(x,y-10); ctx.lineTo(x,y+6); ctx.stroke();
      // legs
      for(let i=-2;i<=2;i++){ if(i===0)continue; ctx.beginPath(); ctx.moveTo(x+i*5,y+10); ctx.lineTo(x+i*5,y+14); ctx.stroke(); }
      // eyes
      ctx.fillStyle='#fff'; ctx.beginPath(); ctx.arc(x-e.dir*-6,y-6,2,0,Math.PI*2); ctx.fill();
      ctx.fillStyle='#000'; ctx.beginPath(); ctx.arc(x-e.dir*-6,y-6,1,0,Math.PI*2); ctx.fill();
    } else if(e.type==='pigeon'){
      ctx.fillStyle='#8a8a9a';
      ctx.beginPath(); ctx.ellipse(x,y,18,11,0,0,Math.PI*2); ctx.fill();
      ctx.fillStyle='#6a6a7a';
      const wf = Math.sin(Date.now()/100)*6;
      ctx.beginPath(); ctx.ellipse(x,y-4+wf*0.3,12,5,0,0,Math.PI*2); ctx.fill();
      ctx.fillStyle='#8a8a9a'; ctx.beginPath(); ctx.arc(x+e.dir*16,y-4,8,0,Math.PI*2); ctx.fill();
      ctx.fillStyle='#e88a1a'; ctx.beginPath(); ctx.moveTo(x+e.dir*22,y-4); ctx.lineTo(x+e.dir*28,y-2); ctx.lineTo(x+e.dir*22,y); ctx.fill();
      ctx.fillStyle='#fff'; ctx.beginPath(); ctx.arc(x+e.dir*18,y-6,2,0,Math.PI*2); ctx.fill();
      ctx.fillStyle='#000'; ctx.beginPath(); ctx.arc(x+e.dir*19,y-6,1,0,Math.PI*2); ctx.fill();
    } else if(e.type==='bandit'){
      ctx.save(); ctx.translate(x,y); if(e.dir<0) ctx.scale(-1,1);
      // body
      ctx.fillStyle='#5a3a7a'; ctx.fillRect(-12,-14,24,28);
      ctx.fillStyle='#3a2a4a'; ctx.fillRect(-12,-14,24,4);
      // legs
      ctx.fillStyle='#2a1a3a'; ctx.fillRect(-10,14,7,12); ctx.fillRect(3,14,7,12);
      // head
      ctx.fillStyle='#e8b48a'; ctx.beginPath(); ctx.arc(0,-22,9,0,Math.PI*2); ctx.fill();
      // mask
      ctx.fillStyle='#2a2a2a'; ctx.fillRect(-9,-25,18,5);
      ctx.fillStyle='#fff'; ctx.beginPath(); ctx.arc(3,-22,1.5,0,Math.PI*2); ctx.fill();
      // turban
      ctx.fillStyle='#8a3a3a'; ctx.beginPath(); ctx.arc(0,-30,8,Math.PI,0); ctx.fill();
      // scimitar
      ctx.strokeStyle='#cccccc'; ctx.lineWidth=3;
      ctx.beginPath(); ctx.moveTo(10,-4); ctx.quadraticCurveTo(22,4,14,16); ctx.stroke();
      ctx.restore();
    }
  });
}

function drawBoss(b){
  const x = b.x - camera.x, y = b.y;
  // shadow
  ctx.fillStyle='rgba(0,0,0,0.3)'; ctx.beginPath(); ctx.ellipse(x,480,50,8,0,0,Math.PI*2); ctx.fill();
  ctx.save(); ctx.translate(x,y);
  if(b.dead){ ctx.rotate(b.deadTimer*0.05); ctx.globalAlpha = Math.max(0,1-b.deadTimer/120); }
  // body big
  ctx.fillStyle='#5a2a1a';
  ctx.fillRect(-40,-50,80,90);
  // belt
  ctx.fillStyle='#ffd84a'; ctx.fillRect(-40,-10,80,10);
  // arms
  ctx.fillStyle='#5a2a1a'; ctx.fillRect(-55,-40,15,60); ctx.fillRect(40,-40,15,60);
  // head
  ctx.fillStyle='#c8946a'; ctx.beginPath(); ctx.arc(0,-65,22,0,Math.PI*2); ctx.fill();
  // turban big
  ctx.fillStyle='#1a3a8a'; ctx.beginPath(); ctx.arc(0,-78,24,Math.PI,0); ctx.fill();
  ctx.fillStyle='#ffd84a'; ctx.fillRect(-8,-90,16,4);
  // beard
  ctx.fillStyle='#fff'; ctx.beginPath(); ctx.arc(0,-55,12,0,Math.PI); ctx.fill();
  // angry eyes
  ctx.fillStyle='#fff'; ctx.beginPath(); ctx.arc(-8,-66,4,0,Math.PI*2); ctx.arc(8,-66,4,0,Math.PI*2); ctx.fill();
  ctx.fillStyle='#c00'; ctx.beginPath(); ctx.arc(-8,-66,2,0,Math.PI*2); ctx.arc(8,-66,2,0,Math.PI*2); ctx.fill();
  // brows
  ctx.strokeStyle='#000'; ctx.lineWidth=3;
  ctx.beginPath(); ctx.moveTo(-14,-72); ctx.lineTo(-4,-68); ctx.moveTo(14,-72); ctx.lineTo(4,-68); ctx.stroke();
  // scimitars
  ctx.strokeStyle='#dde'; ctx.lineWidth=5;
  ctx.beginPath(); ctx.moveTo(-50,0); ctx.quadraticCurveTo(-70,20,-58,40); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(50,0); ctx.quadraticCurveTo(70,20,58,40); ctx.stroke();
  ctx.restore();

  // projectiles
  if(b.proj) b.proj.forEach(pr=>{
    const px = pr.x - camera.x;
    ctx.fillStyle='#ffaa30';
    ctx.beginPath(); ctx.arc(px,pr.y,10,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='#ff5500'; ctx.beginPath(); ctx.arc(px,pr.y,5,0,Math.PI*2); ctx.fill();
  });

  // HP bar
  if(!b.dead){
    const bw = 280;
    ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.fillRect(W/2-bw/2,20,bw,18);
    ctx.fillStyle='#c81818'; ctx.fillRect(W/2-bw/2+2,22,(bw-4)*(b.hp/12),14);
    ctx.strokeStyle='#fff'; ctx.lineWidth=2; ctx.strokeRect(W/2-bw/2,20,bw,18);
    ctx.fillStyle='#fff'; ctx.font='bold 14px sans-serif'; ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('GUARDIANO DEL SOUK', W/2, 29);
  }
}

function drawCheckpoint(){
  if(!level.checkpoint) return;
  const x = level.checkpoint.x - camera.x, y = level.checkpoint.y;
  if(x<-40||x>W+40) return;
  ctx.fillStyle='#5a3a1a'; ctx.fillRect(x-3,y-60,6,60);
  ctx.fillStyle = level.checkpoint.taken ? '#5fff90' : '#cccccc';
  ctx.beginPath(); ctx.moveTo(x+3,y-60); ctx.lineTo(x+30,y-50); ctx.lineTo(x+3,y-40); ctx.closePath(); ctx.fill();
  ctx.strokeStyle='#000'; ctx.lineWidth=1; ctx.stroke();
}

function drawGoal(){
  if(!level.goal) return;
  const x = level.goal.x - camera.x, y = level.goal.y;
  if(x<-50||x>W+50) return;
  // archway
  ctx.fillStyle='#d4a04a';
  ctx.fillRect(x-25,y-60,50,60);
  ctx.fillStyle='#3a1a08';
  ctx.beginPath(); ctx.moveTo(x-18,y); ctx.lineTo(x-18,y-30); ctx.arc(x,y-30,18,Math.PI,0); ctx.lineTo(x+18,y); ctx.closePath(); ctx.fill();
  // flag
  ctx.fillStyle='#c8201a'; ctx.fillRect(x-3,y-100,6,40);
  ctx.fillStyle='#fff'; ctx.beginPath(); ctx.moveTo(x+3,y-100); ctx.lineTo(x+28,y-92); ctx.lineTo(x+3,y-84); ctx.closePath(); ctx.fill();
  ctx.fillStyle='#c8201a'; ctx.beginPath(); ctx.arc(x+12,y-92,3,0,Math.PI*2); ctx.fill();
}

function drawParticles(){
  particles.forEach(p=>{
    ctx.globalAlpha = Math.min(1, p.life/30);
    ctx.fillStyle=p.color;
    ctx.fillRect(p.x-camera.x-2,p.y-2,4,4);
  });
  ctx.globalAlpha=1;
}

function drawSandstorm(){
  if(!sandstormActive) return;
  ctx.fillStyle='rgba(220,170,80,0.45)';
  ctx.fillRect(0,0,W,H);
  for(let i=0;i<80;i++){
    ctx.fillStyle='rgba(255,220,150,0.6)';
    const x = (i*73 + Date.now()*0.5)%W;
    const y = (i*41 + Date.now()*0.3)%H;
    ctx.fillRect(x,y,3,1);
  }
}

function drawHUD(){
  // lives
  ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.fillRect(10,10,150,30);
  ctx.fillStyle='#fff'; ctx.font='bold 16px sans-serif'; ctx.textAlign='left'; ctx.textBaseline='middle';
  ctx.fillText('❤ x '+lives, 20, 25);
  // coins
  ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.fillRect(170,10,150,30);
  ctx.fillStyle='#ffd84a'; ctx.fillText('🪙 '+totalCoins, 180, 25);
  // score
  ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.fillRect(330,10,200,30);
  ctx.fillStyle='#fff'; ctx.fillText('Score: '+totalScore, 340, 25);
  // power bars
  if(player.boost>0){
    ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.fillRect(540,10,150,14);
    ctx.fillStyle='#ff66cc'; ctx.fillRect(542,12,(146)*(player.boost/420),10);
    ctx.fillStyle='#fff'; ctx.font='10px sans-serif'; ctx.fillText('BABOUCHE BOOST',544,18);
  }
  if(player.shield>0){
    ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.fillRect(540,28,150,14);
    ctx.fillStyle='#50c8ff'; ctx.fillRect(542,30,(146)*(player.shield/480),10);
    ctx.fillStyle='#fff'; ctx.font='10px sans-serif'; ctx.fillText('TAJINE SHIELD',544,36);
  }
  // level
  ctx.fillStyle='rgba(0,0,0,0.5)'; ctx.fillRect(W-130,10,120,30);
  ctx.fillStyle='#fff'; ctx.font='bold 14px sans-serif'; ctx.textAlign='center';
  const names=['Medina','Souk','Deserto','Oasi','BOSS'];
  ctx.fillText('Lv.'+(levelIndex+1)+' - '+names[levelIndex], W-70, 25);
}

function render(){
  drawSky();
  drawBackground();
  drawGround();
  drawCheckpoint();
  drawGoal();
  level.coins.forEach(c=>{ if(!c.collected) drawCoin(c); });
  level.powerups.forEach(p=>{ if(!p.taken) drawPowerup(p); });
  drawEnemies();
  if(level.boss) drawBoss(level.boss);
  drawPlayer();
  drawParticles();
  drawSandstorm();
  drawHUD();
}

// ============ MAIN LOOP ============
function loop(){
  if(state==='play'){
    update();
    render();
  }
  requestAnimationFrame(loop);
}

// ============ UI ============
document.getElementById('startBtn').onclick = ()=>{
  audio(); // unlock
  document.getElementById('menu').classList.add('hidden');
  totalScore=0; totalCoins=0; lives=3; checkpointPos=null;
  startLevel(0);
};
document.getElementById('nextBtn').onclick = ()=>{
  document.getElementById('levelEnd').classList.add('hidden');
  startLevel(levelIndex+1);
};
document.getElementById('retryBtn').onclick = ()=>{
  document.getElementById('gameOver').classList.add('hidden');
  totalScore=0; totalCoins=0; lives=3; checkpointPos=null;
  startLevel(0);
};
document.getElementById('winBtn').onclick = ()=>{
  document.getElementById('win').classList.add('hidden');
  totalScore=0; totalCoins=0; lives=3; checkpointPos=null;
  startLevel(0);
};

// initial render
ctx.fillStyle='#1a1208'; ctx.fillRect(0,0,W,H);
loop();
</script>
</body>
</html>
