function playSound(freq, dur=0.15, type='sine') {
  try {
    const ctx = new (window.AudioContext||window.webkitAudioContext)();
    const o = ctx.createOscillator(); const g = ctx.createGain();
    o.type=type; o.frequency.value=freq;
    o.connect(g); g.connect(ctx.destination);
    g.gain.setValueAtTime(0.2, ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime+dur);
    o.start(); o.stop(ctx.currentTime+dur);
  } catch(e){}
}

function showSlide(n) {
  slides.forEach(s => s.classList.remove('active'));
  slides[n].classList.add('active');
  document.getElementById('slideNum').textContent = (n+1)+'/'+total;
  document.getElementById('progress').style.width = ((n+1)/total*100)+'%';
  document.getElementById('prevBtn').disabled = n===0;
  document.getElementById('nextBtn').style.display = n===total-1 ? 'none' : 'inline-block';
  if (n === total-1) showFinal();
}

function changeSlide(dir) {
  const next = current + dir;
  if (next>=0 && next<total) {
    current = next;
    showSlide(current);
    playSound(440, 0.1);
