    check:(g)=>g.flags.foundRelic, reward:{xp:150,gold:200,item:'relic_amulet'}}
};

// ============== HELPERS ==============
function pushLog(type,msg){
  G.log.unshift({type,msg,t:`${G.time.day}日 ${G.time.hour}时`});
  if(G.log.length>50) G.log.pop();
}
function rand(a,b){return Math.floor(Math.random()*(b-a+1))+a;}
function pick(arr){return arr[Math.floor(Math.random()*arr.length)];}

function itemWeight(it){return it.w||1;}
function addItem(it){
  if(G.p.inv.length>=G.p.invMax){pushLog('w','背包已满！');return false;}
  if(G.p.invWeight+itemWeight(it)>G.p.invWeightMax){pushLog('w','负重超限！');return false;}
  G.p.inv.push({...it}); G.p.invWeight += itemWeight(it);
  pushLog('i',`获得 [${RARITY[it.rarity].n}] ${it.n}`);
  if(['rare','epic','legend'].includes(it.rarity) && !G.collection.find(c=>c.id===it.id)){
    G.collection.push({id:it.id,n:it.n,rarity:it.rarity});
    if(G.collection.length>=5) unlockAch('collector');
  }
  return true;
}
function removeItem(idx){
  const it=G.p.inv[idx]; if(!it) return;
  G.p.invWeight -= itemWeight(it);
  G.p.inv.splice(idx,1);
}
function equip(idx){
  const it=G.p.inv[idx]; if(!it||!['weapon','armor','trinket'].includes(it.type)) return;
  const slot=it.type;
  if(G.p.equip[slot]){G.p.inv.push(G.p.equip[slot]); G.p.invWeight += itemWeight(G.p.equip[slot]);}
  G.p.equip[slot]=it;
  G.p.invWeight -= itemWeight(it);
  G.p.inv.splice(idx,1);
  pushLog('i',`装备了 ${it.n}`);
}
function useItem(idx){
  const it=G.p.inv[idx]; if(!it||it.type!=='consume') return;
  if(it.effect.hp){G.p.hp=Math.min(G.p.hpMax,G.p.hp+it.effect.hp); pushLog('h',`使用${it.n}，恢复${it.effect.hp}HP`);}
