  removeItem(idx);
}

function getAtk(){
  let a=G.p.str + (G.p.equip.weapon?.atk||0);
  if(G.p.cls==='mage') a += G.p.int + (G.p.equip.weapon?.int||0);
  if(G.p.cls==='rogue') a += Math.floor(G.p.dex/2);
  return a;
}
function getDef(){return Math.floor(G.p.vit/2)+(G.p.equip.armor?.def||0);}
function getAgi(){return G.p.dex + (G.p.equip.trinket?.agi||0);}

function gainXP(x){
  G.p.xp+=x; pushLog('x',`+${x} 经验`);
  while(G.p.xp>=G.p.xpNext){
    G.p.xp-=G.p.xpNext; G.p.lv++; G.p.xpNext=Math.floor(G.p.xpNext*1.5);
    G.p.hpMax+=12; G.p.mpMax+=6; G.p.hp=G.p.hpMax; G.p.mp=G.p.mpMax;
    G.p.str+=2;G.p.dex+=2;G.p.int+=2;G.p.vit+=2;G.p.lck+=1;
    pushLog('lv',`⭐ 升级！现在是 Lv.${G.p.lv}`);
    SKILLS[G.p.cls].forEach(s=>{
      if(s.lv===G.p.lv && !G.p.skills.includes(s.id)){
        G.p.skills.push(s.id); pushLog('lv',`习得新技能：${s.n}`);
      }
    });
    if(G.p.lv>=10) unlockAch('lv10');
  }
}
function unlockAch(id){
  if(G.achievements.includes(id)) return;
  G.achievements.push(id);
  const a=ACHIEVEMENTS.find(x=>x.id===id);
  pushLog('ach',`🏆 成就解锁：${a.n} - ${a.d}`);
}

function giveQuest(id){
  if(G.quests.active.find(q=>q.id===id)||G.quests.done.includes(id)) return;
  const Q=QUESTS[id]; if(!Q) return;
  G.quests.active.push({id,...JSON.parse(JSON.stringify(Q))});
  pushLog('q',`📜 接受任务：${Q.n}`);
}
function checkQuests(){
  G.quests.active = G.quests.active.filter(q=>{
    const Q=QUESTS[q.id];
    const done = (q.need && q.count>=q.need) || (Q.check && Q.check(G));
    if(done){
      pushLog('q',`✅ 完成任务：${Q.n}`);
      if(Q.reward.xp) gainXP(Q.reward.xp);
      if(Q.reward.gold){G.p.gold+=Q.reward.gold; pushLog('i',`+${Q.reward.gold} 金币`);}
      if(Q.reward.fac) for(const f in Q.reward.fac){G.factions[f]=(G.factions[f]||0)+Q.reward.fac[f]; pushLog('f',`${f}声望 +${Q.reward.fac[f]}`);}
      G.quests.done.push(q.id);
      return false;
    }
    return true;
  });
}

