// ============== COMBAT ==============
function startCombat(enemyKeys){
  const enemies = enemyKeys.map((k,i)=>{
    const e=ENEMIES[k]; const lvScale=1+(REGIONS[LOCATIONS[G.p.loc].region].danger-1)*0.2;
    return {id:i,key:k,n:e.n,hp:Math.floor(e.hp*lvScale),hpMax:Math.floor(e.hp*lvScale),
      atk:Math.floor(e.atk*lvScale),def:e.def,agi:e.agi,el:e.el,xp:e.xp,gold:e.gold,
      status:{},data:e};
  });
  G.combat={enemies, turn:0, target:0, sequence:[], log:[]};
  buildSequence();
  G.combat.log.push(`⚔️ 战斗开始！遭遇 ${enemies.map(e=>e.n).join('、')}`);
  processTurn();
}
function buildSequence(){
  const all=[{type:'p',agi:getAgi()}, ...G.combat.enemies.filter(e=>e.hp>0).map(e=>({type:'e',id:e.id,agi:e.agi}))];
  all.sort((a,b)=>b.agi-a.agi);
  G.combat.sequence=all; G.combat.turn=0;
}
function processTurn(){
  if(!G.combat) return;
  if(G.combat.enemies.every(e=>e.hp<=0)){endCombat(true);return;}
  if(G.p.hp<=0){endCombat(false);return;}
  if(G.combat.turn>=G.combat.sequence.length){
    // tick statuses
    if(G.p.status.poison){G.p.hp-=5; G.combat.log.push('☠️ 你受到中毒伤害 5');}
    G.combat.enemies.forEach(e=>{if(e.hp>0 && e.status.poison){e.hp-=8; G.combat.log.push(`☠️ ${e.n} 中毒 -8`);}});
    G.p.buffs={}; // clear single-turn
    buildSequence();
  }
  const cur=G.combat.sequence[G.combat.turn];
  if(cur.type==='p'){render(); return;} // wait for input
  // enemy turn
  const e=G.combat.enemies.find(x=>x.id===cur.id);
  if(!e||e.hp<=0){G.combat.turn++; return processTurn();}
  setTimeout(()=>enemyAct(e),500);
}
function enemyAct(e){
  if(G.p.buffs.dodge){G.combat.log.push(`💨 你闪避了 ${e.n} 的攻击！`); G.combat.turn++; render(); return processTurn();}
  let dmg = Math.max(1, e.atk + rand(-3,3) - getDef());
  if(G.p.buffs.guard) dmg = Math.floor(dmg/2);
  // smart AI: low hp enemies more aggressive
  if(e.hp<e.hpMax*0.3) dmg = Math.floor(dmg*1.3);
  G.p.hp -= dmg;
  G.combat.log.push(`💢 ${e.n} 攻击你，造成 ${dmg} 点${e.el}伤害`);
  if(e.data.poison && Math.random()<0.3){G.p.status.poison=3; G.combat.log.push('☠️ 你中毒了！');}
  G.combat.turn++; render(); processTurn();
}
function playerSkill(sid){
  if(!G.combat) return;
  const cur=G.combat.sequence[G.combat.turn];
  if(cur.type!=='p') return;
  const S=SKILLS[G.p.cls].find(s=>s.id===sid);
  if(G.p.mp<S.mp){pushLog('w','法力不足'); return;}
  G.p.mp-=S.mp;
  const targets = S.aoe ? G.combat.enemies.filter(e=>e.hp>0) : [G.combat.enemies[G.combat.target]];
  if(S.dmg){
    targets.forEach(t=>{
      let base = getAtk() * S.dmg;
      let mod=1;
      if(COUNTER[S.el]===t.el){mod=1.5; G.combat.log.push('✨ 属性克制！');}
      else if(COUNTER[t.el]===S.el) mod=0.6;
      // execute bonus
      if(sid==='execute' && t.hp<t.hpMax*0.3) mod*=2;
      let dmg=Math.max(1,Math.floor((base-t.def)*mod + rand(-2,4)));
      const crit = Math.random() < (G.p.lck*0.01 + 0.05);
      if(crit){dmg=Math.floor(dmg*1.8); G.combat.log.push('🎯 暴击！');}
      t.hp-=dmg;
      G.combat.log.push(`⚔️ 你对 ${t.n} 使用 ${S.n}，造成 ${dmg} 伤害`);
      if(S.status && Math.random()<0.6){t.status[S.status]=3; G.combat.log.push(`💫 ${t.n} 陷入${S.status}！`);}
    });
  }
  if(S.buff){G.p.buffs[S.buff]=true; G.combat.log.push(`🛡️ 你进入${S.n}状态`);}
  G.combat.turn++; render(); setTimeout(processTurn,400);
}
function flee(){
  if(Math.random()<0.5+getAgi()*0.02){
    G.combat.log.push('🏃 你成功逃离！');
    pushLog('s','你逃离了战斗。');
    G.combat=null; advanceTime(1); render();
  } else {
    G.combat.log.push('❌ 逃跑失败！');
    G.combat.turn++; render(); processTurn();
  }
}
function endCombat(win){
  if(win){
    let xp=0,gold=0,loot=[];
    G.combat.enemies.forEach(e=>{
      xp+=e.xp; gold+=rand(e.gold[0],e.gold[1]);
      // loot
      if(Math.random()<0.3){
        const r=Math.random();
        const rarity = r<0.5?'common':r<0.8?'uncommon':r<0.95?'rare':'epic';
        loot.push(genLoot(rarity,e.data.boss));
      }
      if(e.data.boss) unlockAch('dragon_slayer');
    });
    G.p.gold+=gold;
    pushLog('w',`🎉 战斗胜利！+${xp}XP +${gold}金`);
    if(G.p.gold>=1000) unlockAch('rich');
    gainXP(xp);
    G.flags.killedAny=true;
    unlockAch('first_blood');
    // quest progress
    G.quests.active.forEach(q=>{
      if(q.id==='q_wolves' && G.combat.enemies.some(e=>e.key==='wolf')){
        q.count += G.combat.enemies.filter(e=>e.key==='wolf').length;
        pushLog('q',`狼患进度 ${Math.min(q.count,q.need)}/${q.need}`);
      }
    });
    loot.forEach(l=>addItem(l));
    checkQuests();
  } else {
    pushLog('w','💀 你倒下了…苏醒在橡谷镇的客栈。');
    G.p.hp=Math.floor(G.p.hpMax*0.3);
    G.p.gold=Math.floor(G.p.gold*0.7);
    G.p.loc='town_oakvale';
  }
  G.combat=null;
  advanceTime(1);
  render();
}
function genLoot(rarity,boss){
  const pool=[
    {n:'生锈短剑',type:'weapon',atk:3,w:2},
    {n:'符文长剑',type:'weapon',atk:rand(8,14),w:3},
    {n:'破旧护甲',type:'armor',def:rand(3,8),w:3},
    {n:'巫师袍',type:'armor',def:rand(4,7),int:3,w:2},
    {n:'敏捷之戒',type:'trinket',agi:rand(2,6),w:.1},
    {n:'生命药水',type:'consume',w:.5,desc:'恢复50HP',effect:{hp:50}}
  ];
  let base=pick(pool);
  if(boss){
    return {id:'dragon_fang',n:'龙牙巨剑',type:'weapon',rarity:'legend',atk:30,w:5,desc:'凝聚古龙之力',el:'火'};
  }
  return {id:base.n,...base,rarity,desc:'战利品'};
}

// ============== EXPLORATION ==============
function explore(){
  const loc=LOCATIONS[G.p.loc];
  advanceTime(1);
  if(loc.encounters && Math.random()<0.55){
    const n = loc.type==='dungeon'?rand(1,3):rand(1,2);
    const enemies=[];
    for(let i=0;i<n;i++) enemies.push(pick(loc.encounters));
    return startCombat(enemies);
  }
  // random events
  const r=Math.random();
  if(r<0.2){
    const g=rand(10,40);
    G.p.gold+=g;
    pushLog('e',`💰 你在草丛中发现 ${g} 金币。`);
  } else if(r<0.35){
    const it={id:'herb',n:'草药',type:'consume',rarity:'common',w:.2,desc:'恢复15HP',effect:{hp:15}};
    addItem(it);
  } else if(r<0.45 && loc.hidden){
    pushLog('e',`✨ ${loc.hidden}`);
    if(!G.flags.foundGlade && loc.id!=='hidden_glade'){
      G.flags.foundGlade=true;
      unlockAch('explorer');
      pushLog('e','你似乎找到了通往隐秘之处的线索…');
    }
  } else if(r<0.55 && G.p.loc==='ruin_old' && !G.flags.foundRelic){
    G.flags.foundRelic=true;
    pushLog('e','🔮 你在石棺中找到了一枚古老的护符！');
    addItem({id:'relic_amulet',n:'王朝护符',type:'trinket',rarity:'rare',lck:8,w:.1,desc:'失落王朝的徽记'});
  } else {
    pushLog('e','你探索了一阵，无事发生。');
  }
  render();
}

function travel(to){
  if(!LOCATIONS[to]){pushLog('w','无效目的地'); return;}
  if(to==='hidden_glade' && !G.flags.foundGlade){pushLog('w','你不知道如何前往此地。'); return;}
  G.p.loc=to;
  advanceTime(2);
  pushLog('s',`🚶 你来到了 ${LOCATIONS[to].name}。`);
  pushLog('s',LOCATIONS[to].desc);
  // hidden glade only at night
  if(to==='hidden_glade' && (G.time.hour<20 && G.time.hour>6)){
    pushLog('e','此地在月光下显形…白昼空无一物。');
  }
  render();
}

function rest(){
  if(LOCATIONS[G.p.loc].inn){
    if(G.p.gold<10){pushLog('w','需要10金币。'); return;}
    G.p.gold-=10;
    G.p.hp=G.p.hpMax; G.p.mp=G.p.mpMax;
    G.p.status={};
    advanceTime(8);
    rollShop();
    pushLog('s','💤 你美美地睡了一觉，HP/MP全满。');
  } else {
    G.p.hp=Math.min(G.p.hpMax,G.p.hp+15);
    G.p.mp=Math.min(G.p.mpMax,G.p.mp+10);
    advanceTime(2);
    pushLog('s','你休息了一会，恢复了少许体力。');
  }
  render();
}

function shop_buy(id){
  const it=G.shopPrices[id]; if(!it) return;
  if(G.p.gold<it.price){pushLog('w','金币不足'); return;}
  G.p.gold-=it.price;
  if(addItem(it)) pushLog('i',`购买了 ${it.n} (-${it.price}金)`);
  else G.p.gold+=it.price;
  render();
}
function shop_sell(idx){
  const it=G.p.inv[idx]; if(!it) return;
  const base = it.base||30;
  const price=Math.floor(base*0.4);
  G.p.gold+=price;
  removeItem(idx);
  pushLog('i',`卖出 ${it.n} (+${price}金)`);
  render();
}

// ============== ASCII MAP ==============
function getMap(){
  const loc=LOCATIONS[G.p.loc];
  const reg=REGIONS[loc.region];
  const here=' ◉ ';
  const dot='   ';
  let lines=[];
  lines.push(`╔═════════ ${reg.name} ═════════╗`);
  lines.push('║                              ║');
  // simple map of region locations
  const locs=reg.locs;
  let row='║   ';
  locs.forEach((l,i)=>{
    const mark = l===G.p.loc?'◉':(LOCATIONS[l].type==='town'?'⌂':LOCATIONS[l].type==='dungeon'?'▲':LOCATIONS[l].hidden||l==='hidden_glade'?'✦':'♣');
    row+=`[${mark}] `;
  });
  row+='   ║';
  lines.push(row);
  lines.push('║                              ║');
  let row2='║   ';
  locs.forEach(l=>{
    const n=LOCATIONS[l].name.substring(0,3);
    row2+=` ${n} `;
  });
  row2+='   ║';
  lines.push(row2);
  lines.push('║                              ║');
  lines.push(`╚══════════════════════════════╝`);
  lines.push(`位置: ${loc.name}  天气: ${G.weather}  时间: 第${G.time.day}日 ${G.time.hour}时`);
  return lines.join('\n');
}

