function formatLog(l){
  const m={p:'<span class="tag t-gold">序章</span>',s:'',i:'<span class="tag t-blue">物品</span>',w:'<span class="tag t-red">警告</span>',
    h:'<span class="tag t-green">恢复</span>',x:'<span class="tag t-purple">经验</span>',lv:'<span class="tag t-gold">升级</span>',
    q:'<span class="tag t-gold">任务</span>',e:'<span class="tag t-green">事件</span>',f:'<span class="tag t-blue">声望</span>',
    ach:'<span class="tag t-gold">成就</span>'};
