      <button class="${activeTab==='shop'?'act':''}" onclick="setTab('shop')">商店</button>
      <button class="${activeTab==='more'?'act':''}" onclick="setTab('more')">更多</button>
    </div>
    <div>${renderTab()}</div>
  </div>`;
}

function renderTab(){
  if(activeTab==='inv'){
    return `<small>负重 ${G.p.invWeight.toFixed(1)}/${G.p.invWeightMax} · ${G.p.inv.length}/${G.p.invMax}格</small>
    ${G.p.inv.map((it,i)=>`<div class="item r-${it.rarity}">
      <strong style="color:${RARITY[it.rarity].c}">${it.n}</strong>
      <small>${it.desc||''}</small>
      <div class="row">
        ${['weapon','armor','trinket'].includes(it.type)?`<button onclick="equip(${i});render()">装备</button>`:''}
        ${it.type==='consume'?`<button onclick="useItem(${i});render()">使用</button>`:''}
        ${LOCATIONS[G.p.loc].shop?`<button onclick="shop_sell(${i})">卖</button>`:''}
      </div>
    </div>`).join('')||'<small>空空如也</small>'}`;
  }
  if(activeTab==='eq'){
    const e=G.p.equip;
    return ['weapon','armor','trinket'].map(s=>{
      const it=e[s];
      const slotName={weapon:'武器 ⚔️',armor:'护甲 🛡️',trinket:'饰品 💍'}[s];
      return `<div class="item ${it?'r-'+it.rarity:''}"><strong>${slotName}:</strong> ${it?`<span style="color:${RARITY[it.rarity].c}">${it.n}</span><br><small>${it.desc} ${it.atk?'攻+'+it.atk:''} ${it.def?'防+'+it.def:''} ${it.agi?'速+'+it.agi:''} ${it.int?'智+'+it.int:''}</small>`:'<small>无</small>'}</div>`;
    }).join('');
  }
  if(activeTab==='quest'){
    let h='<h3>进行中</h3>';
    h+=G.quests.active.map(q=>`<div class="q"><strong>${QUESTS[q.id].n}</strong><br><small>${QUESTS[q.id].d}</small>${q.need?`<br><small>进度 ${Math.min(q.count||0,q.need)}/${q.need}</small>`:''}</div>`).join('')||'<small>无任务</small>';
    h+='<h3 style="margin-top:8px;">已完成</h3>';
    h+=G.quests.done.map(id=>`<div class="item">✅ ${QUESTS[id].n}</div>`).join('')||'<small>暂无</small>';
    return h;
  }
  if(activeTab==='shop'){
    if(!LOCATIONS[G.p.loc].shop) return '<small>此处无商店</small>';
    return Object.values(G.shopPrices).map(it=>`<div class="item r-${it.rarity}">
      <strong style="color:${RARITY[it.rarity].c}">${it.n}</strong> <span style="float:right;">${it.price}金</span>
      <br><small>${it.desc||''}</small>
      <button onclick="shop_buy('${it.id}')" ${G.p.gold<it.price?'disabled':''}>购买</button>
    </div>`).join('');
  }
  if(activeTab==='more'){
    let h='<h3>声望</h3>';
    for(const f in G.factions) h+=`<div class="stat"><span>${f}</span><span>${G.factions[f]}</span></div>`;
    h+='<h3>成就 '+G.achievements.length+'/'+ACHIEVEMENTS.length+'</h3>';
    h+=ACHIEVEMENTS.map(a=>{
      const got=G.achievements.includes(a.id);
      return `<div class="item" style="opacity:${got?1:.4}">${got?'🏆':'🔒'} <strong>${a.n}</strong><br><small>${a.d}</small></div>`;
    }).join('');
    h+='<h3>收藏 ('+G.collection.length+')</h3>';
    h+=G.collection.map(c=>`<div class="item r-${c.rarity}" style="color:${RARITY[c.rarity].c}">${c.n}</div>`).join('')||'<small>暂无稀有收藏</small>';
    h+='<div style="margin-top:8px;"><button onclick="if(confirm(\'重新开始?\')){G=null;render();}">重新开始</button></div>';
    return h;
  }
}

function setTab(t){activeTab=t; render();}

// ============== COMMAND PARSER ==============
function runCmd(s){
  s=s.trim().toLowerCase();
  if(!s) return;
  if(s==='help'){
    pushLog('s','命令: explore(探索) / rest(休息) / travel <地点> / status(状态) / shop / inventory / quest');
  } else if(s==='explore'||s==='探索') explore();
