    pushLog('s',`${G.p.name} Lv.${G.p.lv} | HP ${G.p.hp}/${G.p.hpMax} | MP ${G.p.mp}/${G.p.mpMax} | 金 ${G.p.gold}`);
  } else if(s==='shop'||s==='商店') setTab('shop');
  else if(s==='inventory'||s==='背包') setTab('inv');
  else if(s==='quest'||s==='任务') setTab('quest');
