<script type="module">
import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';

let scene, camera, renderer, controls, raycaster, mouse;
let board = []; // 8x8 of {piece, mesh, color, type}
let squares = []; // 8x8 square meshes
let selected = null;
let turn = 'white';
let animating = false;
let captured = {white:0, black:0};
let audioCtx;

function beep(freq, dur=0.1, type='sine'){
  try{
    if(!audioCtx) audioCtx = new (window.AudioContext||window.webkitAudioContext)();
    const o=audioCtx.createOscillator(),g=audioCtx.createGain();
    o.type=type;o.frequency.value=freq;
    o.connect(g);g.connect(audioCtx.destination);
    g.gain.setValueAtTime(0.2,audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001,audioCtx.currentTime+dur);
    o.start();o.stop(audioCtx.currentTime+dur);
  }catch(e){}
}

function init(){
  scene = new THREE.Scene();
  scene.background = new THREE.Color(0x1a1a2e);
  scene.fog = new THREE.Fog(0x1a1a2e, 15, 40);

  camera = new THREE.PerspectiveCamera(50, innerWidth/innerHeight, 0.1, 100);
  camera.position.set(0, 10, 10);

  renderer = new THREE.WebGLRenderer({antialias:true});
  renderer.setSize(innerWidth, innerHeight);
  renderer.shadowMap.enabled = true;
  document.getElementById('container').appendChild(renderer.domElement);

  controls = new OrbitControls(camera, renderer.domElement);
  controls.target.set(0,0,0);
  controls.maxPolarAngle = Math.PI/2.1;
  controls.minDistance = 8;
  controls.maxDistance = 25;

  // lights
  scene.add(new THREE.AmbientLight(0xffffff, 0.4));
  const dl = new THREE.DirectionalLight(0xffffff, 1);
  dl.position.set(5,15,8);
  dl.castShadow = true;
  dl.shadow.mapSize.width=1024;dl.shadow.mapSize.height=1024;
  dl.shadow.camera.left=-10;dl.shadow.camera.right=10;
  dl.shadow.camera.top=10;dl.shadow.camera.bottom=-10;
  scene.add(dl);

  const pl = new THREE.PointLight(0xffd700,0.5,20);
  pl.position.set(0,8,0);
  scene.add(pl);

  // board base
  const base = new THREE.Mesh(
    new THREE.BoxGeometry(9,0.4,9),
    new THREE.MeshStandardMaterial({color:0x2a1810})
  );
  base.position.y=-0.3;
  base.receiveShadow=true;
  scene.add(base);

  // squares
  for(let r=0;r<8;r++){
    board[r]=[];squares[r]=[];
    for(let c=0;c<8;c++){
      const light = (r+c)%2===0;
      const mat = new THREE.MeshStandardMaterial({color: light?0xf0d9b5:0x8b5a2b});
      const sq = new THREE.Mesh(new THREE.BoxGeometry(1,0.1,1), mat);
      sq.position.set(c-3.5,0,r-3.5);
      sq.receiveShadow=true;
      sq.userData={type:'square',row:r,col:c,origColor:mat.color.getHex()};
      scene.add(sq);
      squares[r][c]=sq;
      board[r][c]=null;
    }
  }

  raycaster = new THREE.Raycaster();
  mouse = new THREE.Vector2();

  setupPieces();
  renderer.domElement.addEventListener('click', onClick);
  window.addEventListener('resize',()=>{
    camera.aspect=innerWidth/innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(innerWidth,innerHeight);
  });
  animate();
}

function createPiece(type, color){
  const group = new THREE.Group();
  const mat = new THREE.MeshStandardMaterial({
    color: color==='white'?0xf5f5f5:0x222222,
    metalness:0.3, roughness:0.4
  });
  // base
  const base = new THREE.Mesh(new THREE.CylinderGeometry(0.35,0.4,0.15,16), mat);
  base.position.y=0.075;base.castShadow=true;
  group.add(base);

  let body;
  if(type==='pawn'){
    body = new THREE.Mesh(new THREE.SphereGeometry(0.22,16,16),mat);
    body.position.y=0.4;
    const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.15,0.25,0.3,16),mat);
    stem.position.y=0.15;
    group.add(stem);
  }else if(type==='rook'){
    body = new THREE.Mesh(new THREE.BoxGeometry(0.5,0.7,0.5),mat);
    body.position.y=0.5;
  }else if(type==='knight'){
    body = new THREE.Mesh(new THREE.ConeGeometry(0.3,0.8,4),mat);
    body.position.y=0.55;
    body.rotation.y=Math.PI/4;
    body.rotation.x=0.3;
  }else if(type==='bishop'){
    body = new THREE.Mesh(new THREE.ConeGeometry(0.3,0.9,16),mat);
    body.position.y=0.6;
    const top = new THREE.Mesh(new THREE.SphereGeometry(0.1,8,8),mat);
    top.position.y=1.1;
    group.add(top);
  }else if(type==='queen'){
    body = new THREE.Mesh(new THREE.CylinderGeometry(0.2,0.35,0.9,16),mat);
    body.position.y=0.6;
    const crown = new THREE.Mesh(new THREE.SphereGeometry(0.2,16,16),mat);
    crown.position.y=1.15;
    group.add(crown);
  }else if(type==='king'){
    body = new THREE.Mesh(new THREE.CylinderGeometry(0.22,0.35,1,16),mat);
    body.position.y=0.65;
    const c1 = new THREE.Mesh(new THREE.BoxGeometry(0.1,0.3,0.1),mat);
    c1.position.y=1.3;
    const c2 = new THREE.Mesh(new THREE.BoxGeometry(0.3,0.1,0.1),mat);
    c2.position.y=1.35;
    group.add(c1);group.add(c2);
  }
  body.castShadow=true;
  group.add(body);
  group.traverse(o=>{if(o.isMesh){o.castShadow=true;o.userData.parent=group}});
  group.userData={type:'piece',pieceType:type,color:color};
  return group;
}

function placePiece(type,color,r,c){
  const p = createPiece(type,color);
  p.position.set(c-3.5,0.05,r-3.5);
  scene.add(p);
  board[r][c] = p;
}

function setupPieces(){
  const order = ['rook','knight','bishop','queen','king','bishop','knight','rook'];
  for(let c=0;c<8;c++){
    placePiece(order[c],'white',0,c);
    placePiece('pawn','white',1,c);
    placePiece('pawn','black',6,c);
    placePiece(order[c],'black',7,c);
  }
}

function onClick(e){
  if(animating) return;
  const rect = renderer.domElement.getBoundingClientRect();
  mouse.x = ((e.clientX-rect.left)/rect.width)*2-1;
  mouse.y = -((e.clientY-rect.top)/rect.height)*2+1;
  raycaster.setFromCamera(mouse,camera);
  const hits = raycaster.intersectObjects(scene.children,true);
  if(!hits.length) return;

  let target=null;
  for(const h of hits){
    let o = h.object;
    while(o && !o.userData.type) o=o.parent;
    if(o && o.userData.type){target=o;break;}
  }
  if(!target) return;

  if(target.userData.type==='piece'){
    if(target.userData.color===turn){
      selectPiece(target);
    }else if(selected){
      // try capture
      const pos = findPiece(target);
      tryMove(pos.r, pos.c);
    }
  }else if(target.userData.type==='square' && selected){
    tryMove(target.userData.row, target.userData.col);
  }
}

function findPiece(p){
  for(let r=0;r<8;r++)for(let c=0;c<8;c++)if(board[r][c]===p)return{r,c};
  return null;
}

function selectPiece(p){
  if(selected) deselect();
  selected = p;
  const pos = findPiece(p);
  selected.userData.origY = p.position.y;
  animateY(p, 1.2, 200);
  // highlight valid moves
  const moves = getValidMoves(pos.r,pos.c,p.userData.pieceType,p.userData.color);
  for(const [r,c] of moves){
    squares[r][c].material.color.setHex(board[r][c]?0xff6666:0x66ff66);
  }
  beep(440,0.08);
}

function deselect(){
  if(!selected) return;
  animateY(selected, 0.05, 150);
  selected = null;
  // reset square colors
  for(let r=0;r<8;r++)for(let c=0;c<8;c++){
    squares[r][c].material.color.setHex(squares[r][c].userData.origColor);
  }
}

function getValidMoves(r,c,type,color){
  const moves = [];
  const inB = (r,c)=>r>=0&&r<8&&c>=0&&c<8;
  const enemy = color==='white'?'black':'white';
  const add = (r,c)=>{
    if(!inB(r,c)) return false;
    if(!board[r][c]){moves.push([r,c]);return true;}
    if(board[r][c].userData.color===enemy){moves.push([r,c]);}
    return false;
  };
  const ray = (dr,dc)=>{
    for(let i=1;i<8;i++){
      const nr=r+dr*i,nc=c+dc*i;
      if(!inB(nr,nc)) break;
      if(!board[nr][nc]){moves.push([nr,nc]);}
      else{
        if(board[nr][nc].userData.color===enemy) moves.push([nr,nc]);
        break;
      }
    }
  };
  if(type==='pawn'){
    const dir = color==='white'?1:-1;
    const start = color==='white'?1:6;
    if(inB(r+dir,c) && !board[r+dir][c]){
      moves.push([r+dir,c]);
      if(r===start && !board[r+2*dir][c]) moves.push([r+2*dir,c]);
    }
    for(const dc of [-1,1]){
      if(inB(r+dir,c+dc) && board[r+dir][c+dc] && board[r+dir][c+dc].userData.color===enemy)
        moves.push([r+dir,c+dc]);
    }
  }else if(type==='rook'){
    ray(1,0);ray(-1,0);ray(0,1);ray(0,-1);
  }else if(type==='bishop'){
    ray(1,1);ray(1,-1);ray(-1,1);ray(-1,-1);
  }else if(type==='queen'){
    ray(1,0);ray(-1,0);ray(0,1);ray(0,-1);
    ray(1,1);ray(1,-1);ray(-1,1);ray(-1,-1);
  }else if(type==='king'){
    for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++)if(dr||dc) add(r+dr,c+dc);
  }else if(type==='knight'){
    for(const [dr,dc] of [[2,1],[2,-1],[-2,1],[-2,-1],[1,2],[1,-2],[-1,2],[-1,-2]]) add(r+dr,c+dc);
  }
  return moves;
}

function tryMove(r,c){
  const from = findPiece(selected);
  const moves = getValidMoves(from.r,from.c,selected.userData.pieceType,selected.userData.color);
  const valid = moves.some(m=>m[0]===r&&m[1]===c);
  if(!valid){
    beep(150,0.1,'square');
    deselect();
    return;
  }
  const piece = selected;
  const target = board[r][c];
  // reset highlights
  for(let i=0;i<8;i++)for(let j=0;j<8;j++)squares[i][j].material.color.setHex(squares[i][j].userData.origColor);
  selected = null;
  board[from.r][from.c]=null;

  const isKing = target && target.userData.pieceType==='king';
  animating = true;

  // animate move
  const targetPos = new THREE.Vector3(c-3.5,0.05,r-3.5);
  const liftPos = new THREE.Vector3(c-3.5,1.5,r-3.5);
  animatePath(piece, [liftPos, targetPos], 500, ()=>{
    if(target){
      // capture animation
      animateCapture(target,()=>{
        scene.remove(target);
        captured[target.userData.color==='white'?'white':'black']++;
        updateHUD();
        finishMove();
      });
    } else finishMove();

    function finishMove(){
      board[r][c]=piece;
      animating=false;
      beep(target?330:550, 0.12);
      if(isKing){
        document.getElementById('winText').textContent = (turn==='white'?'White':'Black')+' Wins!';
        document.getElementById('endScreen').classList.remove('hidden');
        return;
      }
      turn = turn==='white'?'black':'white';
      document.getElementById('turn').textContent = turn.charAt(0).toUpperCase()+turn.slice(1);
    }
  });
}

function updateHUD(){
  document.getElementById('wcap').textContent=captured.black;
  document.getElementById('bcap').textContent=captured.white;
}

function animateY(obj, targetY, dur){
  const startY = obj.position.y;
  const t0 = performance.now();
  function step(){
    const t = Math.min(1,(performance.now()-t0)/dur);
    obj.position.y = startY + (targetY-startY)*t;
    if(t<1) requestAnimationFrame(step);
  }
  step();
}

function animatePath(obj, points, dur, done){
  const start = obj.position.clone();
  const all = [start, ...points];
  const t0 = performance.now();
  function step(){
    const t = Math.min(1,(performance.now()-t0)/dur);
    // piecewise linear
    const seg = t*(all.length-1);
    const i = Math.min(Math.floor(seg), all.length-2);
    const lt = seg-i;
    obj.position.lerpVectors(all[i], all[i+1], lt);
    // spin slightly
    obj.rotation.y = t*Math.PI*0.5;
    if(t<1) requestAnimationFrame(step);
    else {obj.rotation.y=0;done&&done();}
  }
  step();
}

function animateCapture(obj, done){
  const t0 = performance.now();
  const dur = 400;
  function step(){
    const t = Math.min(1,(performance.now()-t0)/dur);
    obj.position.y = 0.05 + t*3;
    obj.rotation.x = t*Math.PI*2;
    obj.rotation.z = t*Math.PI*2;
    obj.scale.setScalar(1-t);
    if(t<1) requestAnimationFrame(step);
    else done();
  }
  step();
}

function animate(){
  requestAnimationFrame(animate);
  controls.update();
  // gentle selected pulse
  if(selected){
    selected.rotation.y += 0.02;
  }
  renderer.render(scene,camera);
}

window.startGame = function(){
  document.getElementById('startScreen').classList.add('hidden');
  if(!scene) init();
};

init(); // initialize but cover with start screen
</script>
</body>
</html>
