<script type="module">
import * as THREE from 'three';

// ====== SETUP ======
const container = document.getElementById('game');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9bb8d6);
scene.fog = new THREE.Fog(0x9bb8d6, 80, 280);

const camera = new THREE.PerspectiveCamera(75, innerWidth/innerHeight, 0.1, 600);
const renderer = new THREE.WebGLRenderer({ antialias:true, powerPreference:'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
container.appendChild(renderer.domElement);

// Lights
const hemi = new THREE.HemisphereLight(0xb1d4ff, 0x4d3a25, 0.6);
scene.add(hemi);
const sun = new THREE.DirectionalLight(0xfff1d0, 1.2);
sun.position.set(60, 120, 40);
sun.castShadow = true;
sun.shadow.mapSize.set(2048,2048);
sun.shadow.camera.left = -120; sun.shadow.camera.right = 120;
sun.shadow.camera.top = 120; sun.shadow.camera.bottom = -120;
sun.shadow.camera.near = 1; sun.shadow.camera.far = 300;
sun.shadow.bias = -0.0005;
scene.add(sun);

// Ground (large)
const MAP_SIZE = 400;
const groundGeo = new THREE.PlaneGeometry(MAP_SIZE, MAP_SIZE, 64, 64);
// vertex displace for terrain
const pos = groundGeo.attributes.position;
for (let i=0;i<pos.count;i++){
  const x = pos.getX(i), y = pos.getY(i);
  const h = Math.sin(x*0.05)*1.2 + Math.cos(y*0.06)*1.0 + Math.sin((x+y)*0.03)*0.7;
  pos.setZ(i, h);
}
groundGeo.computeVertexNormals();
const groundMat = new THREE.MeshStandardMaterial({ color:0x4a6b3a, roughness:0.95 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI/2;
ground.receiveShadow = true;
scene.add(ground);

// Buildings / cover
const obstacles = [];
function addBox(x,z,w,h,d,color){
  const m = new THREE.Mesh(
    new THREE.BoxGeometry(w,h,d),
    new THREE.MeshStandardMaterial({ color, roughness:0.8 })
  );
  m.position.set(x, h/2, z);
  m.castShadow = m.receiveShadow = true;
  scene.add(m);
  obstacles.push({ mesh:m, x, z, w, d, h });
  return m;
}
// City cluster
for (let i=0;i<40;i++){
  const x = (Math.random()-0.5)*MAP_SIZE*0.85;
  const z = (Math.random()-0.5)*MAP_SIZE*0.85;
  if (Math.hypot(x,z)<8) continue;
  const w = 6 + Math.random()*10;
  const d = 6 + Math.random()*10;
  const h = 5 + Math.random()*18;
  const c = new THREE.Color().setHSL(0.07 + Math.random()*0.1, 0.15, 0.35 + Math.random()*0.25);
  addBox(x,z,w,h,d,c.getHex());
}
// crates
for (let i=0;i<60;i++){
  const x = (Math.random()-0.5)*MAP_SIZE*0.9;
  const z = (Math.random()-0.5)*MAP_SIZE*0.9;
  if (Math.hypot(x,z)<5) continue;
  addBox(x,z, 2, 2, 2, 0x7a5a32);
}
// trees
for (let i=0;i<80;i++){
  const x = (Math.random()-0.5)*MAP_SIZE*0.95;
  const z = (Math.random()-0.5)*MAP_SIZE*0.95;
  if (Math.hypot(x,z)<10) continue;
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.4,0.5,3), new THREE.MeshStandardMaterial({color:0x4a2f1a}));
  trunk.position.set(x,1.5,z); trunk.castShadow = true; scene.add(trunk);
  const top = new THREE.Mesh(new THREE.ConeGeometry(2.5,5,8), new THREE.MeshStandardMaterial({color:0x2d5a2d}));
  top.position.set(x,5,z); top.castShadow = true; scene.add(top);
  obstacles.push({mesh:trunk, x, z, w:1, d:1, h:3});
}

// Safe zone visualization
const zoneGeo = new THREE.RingGeometry(0.98, 1, 64);
const zoneMat = new THREE.MeshBasicMaterial({ color:0x00ffff, side:THREE.DoubleSide, transparent:true, opacity:0.7 });
const zoneRing = new THREE.Mesh(zoneGeo, zoneMat);
zoneRing.rotation.x = -Math.PI/2;
zoneRing.position.y = 0.2;
scene.add(zoneRing);
let zoneRadius = 150;
let zoneTarget = 150;
let zoneCenter = new THREE.Vector3(0,0,0);

// ====== PLAYER ======
const player = {
  pos: new THREE.Vector3(0, 1.7, 0),
  vel: new THREE.Vector3(),
  yaw: 0, pitch: 0,
  hp: 100, armor: 75,
  ammo: 30, reserve: 120, magSize: 30,
  reloading: false,
  fireCooldown: 0,
  onGround: true,
  kills: 0,
  alive: true,
};

// ====== ENEMIES ======
const enemies = [];
const ENEMY_COUNT = 99;
function createEnemy(i){
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.4, 1.0, 4, 8),
    new THREE.MeshStandardMaterial({color:new THREE.Color().setHSL(Math.random(),0.6,0.5)}));
  body.position.y = 0.9; body.castShadow = true; g.add(body);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.28,12,12),
    new THREE.MeshStandardMaterial({color:0xffccaa}));
  head.position.y = 1.85; head.castShadow = true; g.add(head);
  // gun
  const gun = new THREE.Mesh(new THREE.BoxGeometry(0.15,0.15,0.7), new THREE.MeshStandardMaterial({color:0x222}));
  gun.position.set(0.35, 1.2, 0.25); g.add(gun);

  let angle = Math.random()*Math.PI*2;
  let radius = 30 + Math.random()*100;
  g.position.set(Math.cos(angle)*radius, 0, Math.sin(angle)*radius);
  scene.add(g);
  return { mesh:g, hp:100, alive:true, vel:new THREE.Vector3(),
    target:new THREE.Vector3(), shootCD: Math.random()*2,
    aiState: 'patrol', name: 'BOT_'+ (i+1).toString().padStart(2,'0')
  };
}
for (let i=0;i<ENEMY_COUNT;i++) enemies.push(createEnemy(i));

// ====== BULLETS ======
const bullets = [];
const bulletGeo = new THREE.SphereGeometry(0.08, 6, 6);
const bulletMat = new THREE.MeshBasicMaterial({ color:0xffee66 });
function spawnBullet(from, dir, owner='player'){
  const m = new THREE.Mesh(bulletGeo, bulletMat);
  m.position.copy(from);
  scene.add(m);
  bullets.push({ mesh:m, vel:dir.clone().multiplyScalar(120), life:2, owner });
}

// Muzzle flash
const muzzle = new THREE.PointLight(0xffaa44, 0, 8);
scene.add(muzzle);

// Player gun (viewmodel)
const gunGroup = new THREE.Group();
const gunBody = new THREE.Mesh(new THREE.BoxGeometry(0.2,0.2,0.9), new THREE.MeshStandardMaterial({color:0x2a2a2a, metalness:.8, roughness:.4}));
gunBody.position.set(0.3,-0.25,-0.6);
gunGroup.add(gunBody);
const gunMag = new THREE.Mesh(new THREE.BoxGeometry(0.15,0.25,0.15), new THREE.MeshStandardMaterial({color:0x111}));
gunMag.position.set(0.3,-0.45,-0.45);
gunGroup.add(gunMag);
camera.add(gunGroup);
scene.add(camera);

// ====== AUDIO ======
const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
function shootSound(){
  const o = audioCtx.createOscillator(); const g = audioCtx.createGain();
  o.type='square'; o.frequency.setValueAtTime(180, audioCtx.currentTime);
  o.frequency.exponentialRampToValueAtTime(40, audioCtx.currentTime+0.1);
  g.gain.setValueAtTime(0.15, audioCtx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime+0.12);
  o.connect(g).connect(audioCtx.destination); o.start(); o.stop(audioCtx.currentTime+0.13);
}
function hitSound(){
  const o = audioCtx.createOscillator(); const g = audioCtx.createGain();
  o.type='triangle'; o.frequency.setValueAtTime(800,audioCtx.currentTime);
  o.frequency.exponentialRampToValueAtTime(200,audioCtx.currentTime+0.15);
  g.gain.setValueAtTime(0.2,audioCtx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001,audioCtx.currentTime+0.2);
  o.connect(g).connect(audioCtx.destination); o.start(); o.stop(audioCtx.currentTime+0.2);
}
function reloadSound(){
  const o = audioCtx.createOscillator(); const g = audioCtx.createGain();
  o.type='sawtooth'; o.frequency.value=100;
  g.gain.setValueAtTime(0.08,audioCtx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001,audioCtx.currentTime+0.4);
  o.connect(g).connect(audioCtx.destination); o.start(); o.stop(audioCtx.currentTime+0.4);
}

// ====== INPUT ======
const keys = {};
let mouseDown = false;
addEventListener('keydown', e => { keys[e.code]=true;
  if (e.code==='KeyR') reload();
});
addEventListener('keyup', e => { keys[e.code]=false; });
addEventListener('mousedown', e => { if (e.button===0) mouseDown=true; });
addEventListener('mouseup', e => { if (e.button===0) mouseDown=false; });

const canvas = renderer.domElement;
canvas.addEventListener('click', () => {
  if (gameState==='play') canvas.requestPointerLock();
});
addEventListener('mousemove', e => {
  if (document.pointerLockElement === canvas){
    player.yaw -= e.movementX * 0.0025;
    player.pitch -= e.movementY * 0.0025;
    player.pitch = Math.max(-Math.PI/2+0.1, Math.min(Math.PI/2-0.1, player.pitch));
  }
});

// Mobile
let mobileDir = {x:0,y:0};
const joy = document.getElementById('joy');
const stick = document.getElementById('stick');
let joyActive = false, joyId=null, joyStart={x:0,y:0};
joy.addEventListener('touchstart', e => {
  joyActive=true; const t=e.changedTouches[0]; joyId=t.identifier;
  const r=joy.getBoundingClientRect(); joyStart={x:r.left+r.width/2, y:r.top+r.height/2};
});
addEventListener('touchmove', e => {
  for (const t of e.changedTouches){
    if (t.identifier===joyId){
      const dx=t.clientX-joyStart.x, dy=t.clientY-joyStart.y;
      const d=Math.min(60, Math.hypot(dx,dy));
      const a=Math.atan2(dy,dx);
      stick.style.left=(50+Math.cos(a)*d/60*40)+'%';
      stick.style.top=(50+Math.sin(a)*d/60*40)+'%';
      mobileDir.x = Math.cos(a)*d/60; mobileDir.y = Math.sin(a)*d/60;
    }
  }
});
addEventListener('touchend', e => {
  for (const t of e.changedTouches){
    if (t.identifier===joyId){
      joyActive=false; joyId=null; mobileDir={x:0,y:0};
      stick.style.left='50%'; stick.style.top='50%';
    }
  }
});
document.getElementById('fireBtn').addEventListener('touchstart',()=>mouseDown=true);
document.getElementById('fireBtn').addEventListener('touchend',()=>mouseDown=false);
// touch look
let lookId=null, lookLast={x:0,y:0};
canvas.addEventListener('touchstart', e => {
  for (const t of e.changedTouches){
    if (t.clientX > innerWidth/2 && lookId===null && t.target===canvas){
      lookId=t.identifier; lookLast={x:t.clientX,y:t.clientY};
    }
  }
});
canvas.addEventListener('touchmove', e => {
  for (const t of e.changedTouches){
    if (t.identifier===lookId){
      const dx=t.clientX-lookLast.x, dy=t.clientY-lookLast.y;
      player.yaw -= dx*0.005; player.pitch -= dy*0.005;
      player.pitch = Math.max(-1.4, Math.min(1.4, player.pitch));
      lookLast={x:t.clientX,y:t.clientY};
    }
  }
});
canvas.addEventListener('touchend', e => {
  for (const t of e.changedTouches){ if (t.identifier===lookId) lookId=null; }
});

// ====== GAME LOGIC ======
let gameState = 'menu';
function reload(){
  if (player.reloading || player.ammo===player.magSize || player.reserve<=0) return;
  player.reloading = true;
  reloadSound();
  setTimeout(()=>{
    const needed = player.magSize - player.ammo;
    const take = Math.min(needed, player.reserve);
    player.ammo += take; player.reserve -= take;
    player.reloading = false;
    updateHUD();
  }, 1500);
}
function fire(){
  if (player.reloading) return;
  if (player.fireCooldown>0) return;
  if (player.ammo<=0){ reload(); return; }
  player.ammo--; player.fireCooldown = 0.1;
  shootSound();
  // recoil
  player.pitch += 0.015;
  gunGroup.position.z = 0.05;
  setTimeout(()=>gunGroup.position.z=0, 50);
  muzzle.intensity = 4;
  setTimeout(()=>muzzle.intensity=0, 60);

  // raycast
  const dir = new THREE.Vector3();
  camera.getWorldDirection(dir);
  // spread
  dir.x += (Math.random()-0.5)*0.01;
  dir.y += (Math.random()-0.5)*0.01;
  dir.normalize();
  const origin = camera.getWorldPosition(new THREE.Vector3());
  spawnBullet(origin.clone().add(dir.clone().multiplyScalar(1)), dir, 'player');

  // hit detection
  const ray = new THREE.Raycaster(origin, dir, 0, 200);
  let closest=null, closestDist=Infinity;
  for (const en of enemies){
    if (!en.alive) continue;
    const hits = ray.intersectObject(en.mesh, true);
    if (hits.length && hits[0].distance<closestDist){
      closestDist = hits[0].distance; closest = en;
    }
  }
  if (closest){
    closest.hp -= 40 + Math.random()*15;
    hitSound();
    if (closest.hp<=0) killEnemy(closest);
  }
  updateHUD();
}
function killEnemy(en){
  en.alive=false;
  scene.remove(en.mesh);
  player.kills++;
  addKillFeed('YOU', en.name);
  updateHUD();
}
function addKillFeed(a,b){
  const d=document.createElement('div'); d.className='kf';
  d.innerHTML = `<b style="color:#ffd166">${a}</b> ☠ ${b}`;
  document.getElementById('killfeed').prepend(d);
  setTimeout(()=>d.remove(), 6000);
}
function updateHUD(){
  document.getElementById('hpVal').textContent = Math.max(0,Math.round(player.hp));
  document.getElementById('hpBar').style.width = Math.max(0,player.hp) + '%';
  document.getElementById('armVal').textContent = Math.max(0,Math.round(player.armor));
  document.getElementById('armBar').style.width = Math.max(0,player.armor) + '%';
  document.getElementById('ammo').textContent = player.ammo;
  document.getElementById('reserve').textContent = player.reserve;
  document.getElementById('kills').textContent = player.kills;
  document.getElementById('alive').textContent = 1 + enemies.filter(e=>e.alive).length;
}
function takeDamage(dmg){
  if (player.armor>0){
    const absorb = Math.min(player.armor, dmg*0.6);
    player.armor -= absorb; dmg -= absorb;
  }
  player.hp -= dmg;
  document.getElementById('dmg').classList.add('hit');
  setTimeout(()=>document.getElementById('dmg').classList.remove('hit'), 200);
  if (player.hp<=0 && player.alive){ player.alive=false; endGame(false); }
  updateHUD();
}

// Collisions vs obstacles (simple AABB)
function collide(x,z){
  for (const o of obstacles){
    if (Math.abs(x-o.x) < o.w/2+0.5 && Math.abs(z-o.z) < o.d/2+0.5) return true;
  }
  return false;
}

// ====== UPDATE LOOP ======
const clock = new THREE.Clock();
function animate(){
  requestAnimationFrame(animate);
  const dt = Math.min(0.05, clock.getDelta());
  if (gameState==='play') update(dt);
  renderer.render(scene, camera);
}
animate();

function update(dt){
  // movement
  const speed = (keys['ShiftLeft']?9:5);
  const fwd = new THREE.Vector3(-Math.sin(player.yaw), 0, -Math.cos(player.yaw));
  const right = new THREE.Vector3(Math.cos(player.yaw), 0, -Math.sin(player.yaw));
  let mx=0, mz=0;
  if (keys['KeyW']) mz+=1;
  if (keys['KeyS']) mz-=1;
  if (keys['KeyD']) mx+=1;
  if (keys['KeyA']) mx-=1;
  mx += mobileDir.x; mz -= mobileDir.y;
  const moveVec = new THREE.Vector3().addScaledVector(fwd, mz).addScaledVector(right, mx);
  if (moveVec.lengthSq()>0) moveVec.normalize().multiplyScalar(speed*dt);

  // gravity / jump
  if (keys['Space'] && player.onGround){ player.vel.y = 7; player.onGround=false; }
  player.vel.y -= 18*dt;
  player.pos.y += player.vel.y*dt;
  if (player.pos.y<=1.7){ player.pos.y=1.7; player.vel.y=0; player.onGround=true; }

  const newX = player.pos.x + moveVec.x;
  const newZ = player.pos.z + moveVec.z;
  if (!collide(newX, player.pos.z)) player.pos.x = newX;
  if (!collide(player.pos.x, newZ)) player.pos.z = newZ;

  // camera
  camera.position.copy(player.pos);
  camera.rotation.order = 'YXZ';
  camera.rotation.y = player.yaw;
  camera.rotation.x = player.pitch;

  // muzzle position
  muzzle.position.copy(camera.position).add(fwd.clone().multiplyScalar(1.5));

  // shooting
  player.fireCooldown -= dt;
  if (mouseDown) fire();

  // bullets
  for (let i=bullets.length-1;i>=0;i--){
    const b = bullets[i];
    b.mesh.position.addScaledVector(b.vel, dt);
    b.life -= dt;
    if (b.life<=0){ scene.remove(b.mesh); bullets.splice(i,1); continue; }
    if (b.owner==='enemy'){
      if (b.mesh.position.distanceTo(player.pos) < 0.8){
        takeDamage(8 + Math.random()*5);
        scene.remove(b.mesh); bullets.splice(i,1);
      }
    }
  }

  // zone
  zoneRing.position.x = zoneCenter.x; zoneRing.position.z = zoneCenter.z;
  zoneRing.scale.set(zoneRadius, zoneRadius, zoneRadius);
  zoneRadius += (zoneTarget - zoneRadius) * 0.001;
  // shrink occasionally
  if (Math.random()<0.0005 && zoneTarget>20) zoneTarget *= 0.92;

  // damage outside zone
  const distFromCenter = Math.hypot(player.pos.x-zoneCenter.x, player.pos.z-zoneCenter.z);
  if (distFromCenter > zoneRadius) takeDamage(8*dt);

  // enemies AI
  for (const en of enemies){
    if (!en.alive) continue;
    const ep = en.mesh.position;
    const dToPlayer = ep.distanceTo(player.pos);
    // movement towards target / player
    if (dToPlayer < 60) {
      // shoot at player
      en.shootCD -= dt;
      // look at player
      en.mesh.lookAt(player.pos.x, ep.y+1, player.pos.z);
      if (en.shootCD<=0 && dToPlayer<50){
        en.shootCD = 0.6 + Math.random()*0.8;
        const dir = new THREE.Vector3().subVectors(player.pos, ep.clone().setY(ep.y+1.5)).normalize();
        dir.x += (Math.random()-0.5)*0.08;
        dir.y += (Math.random()-0.5)*0.08;
        spawnBullet(ep.clone().setY(ep.y+1.5), dir, 'enemy');
      }
      // strafe / approach
      if (dToPlayer>15){
        const d = new THREE.Vector3().subVectors(player.pos, ep).normalize();
        ep.x += d.x*3*dt; ep.z += d.z*3*dt;
      }
    } else {
      // patrol
      if (ep.distanceTo(en.target)<2 || en.target.lengthSq()===0){
        en.target.set((Math.random()-0.5)*MAP_SIZE*0.7, 0, (Math.random()-0.5)*MAP_SIZE*0.7);
      }
      const d = new THREE.Vector3().subVectors(en.target, ep).normalize();
      ep.x += d.x*2*dt; ep.z += d.z*2*dt;
      en.mesh.lookAt(en.target.x, ep.y+1, en.target.z);
    }

    // enemies vs zone
    const eDist = Math.hypot(ep.x-zoneCenter.x, ep.z-zoneCenter.z);
    if (eDist > zoneRadius){
      en.hp -= 5*dt;
      if (en.hp<=0) {
        en.alive=false; scene.remove(en.mesh);
        addKillFeed('ZONE', en.name); updateHUD();
      }
    }

    // enemy vs enemy (sometimes)
    if (Math.random()<0.0001){
      const other = enemies[Math.floor(Math.random()*enemies.length)];
      if (other!==en && other.alive){
        other.hp -= 50;
        if (other.hp<=0){ other.alive=false; scene.remove(other.mesh); addKillFeed(en.name, other.name); updateHUD();}
      }
    }
  }

  // Win check
  const aliveCount = enemies.filter(e=>e.alive).length;
  if (aliveCount===0 && player.alive){ endGame(true); }

  // Minimap
  drawMinimap();
}

// minimap
const mini = document.getElementById('miniCanvas');
const mctx = mini.getContext('2d');
function drawMinimap(){
  mctx.clearRect(0,0,200,200);
  mctx.fillStyle = '#2a3a4d'; mctx.fillRect(0,0,200,200);
  // zone
  const scale = 200/MAP_SIZE;
  mctx.strokeStyle='#00ffff'; mctx.lineWidth=2;
  mctx.beginPath();
  mctx.arc(100+zoneCenter.x*scale, 100+zoneCenter.z*scale, zoneRadius*scale, 0, Math.PI*2);
  mctx.stroke();
  // enemies
  mctx.fillStyle='#ff3030';
  for (const en of enemies){
    if (!en.alive) continue;
    mctx.fillRect(100+en.mesh.position.x*scale-1, 100+en.mesh.position.z*scale-1, 2, 2);
  }
  // player
  mctx.fillStyle='#00ff66';
  mctx.beginPath();
  mctx.arc(100+player.pos.x*scale, 100+player.pos.z*scale, 4, 0, Math.PI*2);
  mctx.fill();
}

// ====== GAME STATE ======
document.getElementById('startBtn').addEventListener('click', () => {
  document.getElementById('startScreen').style.display='none';
  gameState='play';
  audioCtx.resume();
  canvas.requestPointerLock();
});
document.getElementById('restartBtn').addEventListener('click', () => location.reload());

function endGame(win){
  gameState='end';
  document.exitPointerLock?.();
  const s = document.getElementById('endScreen');
  s.style.display='flex';
  document.getElementById('endTitle').textContent = win ? 'VICTORY' : 'ELIMINATED';
  document.getElementById('endSub').textContent = win ? '#1 — WINNER WINNER' : 'BETTER LUCK NEXT TIME';
  const place = 1 + enemies.filter(e=>e.alive).length;
  document.getElementById('endStats').innerHTML =
    `Placement: <b>#${win?1:place}</b> &nbsp; • &nbsp; Kills: <b>${player.kills}</b> &nbsp; • &nbsp; Damage Taken: <b>${Math.round(100-player.hp + (75-player.armor))}</b>`;
}

addEventListener('resize', () => {
  camera.aspect = innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

updateHUD();
</script>
</body>
</html>
