      }
    } else {
      // run off-screen
      t.target = {x: t.x < W/2 ? -50 : W+50, y: t.y};
    }
    const ang = Math.atan2(t.target.y-t.y, t.target.x-t.x);
    t.x += Math.cos(ang)*t.speed;
    t.y += Math.sin(ang)*t.speed;

    // steal from base
    if (!t.carrying && dist(t, state.base) < state.base.r + 5 && state.baseItems && state.baseItems.length > 0) {
      // defense reduces chance
      if (Math.random() > state.defense * 0.15) {
        t.carrying = state.baseItems.pop();
        toast('⚠️ Thief stole ' + t.carrying.type + '!');
        state.brainrotCount = Math.max(0, state.brainrotCount-1);
      } else {
        // defense blocks
        addParticle(t.x, t.y, '#00ff00');
        state.thieves.splice(i,1);
        state.cash += 20;
        toast('🛡️ Defended! +$20');
        continue;
      }
    }
    // steal from player
    if (!t.carrying && dist(t, p) < t.r + p.r && p.carrying.length > 0) {
      t.carrying = p.carrying.pop();
      toast('⚠️ Thief mugged you!');
    }
    // escaped
    if (t.x < -40 || t.x > W+40) {
      state.thieves.splice(i,1);
    }
    // hit base hp if no items
    if (!t.carrying && dist(t, state.base) < state.base.r + 5 && (!state.baseItems || state.baseItems.length===0)) {
      state.baseHP -= 0.3 / state.defense;
      if (state.baseHP <= 0) gameOver();
    }
  }

  // particles
  for (let i=state.particles.length-1; i>=0; i--) {
    const pa = state.particles[i];
    pa.x += pa.vx; pa.y += pa.vy; pa.life--;
    if (pa.life <= 0) state.particles.splice(i,1);
  }
}

function addParticle(x,y,color) {
  for (let i=0; i<8; i++) state.particles.push({
    x,y, vx:(Math.random()-0.5)*4, vy:(Math.random()-0.5)*4, life:30, color
  });
}

function getPetBoost(stat) {
  let total = 0;
  for (const pet of state.pets) if (pet.boost[stat]) total += pet.boost[stat];
  return total;
}

function passiveIncome() {
  if (!state.running) return;
  const inc = Math.floor(state.brainrotCount * state.aura * (1 + getPetBoost('aura')));
  state.cash += inc;
  updateHUD();
}

function draw() {
  ctx.fillStyle = '#1a3d2e';
  ctx.fillRect(0,0,W,H);
  // road
  ctx.strokeStyle = '#444'; ctx.lineWidth = 80;
  ctx.beginPath(); ctx.moveTo(state.base.x, state.base.y); ctx.lineTo(state.zone.x, state.zone.y); ctx.stroke();
  ctx.strokeStyle = '#ffd700'; ctx.lineWidth = 2; ctx.setLineDash([15,15]);
  ctx.beginPath(); ctx.moveTo(state.base.x, state.base.y); ctx.lineTo(state.zone.x, state.zone.y); ctx.stroke();
  ctx.setLineDash([]);

  // base
  ctx.fillStyle = 'rgba(0,150,255,0.25)';
  ctx.beginPath(); ctx.arc(state.base.x, state.base.y, state.base.r, 0, Math.PI*2); ctx.fill();
  ctx.strokeStyle = '#00bfff'; ctx.lineWidth = 3; ctx.stroke();
  ctx.fillStyle = '#fff'; ctx.font = '14px sans-serif'; ctx.textAlign='center';
  ctx.fillText('🏠 BASE', state.base.x, state.base.y - state.base.r - 8);
  // base HP bar
  ctx.fillStyle = '#333'; ctx.fillRect(state.base.x-40, state.base.y+state.base.r+5, 80, 6);
  ctx.fillStyle = state.baseHP > 30 ? '#0f0' : '#f00';
  ctx.fillRect(state.base.x-40, state.base.y+state.base.r+5, 80*Math.max(0,state.baseHP)/100, 6);
  // stored items
  if (state.baseItems) {
    state.baseItems.slice(0,6).forEach((it,i) => {
      ctx.font = '18px sans-serif';
      ctx.fillText(it.type, state.base.x - 30 + (i%3)*20, state.base.y + (Math.floor(i/3)*15));
    });
  }

  // zone
  ctx.fillStyle = 'rgba(255,50,50,0.2)';
  ctx.beginPath(); ctx.arc(state.zone.x, state.zone.y, state.zone.r, 0, Math.PI*2); ctx.fill();
  ctx.strokeStyle = '#ff4444'; ctx.lineWidth = 3; ctx.stroke();
  ctx.fillStyle = '#fff'; ctx.fillText('🧠 BRAINROT ZONE', state.zone.x, state.zone.y - state.zone.r - 8);

  // items
  for (const it of state.items) {
    ctx.font = '22px sans-serif';
    ctx.fillText(it.type, it.x, it.y+8);
  }

  // thieves
  for (const t of state.thieves) {
    ctx.fillStyle = t.color;
    ctx.beginPath(); ctx.arc(t.x, t.y, t.r, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle='#fff'; ctx.font='14px sans-serif'; ctx.fillText('😈', t.x, t.y+5);
    if (t.carrying) { ctx.font='16px sans-serif'; ctx.fillText(t.carrying.type, t.x, t.y - 16); }
  }

  // player (with car effect)
  const p = state.player;
  ctx.fillStyle = p.color;
  ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI*2); ctx.fill();
  ctx.strokeStyle = '#fff'; ctx.lineWidth=2; ctx.stroke();
  ctx.fillStyle = '#fff'; ctx.font='14px sans-serif'; ctx.fillText('🚗', p.x, p.y+5);
  // carrying
  p.carrying.forEach((it,i) => {
    ctx.font='18px sans-serif';
    ctx.fillText(it.type, p.x - 15 + i*15, p.y - 22);
  });

  // pets follow player
  state.pets.forEach((pet,i) => {
    const ang = (Date.now()/500 + i*Math.PI*2/state.pets.length);
    const px = p.x + Math.cos(ang)*32;
    const py = p.y + Math.sin(ang)*32;
    ctx.font='18px sans-serif';
    ctx.fillText(pet.emoji, px, py+6);
  });

  // particles
  for (const pa of state.particles) {
    ctx.fillStyle = pa.color;
    ctx.globalAlpha = pa.life/30;
    ctx.fillRect(pa.x-2, pa.y-2, 4, 4);
    ctx.globalAlpha = 1;
  }
}

function loop() {
  if (!state.running) return;
  update(); draw(); updateHUD();
  requestAnimationFrame(loop);
}

function updateHUD() {
  document.getElementById('cash').textContent = '$' + state.cash;
  document.getElementById('aura').textContent = state.aura.toFixed(2) + 'x';
  document.getElementById('brainrots').textContent = state.brainrotCount;
  document.getElementById('income').textContent = '$' + Math.floor(state.brainrotCount * state.aura);
  document.getElementById('defense').textContent = state.defense;
  document.getElementById('speed').textContent = (state.player.speedBase + getPetBoost('speed')).toFixed(1);
  document.getElementById('carry').textContent = state.carryMax + getPetBoost('carry');
}

function clickAura(e) {
  state.aura += 0.01;
  const btn = e.target;
  btn.style.transform = 'scale(0.95)';
  setTimeout(()=>btn.style.transform='',100);
  updateHUD();
  // audio blip
  beep(600 + Math.random()*200, 0.05);
}

function buyCar(type) {
  const cost = state.carCost[type];
  if (state.cash < cost) return toast('Not enough cash!');
  state.cash -= cost;
  const boosts = {sedan:1, sports:3, super:6};
  state.player.speedBase += boosts[type];
  state.carCost[type] = Math.floor(cost * 2.5);
  document.getElementById('buy-'+type).textContent = 
    type[0].toUpperCase()+type.slice(1) + ' - $' + state.carCost[type] + ' (+' + boosts[type] + ' spd)';
  toast('🚗 New car!');
  beep(440, 0.15);
}

let defCost = 150;
function upgradeDefense() {
  if (state.cash < defCost) return toast('Not enough!');
  state.cash -= defCost;
  state.defense++;
  state.baseHP = Math.min(100, state.baseHP + 20);
  defCost = Math.floor(defCost * 1.8);
  document.getElementById('up-def').textContent = 'Upgrade Defense - $' + defCost;
  toast('🛡️ Defense+');
  beep(500, 0.1);
}

let carryCost = 300;
function upgradeCarry() {
  if (state.cash < carryCost) return toast('Not enough!');
  state.cash -= carryCost;
  state.carryMax++;
  carryCost = Math.floor(carryCost * 2);
  document.getElementById('up-carry').textContent = '+1 Carry Slot - $' + carryCost;
  toast('💪 Carry+');
  beep(550, 0.1);
}

function customize() {
  if (state.cash < 100) return toast('Not enough!');
  state.cash -= 100;
  const colors = ['#00bfff','#ff00ff','#ffd700','#00ff88','#ff6600','#ff0066'];
  state.player.color = colors[Math.floor(Math.random()*colors.length)];
  toast('🎨 New paint!');
}

function hatchEgg() {
  if (state.cash < 500) return toast('Not enough!');
  state.cash -= 500;
  const pet = PET_TYPES[Math.floor(Math.random()*PET_TYPES.length)];
  state.pets.push({...pet});
  renderPets();
  toast('🥚 Hatched ' + pet.emoji + ' ' + pet.name + '!');
  beep(700, 0.2);
}

function renderPets() {
  const list = document.getElementById('pet-list');
  if (state.pets.length === 0) { list.textContent = 'No pets yet!'; return; }
  list.innerHTML = state.pets.map(p => `<span class="pet" title="${p.name}">${p.emoji}</span>`).join('');
}

function gameOver() {
  state.running = false;
  document.getElementById('final-stats').textContent = 
    `Earnings: $${state.cash} • Brainrots Stolen: ${state.brainrotCount} • Aura: ${state.aura.toFixed(2)}x • Pets: ${state.pets.length}`;
  document.getElementById('game-over').style.display = 'flex';
}

// Web Audio beep
let actx;
function beep(freq, dur) {
  try {
    actx = actx || new (window.AudioContext||window.webkitAudioContext)();
    const o = actx.createOscillator(); const g = actx.createGain();
    o.frequency.value = freq; o.type = 'square';
    g.gain.value = 0.05;
    o.connect(g); g.connect(actx.destination);
    o.start(); o.stop(actx.currentTime + dur);
  } catch(e){}
}
</script>
</body>
</html>
