<body>
<h1>⚔ Mots Croisés du Château de Rochechinard ⚔</h1>
<div class="subtitle">Découvrez l'histoire de ce village du Vercors</div>

<div class="container">
  <div>
    <div class="grid-wrap"><table id="grid"></table></div>
    <div class="controls">
      <button onclick="checkAll()">Vérifier</button>
      <button onclick="revealOne()">Indice (1 lettre)</button>
      <button onclick="resetGame()">Recommencer</button>
    </div>
    <div id="status"></div>
  </div>
  <div class="clues">
    <h2>📜 Définitions</h2>
    <ol id="cluelist"></ol>
  </div>
</div>

<script>
const ROWS = 8, COLS = 12;
const words = [
  { word:"ROCHECHINARD", row:1, col:0, dir:"H", num:2, clue:"Village du Vercors connu pour son château médiéval" },
  { word:"CHATEAU",      row:0, col:3, dir:"V", num:1, clue:"Construction fortifiée du Moyen Âge" },
  { word:"ROYANS",       row:1, col:0, dir:"V", num:2, clue:"Région naturelle du Dauphiné, au pied du Vercors" },
  { word:"ZIZIM",        row:0, col:7, dir:"V", num:3, clue:"Prince ottoman emprisonné au château au XVe siècle" },
  { word:"ALLEMAN",      row:1, col:9, dir:"V", num:4, clue:"Famille seigneuriale dauphinoise qui posséda le château" },
];

// Build grid solution map
let solution = {}; // "r,c" -> letter
let cellNums = {};
words.forEach(w => {
  for (let i=0;i<w.word.length;i++){
    const r = w.row + (w.dir==="V"?i:0);
    const c = w.col + (w.dir==="H"?i:0);
    solution[r+","+c] = w.word[i];
  }
  cellNums[w.row+","+w.col] = w.num;
});

// Audio
let audioCtx;
function beep(freq, dur=0.1, type="sine") {
  try {
    audioCtx = audioCtx || new (window.AudioContext||window.webkitAudioContext)();
    const o = audioCtx.createOscillator(), g = audioCtx.createGain();
    o.type=type; o.frequency.value=freq;
    o.connect(g); g.connect(audioCtx.destination);
    g.gain.setValueAtTime(0.15, audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime+dur);
    o.start(); o.stop(audioCtx.currentTime+dur);
  } catch(e){}
}

// Render grid
const grid = document.getElementById('grid');
for (let r=0;r<ROWS;r++){
  const tr=document.createElement('tr');
  for (let c=0;c<COLS;c++){
    const td=document.createElement('td');
    if (solution[r+","+c]) {
      td.className='cell';
      if (cellNums[r+","+c]) {
        const s=document.createElement('span');
        s.className='num'; s.textContent=cellNums[r+","+c];
        td.appendChild(s);
      }
      const inp=document.createElement('input');
      inp.maxLength=1;
      inp.dataset.r=r; inp.dataset.c=c;
      inp.addEventListener('input', onInput);
      inp.addEventListener('keydown', onKey);
      td.appendChild(inp);
    }
    tr.appendChild(td);
  }
  grid.appendChild(tr);
}

// Clues list
const cl = document.getElementById('cluelist');
words.forEach((w,i)=>{
  const li=document.createElement('li');
  li.innerHTML=`<b>${w.num}. ${w.dir==='H'?'→':'↓'}</b> ${w.clue} <i>(${w.word.length})</i>`;
  li.onclick = ()=>{
    const inp = document.querySelector(`input[data-r="${w.row}"][data-c="${w.col}"]`);
    if (inp) inp.focus();
  };
  li.dataset.idx=i;
  cl.appendChild(li);
});

function onInput(e){
  e.target.value = e.target.value.toUpperCase().replace(/[^A-Z]/g,'');
  e.target.classList.remove('wrong','correct');
  if (e.target.value) {
    beep(600,0.05);
    moveNext(e.target, 1);
  }
  checkWordsSolved();
}
function onKey(e){
  if (e.key==='Backspace' && !e.target.value){ moveNext(e.target,-1); }
  if (e.key==='ArrowRight') moveNext(e.target,1,'H');
  if (e.key==='ArrowLeft') moveNext(e.target,-1,'H');
  if (e.key==='ArrowDown') moveNext(e.target,1,'V');
  if (e.key==='ArrowUp') moveNext(e.target,-1,'V');
}
function moveNext(inp, delta, dir){
  let r=+inp.dataset.r, c=+inp.dataset.c;
  // default: try horizontal next, else vertical
  const tries = dir ? [dir] : ['H','V'];
  for (const d of tries) {
    const nr = r + (d==='V'?delta:0);
    const nc = c + (d==='H'?delta:0);
    const n = document.querySelector(`input[data-r="${nr}"][data-c="${nc}"]`);
    if (n){ n.focus(); n.select(); return; }
  }
}

function checkAll(){
  let allOk=true, anyFilled=false;
  document.querySelectorAll('#grid input').forEach(inp=>{
    const key=inp.dataset.r+","+inp.dataset.c;
    if (!inp.value){ allOk=false; return; }
    anyFilled=true;
    if (inp.value === solution[key]) inp.classList.add('correct'),inp.classList.remove('wrong');
    else { inp.classList.add('wrong'); inp.classList.remove('correct'); allOk=false; }
  });
  const st=document.getElementById('status');
  if (allOk){ st.textContent='🏆 Bravo ! Vous avez tout trouvé !'; st.className='win'; victory();}
  else if (anyFilled){ st.textContent='Quelques erreurs... continuez !'; st.className=''; beep(200,0.2,'square');}
}

function checkWordsSolved(){
  let allCells=true;
  words.forEach((w,i)=>{
    let ok=true;
    for (let j=0;j<w.word.length;j++){
      const r=w.row+(w.dir==='V'?j:0), c=w.col+(w.dir==='H'?j:0);
      const inp=document.querySelector(`input[data-r="${r}"][data-c="${c}"]`);
      if (!inp.value || inp.value!==w.word[j]) { ok=false; break; }
    }
    const li=cl.querySelector(`li[data-idx="${i}"]`);
    if (ok) li.classList.add('solved'); else li.classList.remove('solved');
    if (!ok) allCells=false;
  });
  if (allCells) checkAll();
}

function revealOne(){
  const empty=[...document.querySelectorAll('#grid input')].filter(i=>!i.value || i.value!==solution[i.dataset.r+","+i.dataset.c]);
  if (!empty.length) return;
  const pick=empty[Math.floor(Math.random()*empty.length)];
  pick.value=solution[pick.dataset.r+","+pick.dataset.c];
  pick.classList.add('correct');
  beep(800,0.1);
  checkWordsSolved();
}

function resetGame(){
  document.querySelectorAll('#grid input').forEach(i=>{i.value='';i.className='';});
  document.querySelectorAll('#cluelist li').forEach(l=>l.classList.remove('solved'));
  document.getElementById('status').textContent='';
}

function victory(){
  [523,659,784,1047].forEach((f,i)=>setTimeout(()=>beep(f,0.2),i*150));
}
</script>
</body>
</html>
