  #menu h1 { font-size:64px; color:#00ff88; text-shadow:0 0 20px #00ff88; letter-spacing:6px; margin-bottom:10px;}
  #menu h2 { font-size:20px; opacity:0.7; letter-spacing:3px; margin-bottom:30px;}
  #menu p { max-width:520px; margin-bottom:20px; line-height:1.7; opacity:0.85;}
  #menu button { padding:15px 50px; font-size:22px; background:#00ff88; color:#000; border:none; cursor:pointer; font-weight:bold; letter-spacing:2px; transition:.2s;}
  #menu button:hover { background:#fff; transform:scale(1.05); box-shadow:0 0 30px #00ff88;}
  .controls { display:grid; grid-template-columns:1fr 1fr; gap:8px 30px; margin:20px 0; font-size:14px; opacity:0.85;}
  .controls b { color:#00ff88;}
  #killFeed { position:absolute; top:20px; right:20px; text-align:right; font-size:14px;}
  .kill { background:rgba(0,0,0,0.5); padding:6px 10px; margin-bottom:4px; border-right:3px solid #ff3344;}
  #muzzle { position:absolute; top:50%; left:50%; width:60px; height:60px; transform:translate(-50%,-50%); background:radial-gradient(circle,#fff,#ff0,transparent 70%); opacity:0; pointer-events:none;}
  #gun { position:absolute; bottom:0; right:8%; width:340px; height:220px; pointer-events:none;}
</style>
</head>
<body>
<canvas id="game"></canvas>
<div id="hud">
  <div id="crosshair"><div class="dot"></div></div>
  <div id="muzzle"></div>
  <div id="hitMarker">✕</div>
  <div id="damageOverlay"></div>
  <svg id="gun" viewBox="0 0 340 220">
    <defs><linearGradient id="gm" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#444"/><stop offset="1" stop-color="#111"/></linearGradient></defs>
    <polygon points="0,220 340,220 340,140 200,140 180,100 80,100 60,140 0,140" fill="url(#gm)"/>
    <rect x="120" y="60" width="100" height="50" fill="#222"/>
    <rect x="210" y="130" width="120" height="14" fill="#0a0a0a"/>
    <circle cx="155" cy="170" r="10" fill="#000"/>
  </svg>
  <div id="topBar">
    <div id="score">0</div>
    <div id="wave">WAVE 1</div>
  </div>
  <div id="killFeed"></div>
  <div id="bottomBar">
    <div class="stat">HEALTH<br><span id="hpNum">100</span><div id="healthBar"><div id="healthFill"></div></div></div>
    <div class="stat" style="text-align:right;border-left:none;border-right:4px solid #ffaa00;">AMMO<br><span id="ammoNum">30</span> / <span id="reserveNum">90</span></div>
  </div>
</div>
<div id="menu">
  <h1>TACTICAL STRIKE</h1>
  <h2>FPS COMBAT</h2>
  <p>Bertahan dari gelombang musuh AI. Map luas, taktis, dan tanpa ampun. Setiap wave musuh semakin banyak dan kuat.</p>
  <div class="controls">
    <div><b>WASD</b> Gerak</div><div><b>MOUSE</b> Lihat / Tembak</div>
    <div><b>SHIFT</b> Lari</div><div><b>SPACE</b> Lompat</div>
    <div><b>R</b> Reload</div><div><b>ESC</b> Lepas Mouse</div>
  </div>
  <button id="startBtn">MULAI MISI</button>
</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/PointerLockControls.js"></script>
<script>
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x88aacc);
scene.fog = new THREE.Fog(0x88aacc, 50, 220);

const camera = new THREE.PerspectiveCamera(75, innerWidth/innerHeight, 0.1, 500);
const renderer = new THREE.WebGLRenderer({canvas:document.getElementById('game'), antialias:true});
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

// Lights
const sun = new THREE.DirectionalLight(0xffeecc, 1.0);
sun.position.set(60,80,30); sun.castShadow = true;
sun.shadow.mapSize.set(2048,2048);
sun.shadow.camera.left=-150; sun.shadow.camera.right=150;
sun.shadow.camera.top=150; sun.shadow.camera.bottom=-150;
scene.add(sun);
scene.add(new THREE.AmbientLight(0x8899bb, 0.5));
scene.add(new THREE.HemisphereLight(0xaaccff, 0x553322, 0.4));

// Ground
const groundGeo = new THREE.PlaneGeometry(400,400,40,40);
const groundMat = new THREE.MeshStandardMaterial({color:0x5a6b3a, roughness:1});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI/2; ground.receiveShadow = true;
scene.add(ground);

// Sand patches
for(let i=0;i<8;i++){
  const sand = new THREE.Mesh(new THREE.CircleGeometry(15+Math.random()*15,16), new THREE.MeshStandardMaterial({color:0xb89968,roughness:1}));
  sand.rotation.x=-Math.PI/2; sand.position.set((Math.random()-0.5)*300,0.01,(Math.random()-0.5)*300);
  scene.add(sand);
}

// Obstacles (buildings, crates, walls)
const obstacles = []; // {mesh, box}
function addBox(x,y,z,w,h,d,color){
  const m = new THREE.Mesh(new THREE.BoxGeometry(w,h,d), new THREE.MeshStandardMaterial({color, roughness:0.8}));
  m.position.set(x,y+h/2,z); m.castShadow=true; m.receiveShadow=true;
  scene.add(m);
  obstacles.push({mesh:m, box:new THREE.Box3().setFromObject(m)});
  return m;
}

// Buildings
const buildingColors=[0x8a7a6a,0x9a8a7a,0x7a6a5a,0xa89a82];
for(let i=0;i<14;i++){
  const w=8+Math.random()*10, d=8+Math.random()*10, h=6+Math.random()*10;
  const x=(Math.random()-0.5)*250, z=(Math.random()-0.5)*250;
  if(Math.abs(x)<10&&Math.abs(z)<10) continue;
  addBox(x,0,z,w,h,d,buildingColors[i%buildingColors.length]);
}
// Walls
for(let i=0;i<10;i++){
  addBox((Math.random()-0.5)*240,0,(Math.random()-0.5)*240, 12,3,1.2, 0x776655);
}
// Crates
for(let i=0;i<30;i++){
  const s=1.5+Math.random();
  addBox((Math.random()-0.5)*260,0,(Math.random()-0.5)*260, s,s,s, 0x6a4a2a);
}
// Perimeter walls
addBox(0,0,200,400,8,2,0x554433);
addBox(0,0,-200,400,8,2,0x554433);
addBox(200,0,0,2,8,400,0x554433);
addBox(-200,0,0,2,8,400,0x554433);

// Controls
const controls = new THREE.PointerLockControls(camera, document.body);
scene.add(controls.getObject());
controls.getObject().position.set(0,1.7,0);

const keys={};
addEventListener('keydown',e=>{keys[e.code]=true; if(e.code==='KeyR') reload();});
addEventListener('keyup',e=>{keys[e.code]=false;});

let velocity = new THREE.Vector3();
let canJump = false;

// Audio
const actx = new (window.AudioContext||window.webkitAudioContext)();
function beep(freq,dur,type='square',vol=0.1){
  const o=actx.createOscillator(), g=actx.createGain();
  o.type=type; o.frequency.value=freq;
  g.gain.setValueAtTime(vol,actx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001,actx.currentTime+dur);
  o.connect(g); g.connect(actx.destination); o.start(); o.stop(actx.currentTime+dur);
}
function shootSound(){ beep(180,0.08,'square',0.15); beep(80,0.1,'sawtooth',0.1);}
function hitSound(){ beep(600,0.05,'square',0.1);}
function enemyShootSound(){ beep(120,0.08,'sawtooth',0.06);}
function reloadSound(){ beep(300,0.1,'sine',0.08); setTimeout(()=>beep(400,0.1,'sine',0.08),200);}
function deathSound(){ beep(150,0.3,'sawtooth',0.15);}

// Player state
const player = {hp:100, score:0, ammo:30, reserve:90, magSize:30, alive:true};

// Enemies
const enemies = [];
function createEnemy(x,z,hp){
  const g = new THREE.Group();
  const bodyMat = new THREE.MeshStandardMaterial({color:0x553322});
  const headMat = new THREE.MeshStandardMaterial({color:0xddbb99});
  const body = new THREE.Mesh(new THREE.BoxGeometry(0.8,1.2,0.5), bodyMat); body.position.y=1.1; body.castShadow=true;
  const head = new THREE.Mesh(new THREE.BoxGeometry(0.5,0.5,0.5), headMat); head.position.y=2.0; head.castShadow=true;
  const legL = new THREE.Mesh(new THREE.BoxGeometry(0.3,1,0.3), bodyMat); legL.position.set(-0.2,0.5,0); legL.castShadow=true;
  const legR = new THREE.Mesh(new THREE.BoxGeometry(0.3,1,0.3), bodyMat); legR.position.set(0.2,0.5,0); legR.castShadow=true;
  const armL = new THREE.Mesh(new THREE.BoxGeometry(0.2,0.9,0.2), bodyMat); armL.position.set(-0.55,1.2,0.1);
  const armR = new THREE.Mesh(new THREE.BoxGeometry(0.2,0.9,0.2), bodyMat); armR.position.set(0.55,1.2,0.1);
  const gun = new THREE.Mesh(new THREE.BoxGeometry(0.15,0.15,0.8), new THREE.MeshStandardMaterial({color:0x222222}));
  gun.position.set(0.55,1.0,0.6);
  g.add(body,head,legL,legR,armL,armR,gun);
  g.position.set(x,0,z);
  scene.add(g);
  enemies.push({mesh:g, hp, maxHp:hp, legL,legR, lastShot:0, state:'patrol', target:new THREE.Vector3(x,0,z), shotCool:1.5+Math.random()});
}

// Wave system
let wave = 1;
function spawnWave(){
  document.getElementById('wave').textContent = `WAVE ${wave}`;
  const count = 3 + wave*2;
  for(let i=0;i<count;i++){
    let x,z, tries=0;
    do {
      const a=Math.random()*Math.PI*2;
      const r=40+Math.random()*120;
      x=Math.cos(a)*r; z=Math.sin(a)*r;
      tries++;
    } while(isBlocked(x,z) && tries<20);
    createEnemy(x,z, 30+wave*10);
  }
}

function isBlocked(x,z){
  const p=new THREE.Vector3(x,1,z);
  for(const o of obstacles){ if(o.box.containsPoint(p)) return true;}
  return false;
}

// Collision check
function collide(pos){
  const r = 0.4;
  for(const o of obstacles){
    const b = o.box;
    if(pos.x+r>b.min.x && pos.x-r<b.max.x && pos.z+r>b.min.z && pos.z-r<b.max.z && pos.y<b.max.y && pos.y+1.8>b.min.y){
      return true;
    }
  }
  return false;
}

// Shooting
let canShoot=true, reloading=false;
function shoot(){
  if(!controls.isLocked||!player.alive||reloading) return;
  if(player.ammo<=0){ reload(); return; }
  if(!canShoot) return;
  canShoot=false; setTimeout(()=>canShoot=true,100);
  player.ammo--;
  updateHUD();
  shootSound();
  flashMuzzle();
  recoil();
  // Raycast
  const ray = new THREE.Raycaster();
  ray.setFromCamera({x:0,y:0}, camera);
  // Check enemies
  let hits = [];
  for(const e of enemies){
    const inter = ray.intersectObject(e.mesh, true);
    if(inter.length) hits.push({e,dist:inter[0].distance, point:inter[0].point, obj:inter[0].object});
  }
  // Check obstacles
  let obDist = Infinity;
  for(const o of obstacles){
    const inter = ray.intersectObject(o.mesh);
    if(inter.length && inter[0].distance<obDist) obDist = inter[0].distance;
  }
  hits = hits.filter(h=>h.dist<obDist).sort((a,b)=>a.dist-b.dist);
  if(hits.length){
    const h = hits[0];
    const isHead = h.obj.position.y>1.8;
    const dmg = isHead?60:25;
    h.e.hp -= dmg;
    showHitMarker();
    hitSound();
    if(h.e.hp<=0) killEnemy(h.e, isHead);
  }
}
addEventListener('mousedown',e=>{if(e.button===0)shoot();});

function flashMuzzle(){
  const m=document.getElementById('muzzle');
  m.style.opacity=1;
  setTimeout(()=>m.style.opacity=0,50);
}
let recoilY=0;
function recoil(){ recoilY += 0.02; }

function showHitMarker(){
  const h=document.getElementById('hitMarker');
  h.style.opacity=1;
  clearTimeout(h._t); h._t=setTimeout(()=>h.style.opacity=0,150);
}

function killEnemy(e, headshot){
  scene.remove(e.mesh);
  const idx = enemies.indexOf(e); if(idx>=0) enemies.splice(idx,1);
  player.score += headshot?150:100;
  deathSound();
  addKill(headshot);
  updateHUD();
  if(enemies.length===0){
    wave++;
    player.reserve += 30;
    setTimeout(spawnWave, 2000);
  }
}

function addKill(hs){
  const kf = document.getElementById('killFeed');
  const d = document.createElement('div'); d.className='kill';
  d.innerHTML = `YOU ⟶ ENEMY ${hs?'<span style="color:#ff3344">[HEADSHOT]</span>':''}`;
  kf.prepend(d);
  setTimeout(()=>d.remove(),4000);
}

function reload(){
  if(reloading||player.ammo===player.magSize||player.reserve===0) return;
  reloading=true; reloadSound();
  setTimeout(()=>{
    const need = player.magSize-player.ammo;
    const give = Math.min(need, player.reserve);
    player.ammo+=give; player.reserve-=give;
    reloading=false; updateHUD();
  },1200);
}

function updateHUD(){
  document.getElementById('hpNum').textContent = Math.max(0,Math.floor(player.hp));
  document.getElementById('healthFill').style.width = Math.max(0,player.hp)+'%';
  document.getElementById('ammoNum').textContent = player.ammo;
  document.getElementById('reserveNum').textContent = player.reserve;
  document.getElementById('score').textContent = player.score;
}

// Damage player
function damagePlayer(d){
  if(!player.alive)return;
  player.hp-=d;
  const o=document.getElementById('damageOverlay');
  o.style.opacity=1; setTimeout(()=>o.style.opacity=0,300);
  updateHUD();
  if(player.hp<=0) gameOver();
}

function gameOver(){
  player.alive=false;
  controls.unlock();
  const m=document.getElementById('menu');
  m.style.display='flex';
  m.innerHTML=`<h1 style="color:#ff3344;text-shadow:0 0 20px #ff3344">MISSION FAILED</h1>
    <h2>SCORE: ${player.score} • WAVE ${wave}</h2>
    <button onclick="location.reload()">COBA LAGI</button>`;
}

// Enemy AI
const tmpV = new THREE.Vector3();
function updateEnemies(dt){
  const playerPos = controls.getObject().position;
  for(const e of enemies){
    const ep = e.mesh.position;
    const dist = ep.distanceTo(playerPos);
    // LOS check
    const dir = tmpV.subVectors(playerPos,ep).normalize();
    const ray = new THREE.Raycaster(ep.clone().setY(1.5), dir, 0, dist);
    let los=true;
    for(const o of obstacles){
      const inter = ray.intersectObject(o.mesh);
      if(inter.length){ los=false; break;}
    }
    e.mesh.lookAt(playerPos.x, ep.y+1.5, playerPos.z);

    if(los && dist<60){
      e.state='attack';
      // Move closer if far, strafe if close
      if(dist>15){
        const step = 2.5*dt;
        const newPos = ep.clone().add(dir.clone().multiplyScalar(step));
        if(!enemyBlocked(newPos)) ep.copy(newPos);
      }
      // Shoot
      e.lastShot += dt;
      if(e.lastShot > e.shotCool){
        e.lastShot=0;
        enemyShootSound();
        // Hit chance based on distance
        if(Math.random() < 0.35 - dist*0.003){
          damagePlayer(5 + wave);
        }
      }
      // Leg animation
      const t = performance.now()*0.008;
      e.legL.rotation.x = Math.sin(t)*0.5;
      e.legR.rotation.x = -Math.sin(t)*0.5;
    } else {
      // Patrol
      if(ep.distanceTo(e.target)<2){
        e.target.set((Math.random()-0.5)*300, 0, (Math.random()-0.5)*300);
      }
      const pd = tmpV.subVectors(e.target,ep).setY(0).normalize();
      const step = 1.5*dt;
      const newPos = ep.clone().add(pd.multiplyScalar(step));
      if(!enemyBlocked(newPos)) ep.copy(newPos);
      else e.target.set((Math.random()-0.5)*300,0,(Math.random()-0.5)*300);
      const t = performance.now()*0.005;
      e.legL.rotation.x = Math.sin(t)*0.3;
      e.legR.rotation.x = -Math.sin(t)*0.3;
    }
  }
}

function enemyBlocked(pos){
  for(const o of obstacles){
    const b = o.box;
    if(pos.x+0.5>b.min.x && pos.x-0.5<b.max.x && pos.z+0.5>b.min.z && pos.z-0.5<b.max.z && b.max.y>0.5){
      return true;
    }
  }
  return false;
}

// Main loop
let last = performance.now();
function animate(){
  requestAnimationFrame(animate);
  const now = performance.now();
  const dt = Math.min((now-last)/1000, 0.1); last = now;

  if(controls.isLocked && player.alive){
    const speed = (keys.ShiftLeft||keys.ShiftRight)?10:5.5;
    const forward = (keys.KeyW?1:0) - (keys.KeyS?1:0);
    const strafe = (keys.KeyD?1:0) - (keys.KeyA?1:0);

    velocity.x -= velocity.x*8*dt;
    velocity.z -= velocity.z*8*dt;
    velocity.y -= 25*dt;

    const dir = new THREE.Vector3();
    camera.getWorldDirection(dir); dir.y=0; dir.normalize();
    const right = new THREE.Vector3(dir.z,0,-dir.x);

    velocity.x += (dir.x*forward + right.x*strafe)*speed*dt*10;
    velocity.z += (dir.z*forward + right.z*strafe)*speed*dt*10;

    const obj = controls.getObject();
    const oldX = obj.position.x, oldZ = obj.position.z;

    obj.position.x += velocity.x*dt;
    if(collide(obj.position)) obj.position.x = oldX;
    obj.position.z += velocity.z*dt;
    if(collide(obj.position)) obj.position.z = oldZ;

    obj.position.y += velocity.y*dt;
    if(obj.position.y < 1.7){
      obj.position.y = 1.7; velocity.y = 0; canJump = true;
    }
    if(keys.Space && canJump){ velocity.y = 9; canJump=false;}

    // recoil decay
    if(recoilY>0){ camera.rotation.x += recoilY; recoilY*=0.5; if(recoilY<0.001)recoilY=0;}

    updateEnemies(dt);
  }

  renderer.render(scene,camera);
}
animate();

addEventListener('resize',()=>{
  camera.aspect = innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);
});

document.getElementById('startBtn').onclick=()=>{
  document.getElementById('menu').style.display='none';
  controls.lock();
  if(actx.state==='suspended') actx.resume();
  if(enemies.length===0) spawnWave();
};
updateHUD();
</script>
</body>
</html>
