  .overlay h1{font-size:64px;color:#ffdd33;text-shadow:4px 4px 0 #c0392b,8px 8px 0 rgba(0,0,0,.3);letter-spacing:2px;margin-bottom:10px;transform:rotate(-3deg)}
  .overlay p{font-size:18px;margin:8px 0;max-width:500px}
  .btn{margin-top:20px;padding:16px 40px;font-size:24px;font-weight:bold;color:#fff;background:linear-gradient(180deg,#ff8a3d,#e84118);border:4px solid #fff;border-radius:18px;cursor:pointer;box-shadow:0 6px 0 #b33218,0 10px 20px rgba(0,0,0,.4);transition:transform .1s}
  .btn:active{transform:translateY(4px);box-shadow:0 2px 0 #b33218}
  #hud{position:fixed;top:0;left:0;right:0;display:flex;justify-content:space-between;padding:14px 22px;color:#fff;font-weight:bold;font-size:22px;text-shadow:2px 2px 0 rgba(0,0,0,.6);z-index:5;pointer-events:none}
  #score{position:fixed;top:14px;left:50%;transform:translateX(-50%);font-size:38px;font-weight:bold;color:#fff;text-shadow:3px 3px 0 #c0392b,5px 5px 0 rgba(0,0,0,.4);z-index:5;pointer-events:none}
  #coins{color:#ffeb3b}
  .hidden{display:none!important}
  #powerup{position:fixed;top:70px;right:20px;width:60px;height:60px;border-radius:50%;background:rgba(0,0,0,.5);border:3px solid #ffeb3b;display:flex;align-items:center;justify-content:center;font-size:28px;z-index:5}
</style>
</head>
<body>
<div id="game"></div>
<div id="score">0</div>
<div id="hud"><div>🏃 LEBRON</div><div id="coins">🪙 0</div></div>
<div id="powerup" class="hidden">🧲</div>

<div id="startScreen" class="overlay">
  <h1>LEBRON SURFERS</h1>
  <p>Swipe or use ← → to switch lanes</p>
  <p>↑ / Space to JUMP &nbsp; ↓ to SLIDE</p>
  <p>Grab coins, dodge trains, snag power-ups!</p>
  <button class="btn" onclick="startGame()">PLAY</button>
</div>

<div id="overScreen" class="overlay hidden">
  <h1>BUSTED!</h1>
  <p>Score: <span id="finalScore">0</span></p>
  <p>Coins: <span id="finalCoins">0</span></p>
  <button class="btn" onclick="startGame()">RUN AGAIN</button>
</div>

<script type="importmap">
{ "imports": { "three": "https://unpkg.com/three@0.160.0/build/three.module.js" } }
</script>
<script type="module">
import * as THREE from 'three';

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87ceeb);
scene.fog = new THREE.Fog(0x87ceeb, 40, 120);

const camera = new THREE.PerspectiveCamera(70, innerWidth/innerHeight, 0.1, 300);
camera.position.set(0, 5, 8);
camera.lookAt(0, 1.5, -5);

const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio,2));
renderer.shadowMap.enabled = true;
document.getElementById('game').appendChild(renderer.domElement);

addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});

// Lights
scene.add(new THREE.AmbientLight(0xffffff,0.7));
const sun = new THREE.DirectionalLight(0xffffff,0.9);
sun.position.set(5,15,8); sun.castShadow=true;
sun.shadow.mapSize.set(1024,1024);
sun.shadow.camera.left=-20;sun.shadow.camera.right=20;sun.shadow.camera.top=20;sun.shadow.camera.bottom=-20;
scene.add(sun);

// Ground (segments scrolling)
const LANES = [-2.2, 0, 2.2];
const groundMat = new THREE.MeshLambertMaterial({color:0x8B7355});
const railMat = new THREE.MeshLambertMaterial({color:0x444444});
const sleeperMat = new THREE.MeshLambertMaterial({color:0x5a3a20});

const groundSegments = [];
function makeGroundSegment(z){
  const g = new THREE.Group();
  const base = new THREE.Mesh(new THREE.BoxGeometry(10,0.4,20), groundMat);
  base.position.y=-0.2; base.receiveShadow=true; g.add(base);
  // sleepers
  for(let i=0;i<10;i++){
    const s = new THREE.Mesh(new THREE.BoxGeometry(9,0.15,0.6), sleeperMat);
    s.position.set(0,0.05,-i*2+9); g.add(s);
  }
  // rails
  for(const lx of [-2.8,-1.6,-0.6,0.6,1.6,2.8]){
    const r = new THREE.Mesh(new THREE.BoxGeometry(0.12,0.15,20), railMat);
    r.position.set(lx,0.15,0); g.add(r);
  }
  g.position.z=z;
  scene.add(g);
  return g;
}
for(let i=0;i<6;i++) groundSegments.push(makeGroundSegment(-i*20+10));

// side scenery
const sideStuff=[];
function makeBuilding(z,side){
  const h = 6+Math.random()*10;
  const colors=[0xff6b6b,0x4ecdc4,0xffd166,0x95e1d3,0xf38181,0xaa96da];
  const b = new THREE.Mesh(new THREE.BoxGeometry(4,h,4), new THREE.MeshLambertMaterial({color:colors[Math.floor(Math.random()*colors.length)]}));
  b.position.set(side*9,h/2-0.2,z);
  b.castShadow=true;
  scene.add(b); sideStuff.push(b);
}
for(let i=0;i<20;i++){ makeBuilding(-i*8+10,-1); makeBuilding(-i*8+10,1); }

// Player
const player = new THREE.Group();
const skin = 0xc68863;
const body = new THREE.Mesh(new THREE.BoxGeometry(0.8,1,0.5), new THREE.MeshLambertMaterial({color:0xe74c3c}));
body.position.y=1.1; body.castShadow=true; player.add(body);
const head = new THREE.Mesh(new THREE.BoxGeometry(0.7,0.7,0.7), new THREE.MeshLambertMaterial({color:skin}));
head.position.y=2.0; head.castShadow=true; player.add(head);
const cap = new THREE.Mesh(new THREE.BoxGeometry(0.75,0.2,0.75), new THREE.MeshLambertMaterial({color:0xffeb3b}));
cap.position.y=2.4; player.add(cap);
const legL = new THREE.Mesh(new THREE.BoxGeometry(0.3,0.7,0.3), new THREE.MeshLambertMaterial({color:0x2980b9}));
legL.position.set(-0.2,0.4,0); legL.castShadow=true; player.add(legL);
const legR = legL.clone(); legR.position.x=0.2; player.add(legR);
const armL = new THREE.Mesh(new THREE.BoxGeometry(0.25,0.8,0.25), new THREE.MeshLambertMaterial({color:0xe74c3c}));
armL.position.set(-0.55,1.2,0); player.add(armL);
const armR = armL.clone(); armR.position.x=0.55; player.add(armR);
scene.add(player);

const state = {
  lane:1, targetX:0, y:0, vy:0, sliding:false, slideT:0,
  speed:0.5, score:0, coins:0, running:false,
  magnet:0, shield:0, jumpBoost:0, animT:0
};

// Obstacles & coins pool
const items = []; // {mesh,type,z,lane,...}

function spawnChunk(zStart){
  // coins line
  if(Math.random()<0.7){
    const lane = Math.floor(Math.random()*3);
    const cnt = 5+Math.floor(Math.random()*6);
    for(let i=0;i<cnt;i++){
      addCoin(LANES[lane], 0.9, zStart - i*1.4);
    }
  }
  // obstacles per lane
  const used = [false,false,false];
  const numObs = 1+Math.floor(Math.random()*2);
  for(let i=0;i<numObs;i++){
    let l = Math.floor(Math.random()*3);
    if(used[l]) continue;
    used[l]=true;
    const r = Math.random();
    if(r<0.4) addBarrier(l, zStart-3-Math.random()*4);
    else if(r<0.7) addTrain(l, zStart-5-Math.random()*4);
    else addOverhead(l, zStart-3-Math.random()*4);
  }
  // power-up sometimes
  if(Math.random()<0.15){
    const l = Math.floor(Math.random()*3);
    addPowerup(l, zStart-6);
  }
}

function addCoin(x,y,z){
  const m = new THREE.Mesh(new THREE.CylinderGeometry(0.35,0.35,0.08,16), new THREE.MeshLambertMaterial({color:0xffd700,emissive:0x554400}));
  m.rotation.x=Math.PI/2;
  m.position.set(x,y,z);
  scene.add(m);
  items.push({mesh:m,type:'coin',r:0.4});
}
function addBarrier(lane,z){
  const m = new THREE.Mesh(new THREE.BoxGeometry(1.6,1,0.4), new THREE.MeshLambertMaterial({color:0xf39c12}));
  m.position.set(LANES[lane],0.5,z); m.castShadow=true;
  scene.add(m);
  items.push({mesh:m,type:'barrier',w:1.6,h:1,d:0.4});
}
function addTrain(lane,z){
  const m = new THREE.Mesh(new THREE.BoxGeometry(1.8,2.2,10), new THREE.MeshLambertMaterial({color:Math.random()<0.5?0xe74c3c:0x3498db}));
  m.position.set(LANES[lane],1.1,z); m.castShadow=true;
  scene.add(m);
  items.push({mesh:m,type:'train',w:1.8,h:2.2,d:10});
}
function addOverhead(lane,z){
  const m = new THREE.Mesh(new THREE.BoxGeometry(2,0.4,0.5), new THREE.MeshLambertMaterial({color:0xe67e22}));
  m.position.set(LANES[lane],2.2,z); m.castShadow=true;
  scene.add(m);
  items.push({mesh:m,type:'overhead',w:2,h:0.4,d:0.5});
}
function addPowerup(lane,z){
  const types=[{c:0xff3355,k:'magnet'},{c:0x2ecc71,k:'jump'},{c:0xf1c40f,k:'shield'}];
  const t = types[Math.floor(Math.random()*types.length)];
  const m = new THREE.Mesh(new THREE.IcosahedronGeometry(0.5,0), new THREE.MeshLambertMaterial({color:t.c,emissive:t.c,emissiveIntensity:0.4}));
  m.position.set(LANES[lane],1.2,z);
  scene.add(m);
  items.push({mesh:m,type:'powerup',kind:t.k,r:0.7});
}

// Audio
let actx;
function beep(freq,dur=0.1,type='square',vol=0.1){
  if(!actx) return;
  const o=actx.createOscillator(),g=actx.createGain();
  o.type=type;o.frequency.value=freq;
  g.gain.value=vol;
  o.connect(g);g.connect(actx.destination);
  o.start();g.gain.exponentialRampToValueAtTime(0.001,actx.currentTime+dur);
  o.stop(actx.currentTime+dur);
}

// Input
function moveLane(d){
  state.lane = Math.max(0,Math.min(2,state.lane+d));
  state.targetX = LANES[state.lane];
  beep(440,0.05,'sine',0.05);
}
function jump(){
  if(state.y<=0.01 && !state.sliding){
    state.vy = state.jumpBoost>0 ? 0.42 : 0.32;
    beep(660,0.15,'sine',0.08);
  }
}
function slide(){
  if(state.y<=0.01 && !state.sliding){
    state.sliding=true; state.slideT=0.7;
    body.scale.y=0.5; body.position.y=0.6;
    head.position.y=1.2;
    beep(220,0.2,'sawtooth',0.06);
  }
}

addEventListener('keydown',e=>{
  if(!state.running) return;
  if(e.key==='ArrowLeft'||e.key==='a') moveLane(-1);
  else if(e.key==='ArrowRight'||e.key==='d') moveLane(1);
  else if(e.key==='ArrowUp'||e.key==='w'||e.key===' ') jump();
  else if(e.key==='ArrowDown'||e.key==='s') slide();
});

// Touch
let tx0=0,ty0=0;
addEventListener('touchstart',e=>{tx0=e.touches[0].clientX;ty0=e.touches[0].clientY});
addEventListener('touchend',e=>{
  if(!state.running) return;
  const dx=e.changedTouches[0].clientX-tx0, dy=e.changedTouches[0].clientY-ty0;
  if(Math.abs(dx)>Math.abs(dy)){
    if(dx>30) moveLane(1); else if(dx<-30) moveLane(-1);
  } else {
    if(dy<-30) jump(); else if(dy>30) slide();
  }
});

window.startGame = function(){
  document.getElementById('startScreen').classList.add('hidden');
  document.getElementById('overScreen').classList.add('hidden');
  if(!actx) actx = new (window.AudioContext||window.webkitAudioContext)();
  // reset
  for(const it of items){ scene.remove(it.mesh); }
  items.length=0;
  state.lane=1;state.targetX=0;state.y=0;state.vy=0;state.sliding=false;
  state.speed=0.5;state.score=0;state.coins=0;state.running=true;
  state.magnet=0;state.shield=0;state.jumpBoost=0;
  body.scale.y=1;body.position.y=1.1;head.position.y=2.0;
  player.position.set(0,0,0);
  for(let i=0;i<8;i++) spawnChunk(-10-i*18);
  lastSpawnZ = -10-8*18;
};

let lastSpawnZ = -10;

function gameOver(){
  state.running=false;
  beep(150,0.4,'sawtooth',0.15);
  document.getElementById('finalScore').textContent=Math.floor(state.score);
  document.getElementById('finalCoins').textContent=state.coins;
  document.getElementById('overScreen').classList.remove('hidden');
}

const clock = new THREE.Clock();
function animate(){
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(),0.05);

  if(state.running){
    state.speed = Math.min(1.2, state.speed + dt*0.02);
    state.score += state.speed*dt*40;
    document.getElementById('score').textContent = Math.floor(state.score);

    // lane lerp
    player.position.x += (state.targetX - player.position.x)*0.2;

    // jump
    state.vy -= 0.025;
    state.y += state.vy;
    if(state.y<0){state.y=0;state.vy=0;}
    player.position.y = state.y;

    // slide timer
    if(state.sliding){
      state.slideT -= dt;
      if(state.slideT<=0){ state.sliding=false; body.scale.y=1; body.position.y=1.1; head.position.y=2.0; }
    }

    // run anim
    state.animT += dt*15;
    const sw = Math.sin(state.animT)*0.5;
    if(state.y<0.05 && !state.sliding){
      legL.rotation.x = sw; legR.rotation.x = -sw;
      armL.rotation.x = -sw; armR.rotation.x = sw;
    } else {
      legL.rotation.x=-0.3;legR.rotation.x=0.3;
    }

    // scroll ground
    const move = state.speed;
    for(const g of groundSegments){
      g.position.z += move;
      if(g.position.z>30) g.position.z -= 6*20;
    }
    for(const b of sideStuff){
      b.position.z += move;
      if(b.position.z>20) b.position.z -= 160;
    }

    // items
    for(let i=items.length-1;i>=0;i--){
      const it = items[i];
      it.mesh.position.z += move;
      if(it.type==='coin'){
        it.mesh.rotation.z += 0.15;
        // magnet
        if(state.magnet>0){
          const dx=player.position.x-it.mesh.position.x, dz=player.position.z-it.mesh.position.z;
          if(Math.abs(dz)<8){
            it.mesh.position.x += dx*0.15;
            it.mesh.position.y += (1-it.mesh.position.y)*0.1;
          }
        }
      } else if(it.type==='powerup'){
        it.mesh.rotation.y += 0.05; it.mesh.rotation.x += 0.03;
      }
      // collision
      const dz = it.mesh.position.z - player.position.z;
      if(Math.abs(dz)<1.2 || (it.type==='train' && dz<5 && dz>-5)){
        const dx = Math.abs(it.mesh.position.x - player.position.x);
        if(it.type==='coin' && dx<0.8 && Math.abs(it.mesh.position.y-(player.position.y+1))<1.2 && Math.abs(dz)<0.8){
          state.coins++; state.score+=10;
          document.getElementById('coins').textContent='🪙 '+state.coins;
          beep(880+Math.random()*200,0.08,'sine',0.08);
          scene.remove(it.mesh); items.splice(i,1); continue;
        }
        if(it.type==='powerup' && dx<1 && Math.abs(dz)<1){
          activatePower(it.kind);
          scene.remove(it.mesh); items.splice(i,1); continue;
        }
        if(it.type==='barrier' && dx<1.2 && Math.abs(dz)<0.6){
          if(state.y < 0.7 && !state.sliding) hit();
        }
        if(it.type==='train' && dx<1.4 && dz>-5 && dz<5){
          if(state.y < 1.5) hit();
        }
        if(it.type==='overhead' && dx<1.2 && Math.abs(dz)<0.4){
          if(!state.sliding) hit();
        }
      }
      if(it.mesh.position.z > 15){ scene.remove(it.mesh); items.splice(i,1); }
    }

    // spawn more
    lastSpawnZ += move;
    if(lastSpawnZ > -80){
      spawnChunk(lastSpawnZ - 18);
      lastSpawnZ -= 18;
    }

    // powerup timers
    if(state.magnet>0) state.magnet -= dt;
    if(state.shield>0) state.shield -= dt;
    if(state.jumpBoost>0) state.jumpBoost -= dt;
    updatePowerHud();
  }

  renderer.render(scene,camera);
}

function activatePower(k){
  beep(1200,0.2,'sine',0.1);
  if(k==='magnet') state.magnet=8;
  else if(k==='jump'){ state.jumpBoost=8; }
  else if(k==='shield') state.shield=8;
}
function updatePowerHud(){
  const el=document.getElementById('powerup');
  if(state.magnet>0){el.classList.remove('hidden');el.textContent='🧲';}
  else if(state.shield>0){el.classList.remove('hidden');el.textContent='⭐';}
  else if(state.jumpBoost>0){el.classList.remove('hidden');el.textContent='👟';}
  else el.classList.add('hidden');
}

function hit(){
  if(state.shield>0){
    state.shield=0;
    beep(300,0.3,'square',0.1);
    return;
  }
  gameOver();
}

animate();
</script>
</body>
</html>
