<body>
<div id="game">
  <div class="topbar">
    <div class="stat">🥕 <span class="v" id="carrots">0</span></div>
    <div class="stat">⏱ <span class="v" id="cps">0</span>/초</div>
    <div class="stat">🐰 Lv<span class="v" id="maxlv">1</span></div>
  </div>

  <div class="clicker" id="clicker">🥕</div>
  <div class="hint">당근을 탭! · 토끼를 드래그해서 합치기!</div>

  <div class="grid" id="grid"></div>

  <div class="actions">
    <button class="btn" id="buyBtn">🐰 토끼 사기 (10🥕)</button>
    <button class="btn" id="resetBtn">↺ 리셋</button>
  </div>

  <div class="overlay" id="startScreen">
    <h1>🐰 토끼 농장 🥕</h1>
    <p>당근을 클릭해 모으세요!<br>토끼를 사서 농장에 배치하고,<br>같은 레벨 토끼를 드래그해서 합치면<br>더 많은 당근을 생산해요!</p>
    <button class="btn bounce" style="max-width:200px" id="startBtn">시작하기</button>
  </div>
</div>

<script>
const RABBITS = ['🐰','🐇','🐰','🦙','🦝','🦊','🐼','🐯','🦁','🐲','👑','✨'];
const state = {
  carrots: 0,
  clickPower: 1,
  cells: new Array(16).fill(0), // level, 0 = empty
  buyCost: 10,
  buyLevel: 1,
};

const $ = id => document.getElementById(id);
const gridEl = $('grid');
const cells = [];
for (let i=0;i<16;i++){
  const c = document.createElement('div');
  c.className = 'cell';
  c.dataset.idx = i;
  gridEl.appendChild(c);
  cells.push(c);
}

// Audio
let audioCtx;
function beep(freq=440, dur=0.08, type='square', vol=0.1){
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext||window.webkitAudioContext)();
    const o = audioCtx.createOscillator();
    const g = audioCtx.createGain();
    o.type = type; o.frequency.value = freq;
    g.gain.value = vol;
    o.connect(g); g.connect(audioCtx.destination);
    o.start();
    g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + dur);
    o.stop(audioCtx.currentTime + dur);
  } catch(e){}
}

function rateOf(lvl){ return lvl === 0 ? 0 : Math.floor(Math.pow(1.8, lvl-1) * 1); }
function cpsTotal(){ return state.cells.reduce((s,l)=>s+rateOf(l),0); }
function maxLevel(){ return Math.max(...state.cells, 0); }

function render(){
  $('carrots').textContent = Math.floor(state.carrots);
  $('cps').textContent = cpsTotal();
  $('maxlv').textContent = maxLevel();
  state.cells.forEach((lvl, i)=>{
    const c = cells[i];
    if (lvl > 0){
      c.classList.add('has');
      c.innerHTML = `<span class="emoji">${RABBITS[Math.min(lvl-1, RABBITS.length-1)]}</span><span class="lvl">L${lvl}</span><span class="rate">+${rateOf(lvl)}</span>`;
    } else {
      c.classList.remove('has');
      c.innerHTML = '';
    }
  });
  $('buyBtn').textContent = `🐰 토끼 사기 (${state.buyCost}🥕)`;
  $('buyBtn').disabled = state.carrots < state.buyCost || !state.cells.includes(0);
}

function floatText(x, y, txt){
  const f = document.createElement('div');
  f.className = 'float';
  f.textContent = txt;
  f.style.left = x+'px'; f.style.top = y+'px';
  document.body.appendChild(f);
  setTimeout(()=>f.remove(), 800);
}

$('clicker').addEventListener('pointerdown', e=>{
  state.carrots += state.clickPower;
  beep(600 + Math.random()*100, 0.05, 'triangle', 0.08);
  floatText(e.clientX, e.clientY, '+'+state.clickPower);
  render();
});

$('buyBtn').addEventListener('click', ()=>{
  if (state.carrots < state.buyCost) return;
  const empty = state.cells.indexOf(0);
  if (empty < 0) return;
  state.carrots -= state.buyCost;
  state.cells[empty] = state.buyLevel;
  state.buyCost = Math.floor(state.buyCost * 1.35);
  // increase buy level over time
  if (state.buyCost > 500 && state.buyLevel < 3) state.buyLevel = 2;
  if (state.buyCost > 5000 && state.buyLevel < 4) state.buyLevel = 3;
  beep(800, 0.1, 'sine', 0.1);
  render();
});

$('resetBtn').addEventListener('click', ()=>{
  if (!confirm('정말 리셋할까요?')) return;
  state.carrots = 0; state.clickPower = 1;
  state.cells = new Array(16).fill(0);
  state.buyCost = 10; state.buyLevel = 1;
  localStorage.removeItem('rabbitFarm');
  render();
});

$('startBtn').addEventListener('click', ()=>{
  $('startScreen').style.display = 'none';
  if (!audioCtx) try{ audioCtx = new (window.AudioContext||window.webkitAudioContext)(); }catch(e){}
});

// Drag & drop merge
let dragging = null; // {idx, lvl, el}
let dropTarget = null;

function startDrag(idx, x, y){
  if (state.cells[idx] === 0) return;
  const el = document.createElement('div');
  el.className = 'dragging';
  el.textContent = RABBITS[Math.min(state.cells[idx]-1, RABBITS.length-1)];
  el.style.left = x+'px'; el.style.top = y+'px';
  document.body.appendChild(el);
  dragging = { idx, lvl: state.cells[idx], el };
}

function moveDrag(x, y){
  if (!dragging) return;
  dragging.el.style.left = x+'px';
  dragging.el.style.top = y+'px';
  const elBelow = document.elementFromPoint(x,y);
  cells.forEach(c=>c.classList.remove('drop'));
  if (elBelow){
    const cell = elBelow.closest('.cell');
    if (cell && +cell.dataset.idx !== dragging.idx){
      const ti = +cell.dataset.idx;
      if (state.cells[ti] === dragging.lvl || state.cells[ti] === 0){
        cell.classList.add('drop');
        dropTarget = ti;
        return;
      }
    }
  }
  dropTarget = null;
}

function endDrag(){
  if (!dragging) return;
  cells.forEach(c=>c.classList.remove('drop'));
  if (dropTarget !== null){
    const ti = dropTarget;
    const si = dragging.idx;
    if (state.cells[ti] === dragging.lvl){
      // merge
      state.cells[ti] = dragging.lvl + 1;
      state.cells[si] = 0;
      beep(1000, 0.15, 'sine', 0.15);
      setTimeout(()=>beep(1400, 0.15, 'sine', 0.15), 80);
    } else if (state.cells[ti] === 0){
      state.cells[ti] = dragging.lvl;
      state.cells[si] = 0;
      beep(500, 0.05, 'triangle', 0.08);
    }
  }
  dragging.el.remove();
  dragging = null; dropTarget = null;
  render();
}

gridEl.addEventListener('pointerdown', e=>{
  const cell = e.target.closest('.cell');
  if (!cell) return;
  const idx = +cell.dataset.idx;
  if (state.cells[idx] === 0) return;
  startDrag(idx, e.clientX, e.clientY);
  e.preventDefault();
});
window.addEventListener('pointermove', e=>{
  if (dragging) { moveDrag(e.clientX, e.clientY); e.preventDefault(); }
});
window.addEventListener('pointerup', endDrag);
window.addEventListener('pointercancel', endDrag);

// Idle generation
let lastTime = Date.now();
setInterval(()=>{
  const now = Date.now();
  const dt = (now - lastTime)/1000;
  lastTime = now;
  state.carrots += cpsTotal() * dt;
  render();
  save();
}, 200);

// Save/load
function save(){
  try { localStorage.setItem('rabbitFarm', JSON.stringify({
    carrots: state.carrots, cells: state.cells,
    buyCost: state.buyCost, buyLevel: state.buyLevel, t: Date.now()
  })); } catch(e){}
}
function load(){
  try {
    const s = JSON.parse(localStorage.getItem('rabbitFarm'));
    if (s){
      state.carrots = s.carrots || 0;
      state.cells = s.cells || state.cells;
      state.buyCost = s.buyCost || 10;
      state.buyLevel = s.buyLevel || 1;
      // offline gain (capped)
      if (s.t){
        const off = Math.min((Date.now() - s.t)/1000, 3600*4);
        state.carrots += cpsTotal() * off;
      }
    }
  } catch(e){}
}
load();
render();
</script>
</body>
</html>
