<body>
<h1>⚔ Le Survivant ⚔</h1>
<div class="container">
  <div class="stats">
    <div class="stat"><span class="stat-label">❤ Vie</span><span class="stat-value" id="hp">100</span></div>
    <div class="stat"><span class="stat-label">🍖 Faim</span><span class="stat-value" id="food">50</span></div>
    <div class="stat"><span class="stat-label">💧 Eau</span><span class="stat-value" id="water">50</span></div>
