    <p><b>Conseil:</b> Reposez-vous pour récupérer de la vie, mais cela consomme nourriture et eau.</p>
    <button id="startBtn">Commencer l'aventure</button>
  </div>
</div>

<div class="overlay hidden" id="endOverlay">
  <div class="modal">
    <h2 id="endTitle">Fin</h2>
    <p id="endMsg"></p>
    <button id="endBtn">Rejouer</button>
  </div>
</div>

<script>
const BOARD_SIZE = 8;
const path = [];
// Build serpentine path
for (let r = 0; r < BOARD_SIZE; r++) {
  const row = [];
  for (let c = 0; c < BOARD_SIZE; c++) row.push(c);
  if (r % 2 === 1) row.reverse();
  row.forEach(c => path.push(r * BOARD_SIZE + c));
}

const state = {
  hp: 100, food: 50, water: 50, gold: 0, day: 1,
  pos: 0, alive: true, won: false
};

const boardEl = document.getElementById('board');
const logEl = document.getElementById('log');
const diceEl = document.getElementById('dice');

function buildBoard() {
  boardEl.innerHTML = '';
  for (let i = 0; i < BOARD_SIZE * BOARD_SIZE; i++) {
    const cell = document.createElement('div');
    cell.className = 'cell';
    const pIdx = path.indexOf(i);
    if (pIdx >= 0) {
      cell.classList.add('path');
      if (pIdx === 0) { cell.classList.add('start'); cell.textContent = '🏕'; }
      else if (pIdx === path.length - 1) { cell.classList.add('end'); cell.textContent = '🏁'; }
      else {
        // Random terrain icon based on position
        const icons = ['🌲','🪨','🌿','💧','🔥','⛰','🌵','🦴'];
        cell.textContent = icons[pIdx % icons.length];
      }
    }
    cell.dataset.idx = i;
    boardEl.appendChild(cell);
  }
  updatePlayer();
}

function updatePlayer() {
  document.querySelectorAll('.cell').forEach(c => c.classList.remove('player'));
  const cell = boardEl.children[path[state.pos]];
  cell.classList.add('player');
}

function updateStats() {
  document.getElementById('hp').textContent = state.hp;
  document.getElementById('food').textContent = state.food;
  document.getElementById('water').textContent = state.water;
  document.getElementById('gold').textContent = state.gold;
  document.getElementById('day').textContent = state.day;
}

function log(msg, type='') {
  const e = document.createElement('div');
  e.className = 'log-entry ' + type;
  e.textContent = msg;
  logEl.insertBefore(e, logEl.firstChild);
  while (logEl.children.length > 20) logEl.removeChild(logEl.lastChild);
}

// Sound effects
let audioCtx;
function beep(freq, dur, type='sine') {
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    const o = audioCtx.createOscillator();
    const g = audioCtx.createGain();
    o.type = type; o.frequency.value = freq;
    o.connect(g); g.connect(audioCtx.destination);
    g.gain.setValueAtTime(0.2, audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
    o.start(); o.stop(audioCtx.currentTime + dur);
  } catch(e){}
}

const events = [
  { msg: '🍎 Vous trouvez des fruits sauvages !', effect: () => { state.food += 15; }, type: 'good', sound: () => beep(660, 0.2) },
  { msg: '💧 Une source d\'eau pure !', effect: () => { state.water += 20; }, type: 'good', sound: () => beep(880, 0.2) },
  { msg: '🪙 Vous trouvez un coffre avec de l\'or !', effect: () => { state.gold += Math.floor(Math.random()*20)+5; }, type: 'good', sound: () => beep(1000, 0.3) },
  { msg: '🐺 Un loup vous attaque !', effect: () => { state.hp -= 15; }, type: 'bad', sound: () => beep(150, 0.4, 'sawtooth') },
  { msg: '🌧 Tempête ! Vous êtes épuisé.', effect: () => { state.hp -= 5; state.food -= 5; }, type: 'bad', sound: () => beep(200, 0.3, 'sawtooth') },
  { msg: '🐍 Morsure de serpent !', effect: () => { state.hp -= 20; }, type: 'bad', sound: () => beep(180, 0.3, 'square') },
  { msg: '🍄 Champignons comestibles trouvés.', effect: () => { state.food += 10; }, type: 'good', sound: () => beep(550, 0.2) },
  { msg: '🦌 Vous chassez un cerf !', effect: () => { state.food += 25; state.hp -= 5; }, type: 'good', sound: () => beep(700, 0.25) },
  { msg: '🔥 Un feu de camp abandonné vous réchauffe.', effect: () => { state.hp += 10; }, type: 'good', sound: () => beep(500, 0.2) },
  { msg: '⚡ Un éclair vous frôle !', effect: () => { state.hp -= 10; }, type: 'bad', sound: () => beep(300, 0.2, 'sawtooth') },
  { msg: '🗡 Vous trouvez une arme et chassez avec succès.', effect: () => { state.food += 15; state.gold += 5; }, type: 'good', sound: () => beep(800, 0.2) },
  { msg: '😴 Vous voyagez calmement.', effect: () => {}, type: 'event', sound: () => beep(440, 0.1) },
];

function triggerEvent() {
  const ev = events[Math.floor(Math.random() * events.length)];
  ev.effect();
  ev.sound();
  log(ev.msg, ev.type);
}

function passTime(steps) {
  state.food -= steps * 2;
  state.water -= steps * 3;
  if (state.food < 0) { state.hp += state.food; state.food = 0; log('🍖 Vous avez faim ! Perte de vie.', 'bad'); }
  if (state.water < 0) { state.hp += state.water * 2; state.water = 0; log('💧 Déshydratation ! Perte de vie.', 'bad'); }
  state.food = Math.min(100, state.food);
  state.water = Math.min(100, state.water);
  state.hp = Math.min(100, state.hp);
}

function checkEnd() {
  if (state.hp <= 0) {
    state.hp = 0;
    state.alive = false;
    showEnd(false);
    return true;
  }
  if (state.pos >= path.length - 1) {
    state.won = true;
    showEnd(true);
    return true;
  }
  return false;
}

function showEnd(won) {
  document.getElementById('endTitle').textContent = won ? '🏆 Victoire !' : '💀 Game Over';
  document.getElementById('endMsg').textContent = won
    ? `Vous avez survécu ! Or amassé : ${state.gold}, Jours: ${state.day}`
    : `Vous avez péri au jour ${state.day}. Or amassé: ${state.gold}`;
  document.getElementById('endOverlay').classList.remove('hidden');
  if (won) { beep(660, 0.2); setTimeout(()=>beep(880,0.3), 200); }
  else beep(100, 0.8, 'sawtooth');
}

async function rollDice() {
  if (!state.alive || state.won) return;
  document.getElementById('rollBtn').disabled = true;
  document.getElementById('restBtn').disabled = true;
  diceEl.classList.add('rolling');
  beep(440, 0.1);
  await new Promise(r => setTimeout(r, 400));
  const roll = Math.floor(Math.random() * 6) + 1;
  diceEl.classList.remove('rolling');
  diceEl.textContent = ['⚀','⚁','⚂','⚃','⚄','⚅'][roll-1];
  log(`🎲 Vous lancez ${roll}`, 'event');

  for (let i = 0; i < roll; i++) {
    if (state.pos < path.length - 1) state.pos++;
    updatePlayer();
    beep(500 + i*40, 0.08);
    await new Promise(r => setTimeout(r, 200));
  }
  passTime(roll);
  state.day++;
  triggerEvent();
  updateStats();
  if (!checkEnd()) {
    document.getElementById('rollBtn').disabled = false;
    document.getElementById('restBtn').disabled = false;
  }
}

function rest() {
  if (!state.alive || state.won) return;
  if (state.food < 5 || state.water < 5) {
    log('Pas assez de nourriture/eau pour se reposer !', 'bad');
    return;
  }
  state.hp += 20;
  state.food -= 5;
  state.water -= 5;
  state.day++;
  if (state.hp > 100) state.hp = 100;
  log('💤 Vous vous reposez et récupérez 20 PV.', 'good');
  beep(330, 0.3);
  updateStats();
  checkEnd();
}

function reset() {
  state.hp = 100; state.food = 50; state.water = 50;
  state.gold = 0; state.day = 1; state.pos = 0;
  state.alive = true; state.won = false;
  diceEl.textContent = '🎲';
  logEl.innerHTML = '';
  log('🏕 L\'aventure commence...', 'event');
  buildBoard();
