    </div>
    <button id="startBtn" style="margin-top:24px">▶ Enable Camera & Start</button>
    <p id="status" style="margin-top:14px;font-size:13px;color:#ffa;"></p>
  </div>
</div>

<script>
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const video = document.getElementById('cam');
  const overlay = document.getElementById('overlay');
  const startBtn = document.getElementById('startBtn');
  const statusEl = document.getElementById('status');
  const scoreEl = document.getElementById('score');
  const livesEl = document.getElementById('lives');
  const levelEl = document.getElementById('level');
  const gestureFill = document.getElementById('gestureFill');

  const W = canvas.width, H = canvas.height;

  // Motion detection canvas
  const motionCanvas = document.createElement('canvas');
  motionCanvas.width = 80; motionCanvas.height = 60;
  const mctx = motionCanvas.getContext('2d', { willReadFrequently: true });
  let prevFrame = null;

  // Game state
  let state = 'menu'; // menu | playing | gameover
  let paddleX = W / 2, paddleTargetX = W / 2;
  const paddleW = 140, paddleH = 18;
  const paddleY = H - 60;
  let blocks = [];
  let particles = [];
  let score = 0, lives = 3, level = 1;
  let spawnTimer = 0, spawnInterval = 70;
  let frame = 0;
  let motionStrength = 0;

  // Audio
  let audioCtx;
  function beep(freq, dur, type='sine', vol=0.15) {
    if (!audioCtx) return;
    const o = audioCtx.createOscillator();
    const g = audioCtx.createGain();
    o.type = type; o.frequency.value = freq;
    g.gain.setValueAtTime(vol, audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
    o.connect(g); g.connect(audioCtx.destination);
    o.start(); o.stop(audioCtx.currentTime + dur);
  }

  async function initCamera() {
    statusEl.textContent = 'Requesting camera...';
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: 320, height: 240, facingMode: 'user' }, audio: false
      });
      video.srcObject = stream;
      await new Promise(r => video.onloadedmetadata = r);
      statusEl.textContent = '';
      return true;
    } catch (e) {
      statusEl.textContent = '⚠ Camera unavailable. Use ← → keys or mouse to play.';
      return false;
    }
  }

  function detectMotion() {
    if (!video.videoWidth) return;
    mctx.save();
    mctx.scale(-1, 1); // mirror
    mctx.drawImage(video, -motionCanvas.width, 0, motionCanvas.width, motionCanvas.height);
    mctx.restore();
    const frameData = mctx.getImageData(0, 0, motionCanvas.width, motionCanvas.height);
    const data = frameData.data;
    if (!prevFrame) { prevFrame = new Uint8ClampedArray(data); return; }

    let sumX = 0, count = 0, totalDiff = 0;
    const w = motionCanvas.width, h = motionCanvas.height;
    for (let y = 0; y < h; y++) {
      for (let x = 0; x < w; x++) {
        const i = (y * w + x) * 4;
        const dr = Math.abs(data[i] - prevFrame[i]);
        const dg = Math.abs(data[i+1] - prevFrame[i+1]);
        const db = Math.abs(data[i+2] - prevFrame[i+2]);
        const diff = dr + dg + db;
        if (diff > 60) {
          sumX += x;
          count++;
          totalDiff += diff;
        }
      }
    }
    prevFrame.set(data);
    motionStrength = Math.min(1, count / 400);
    gestureFill.style.height = (motionStrength * 100) + '%';

    if (count > 25) {
      const avgX = sumX / count / w; // 0..1
      paddleTargetX = avgX * W;
    }
  }

  function spawnBlock() {
    const r = Math.random();
    let type;
    if (r < 0.18) type = 'bonus';
    else if (r < 0.65) type = 'good';
    else type = 'bad';
    blocks.push({
      x: 40 + Math.random() * (W - 80),
      y: -40,
      w: 50, h: 50,
      vy: 2 + Math.random() * 1.5 + level * 0.5,
      type,
      rot: 0,
      vr: (Math.random() - 0.5) * 0.05
    });
  }

  function addParticles(x, y, color, n=20) {
    for (let i = 0; i < n; i++) {
      particles.push({
        x, y,
        vx: (Math.random() - 0.5) * 6,
        vy: (Math.random() - 0.5) * 6 - 2,
        life: 40, max: 40,
        color
      });
    }
  }

  function update() {
    frame++;
    if (state !== 'playing') return;

    // Smooth paddle
    paddleX += (paddleTargetX - paddleX) * 0.25;
    paddleX = Math.max(paddleW/2, Math.min(W - paddleW/2, paddleX));

    // Spawn
    spawnTimer++;
    if (spawnTimer >= spawnInterval) {
      spawnTimer = 0;
      spawnBlock();
    }

    // Level up
    const newLevel = 1 + Math.floor(score / 100);
    if (newLevel !== level) {
      level = newLevel;
      spawnInterval = Math.max(25, 70 - level * 4);
      beep(880, 0.2, 'square');
    }

    // Blocks
    for (let i = blocks.length - 1; i >= 0; i--) {
      const b = blocks[i];
      b.y += b.vy;
      b.rot += b.vr;
      // Collision with paddle
      if (b.y + b.h >= paddleY && b.y < paddleY + paddleH &&
          b.x + b.w > paddleX - paddleW/2 && b.x < paddleX + paddleW/2) {
        if (b.type === 'bad') {
          lives--;
          beep(120, 0.3, 'sawtooth', 0.2);
          addParticles(b.x + b.w/2, b.y + b.h/2, '#ff5277', 25);
          if (lives <= 0) gameOver();
        } else if (b.type === 'bonus') {
          score += 25;
          beep(1200, 0.15, 'triangle');
          addParticles(b.x + b.w/2, b.y + b.h/2, '#b388ff', 30);
        } else {
          score += 10;
          beep(700, 0.1, 'sine');
          addParticles(b.x + b.w/2, b.y + b.h/2, '#4fc3ff', 15);
        }
        blocks.splice(i, 1);
        continue;
      }
      if (b.y > H) {
        if (b.type !== 'bad') { /* missed good - no penalty */ }
        blocks.splice(i, 1);
      }
    }

    // Particles
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx; p.y += p.vy;
      p.vy += 0.2; p.life--;
      if (p.life <= 0) particles.splice(i, 1);
    }

    scoreEl.textContent = score;
    livesEl.textContent = lives;
    levelEl.textContent = level;
  }

  function drawBlock(b) {
    ctx.save();
    ctx.translate(b.x + b.w/2, b.y + b.h/2);
    ctx.rotate(b.rot);
    let color, glow;
    if (b.type === 'good') { color = '#4fc3ff'; glow = '#4fc3ff'; }
    else if (b.type === 'bonus') { color = '#b388ff'; glow = '#b388ff'; }
    else { color = '#ff5277'; glow = '#ff5277'; }
    ctx.shadowColor = glow; ctx.shadowBlur = 20;
    ctx.fillStyle = color;
    ctx.fillRect(-b.w/2, -b.h/2, b.w, b.h);
    ctx.shadowBlur = 0;
    ctx.fillStyle = 'rgba(255,255,255,.3)';
    ctx.fillRect(-b.w/2 + 4, -b.h/2 + 4, b.w - 8, 6);
    if (b.type === 'bad') {
      ctx.strokeStyle = '#fff'; ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(-10, -10); ctx.lineTo(10, 10);
      ctx.moveTo(10, -10); ctx.lineTo(-10, 10);
      ctx.stroke();
    } else if (b.type === 'bonus') {
      ctx.fillStyle = '#fff'; ctx.font = 'bold 24px Arial';
      ctx.textAlign='center'; ctx.textBaseline='middle';
      ctx.fillText('★', 0, 0);
    }
    ctx.restore();
  }

  function render() {
    // Background
    ctx.fillStyle = '#050714';
    ctx.fillRect(0, 0, W, H);

    // Grid lines for TV vibe
    ctx.strokeStyle = 'rgba(79,195,255,.06)';
    ctx.lineWidth = 1;
    for (let i = 0; i < W; i += 40) {
      ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, H); ctx.stroke();
    }
    for (let i = 0; i < H; i += 40) {
      ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(W, i); ctx.stroke();
    }

    // Blocks
    blocks.forEach(drawBlock);

    // Particles
    particles.forEach(p => {
      const a = p.life / p.max;
      ctx.globalAlpha = a;
      ctx.fillStyle = p.color;
      ctx.fillRect(p.x - 3, p.y - 3, 6, 6);
    });
    ctx.globalAlpha = 1;

    // Paddle
    ctx.save();
    ctx.shadowColor = '#4fc3ff'; ctx.shadowBlur = 25;
    const grad = ctx.createLinearGradient(paddleX - paddleW/2, 0, paddleX + paddleW/2, 0);
    grad.addColorStop(0, '#4fc3ff');
    grad.addColorStop(1, '#b388ff');
    ctx.fillStyle = grad;
    ctx.fillRect(paddleX - paddleW/2, paddleY, paddleW, paddleH);
    ctx.restore();

    // Floor line
    ctx.strokeStyle = 'rgba(79,195,255,.4)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, paddleY + paddleH + 5); ctx.lineTo(W, paddleY + paddleH + 5);
    ctx.stroke();
  }

  function loop() {
    detectMotion();
    update();
    render();
    requestAnimationFrame(loop);
  }

  function startGame() {
    score = 0; lives = 3; level = 1;
    blocks = []; particles = [];
    spawnTimer = 0; spawnInterval = 70;
    state = 'playing';
    overlay.style.display = 'none';
  }

  function gameOver() {
    state = 'gameover';
    beep(200, 0.5, 'sawtooth', 0.2);
    setTimeout(() => beep(150, 0.6, 'sawtooth', 0.2), 200);
    overlay.style.display = 'flex';
    overlay.querySelector('h1').textContent = 'GAME OVER';
    overlay.querySelector('p').innerHTML = `Final Score: <b style="color:#4fc3ff">${score}</b> &nbsp; Level: <b style="color:#b388ff">${level}</b><br><br>Wave your hand to play again!`;
    startBtn.textContent = '▶ Play Again';
  }

  startBtn.addEventListener('click', async () => {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    audioCtx.resume();
    await initCamera();
    startGame();
  });

  // Keyboard fallback (Google TV remote D-pad)
  window.addEventListener('keydown', e => {
    if (state !== 'playing') {
      if (e.key === 'Enter' || e.key === ' ') startBtn.click();
      return;
    }
    if (e.key === 'ArrowLeft') paddleTargetX -= 50;
    if (e.key === 'ArrowRight') paddleTargetX += 50;
  });

  // Mouse fallback
  canvas.addEventListener('mousemove', e => {
    const r = canvas.getBoundingClientRect();
    paddleTargetX = (e.clientX - r.left) * (W / r.width);
  });

  // Resize handling
  function resize() {
    const ratio = W / H;
    const maxW = window.innerWidth;
    const maxH = window.innerHeight;
    let cw = maxW, ch = maxW / ratio;
    if (ch > maxH) { ch = maxH; cw = ch * ratio; }
    canvas.style.width = cw + 'px';
    canvas.style.height = ch + 'px';
  }
  window.addEventListener('resize', resize);
  resize();

  loop();
})();
</script>
</body>
</html>
