  scene.add(sun);
  scene.add(new THREE.HemisphereLight(0xbfe2ff,0xbfa07a,0.55));
  scene.add(new THREE.AmbientLight(0xffffff,0.25));

  buildGround();
  buildRoad();
  buildFlyover();
  buildMetroBridge();
  buildEnvironment();
  buildCar();
  spawnTraffic();
  spawnCows();

  clock=new THREE.Clock();
