function addVehicle(){
  const types=['bus','auto','truck','bike','car'];
  const type=types[Math.floor(Math.random()*types.length)];
  const g=new THREE.Group();
  let speedV=0.2+Math.random()*0.4;
  let oncoming=Math.random()<0.5;
  // left-side driving: our lane is left (negative x). oncoming = right side positive x going opposite
  const laneX = oncoming ? (LANE) : (-LANE - (Math.random()<0.3?4:0));
  let mat,body;
  if(type==='bus'){
    body=new THREE.Mesh(new THREE.BoxGeometry(2.2,2.8,8),new THREE.MeshLambertMaterial({color:0xff5722}));
    body.position.y=1.6; g.add(body);
    const w=new THREE.Mesh(new THREE.BoxGeometry(2.1,1.2,7.5),new THREE.MeshLambertMaterial({color:0x223}));
    w.position.y=2.4; g.add(w);
  } else if(type==='auto'){
    body=new THREE.Mesh(new THREE.BoxGeometry(1.4,1.4,2.4),new THREE.MeshLambertMaterial({color:0xffeb3b}));
    body.position.y=0.9; g.add(body);
    const top=new THREE.Mesh(new THREE.BoxGeometry(1.3,0.8,1.8),new THREE.MeshLambertMaterial({color:0x111}));
    top.position.set(0,1.8,0); g.add(top);
    speedV*=0.7;
  } else if(type==='truck'){
    body=new THREE.Mesh(new THREE.BoxGeometry(2.4,2.4,6),new THREE.MeshLambertMaterial({color:0x1565c0}));
    body.position.y=1.5; g.add(body);
    const cab=new THREE.Mesh(new THREE.BoxGeometry(2.4,1.8,2),new THREE.MeshLambertMaterial({color:0xffc107}));
    cab.position.set(0,1.6,2); g.add(cab);
  } else if(type==='bike'){
    body=new THREE.Mesh(new THREE.BoxGeometry(0.5,0.6,1.8),new THREE.MeshLambertMaterial({color:0x333}));
    body.position.y=0.6; g.add(body);
    const rider=new THREE.Mesh(new THREE.BoxGeometry(0.5,1,0.5),new THREE.MeshLambertMaterial({color:0x4a90e2}));
    rider.position.set(0,1.4,0); g.add(rider);
    speedV*=1.1;
  } else {
    body=new THREE.Mesh(new THREE.BoxGeometry(1.8,0.8,3.5),new THREE.MeshLambertMaterial({color:Math.random()*0xffffff}));
    body.position.y=0.6; g.add(body);
    const top=new THREE.Mesh(new THREE.BoxGeometry(1.6,0.6,1.8),new THREE.MeshLambertMaterial({color:0x222}));
    top.position.set(0,1.2,-0.2); g.add(top);
  }
  g.position.set(laneX,0,Math.random()*2000-1000);
  if(oncoming) g.rotation.y=Math.PI;
  scene.add(g);
  traffic.push({mesh:g,speed:speedV,oncoming,lane:laneX,type});
}

function spawnCows(){
  for(let i=0;i<6;i++){
    const cow=new THREE.Group();
    const body=new THREE.Mesh(new THREE.BoxGeometry(1.2,1,2.2),new THREE.MeshLambertMaterial({color:0xf5e6c8}));
    body.position.y=1.1; cow.add(body);
    const head=new THREE.Mesh(new THREE.BoxGeometry(0.8,0.7,0.8),new THREE.MeshLambertMaterial({color:0xf5e6c8}));
    head.position.set(0,1.3,1.4); cow.add(head);
    for(let dx of [-0.4,0.4])for(let dz of [-0.8,0.8]){
      const leg=new THREE.Mesh(new THREE.BoxGeometry(0.25,1,0.25),new THREE.MeshLambertMaterial({color:0xc8a878}));
      leg.position.set(dx,0.5,dz); cow.add(leg);
    }
    const x = (Math.random()<0.5?-1:1)*(ROAD_W/2 - 1 + Math.random()*2);
    cow.position.set(x,0,Math.random()*1600-800);
    cow.rotation.y=Math.random()*Math.PI*2;
    scene.add(cow);
    cows.push({mesh:cow});
  }
}

function onResize(){
  camera.aspect=innerWidth/innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth,innerHeight);
}

function update(dt){
  if(!running) return;
  // input
  const up=keys['arrowup']||keys['w'];
  const down=keys['arrowdown']||keys['s'];
  const left=keys['arrowleft']||keys['a'];
  const right=keys['arrowright']||keys['d'];

  if(up) speed=Math.min(maxSpeed,speed+accel);
  else if(down) speed=Math.max(-0.5,speed-accel*1.5);
  else speed*=0.99;

  const steerAmt=0.06*Math.min(1,Math.abs(speed)/0.5);
  if(left) car.position.x -= steerAmt;
  if(right) car.position.x += steerAmt;
  car.position.x=Math.max(-ROAD_W/2+1, Math.min(ROAD_W/2-1, car.position.x));

  // tilt
  car.rotation.z = (left?0.05:0) - (right?0.05:0);

  // move world relative to car: car stays near z=0, traffic & decor recycle
  const dz = speed; // car moves forward
  car.position.z += dz;

  // camera follow
  const camTarget=new THREE.Vector3(car.position.x*0.4, 6, car.position.z-12);
  camera.position.lerp(camTarget,0.1);
  camera.lookAt(car.position.x, 1.5, car.position.z+5);

  // traffic update & recycle
  for(const t of traffic){
    t.mesh.position.z += t.oncoming ? -t.speed : t.speed;
    // recycle when too far
    const rel=t.mesh.position.z-car.position.z;
    if(rel<-100) t.mesh.position.z=car.position.z+400+Math.random()*200;
    if(rel>500) t.mesh.position.z=car.position.z-50-Math.random()*100;
    // collision
    if(Math.abs(t.mesh.position.x-car.position.x)<1.8 && Math.abs(rel)<3.5){
      gameOver();
    }
  }
  // cows recycle
  for(const c of cows){
    const rel=c.mesh.position.z-car.position.z;
    if(rel<-100) c.mesh.position.z=car.position.z+300+Math.random()*200;
    if(Math.abs(c.mesh.position.x-car.position.x)<1.6 && Math.abs(rel)<2.5){
      gameOver();
    }
  }

  // score
  distance+=Math.max(0,dz);
  score=Math.floor(distance*2);
  document.getElementById('score').textContent=score;
  document.getElementById('dist').textContent=Math.floor(distance);
  document.getElementById('kmh').textContent=Math.floor(speed*80);

  // bumpy speed breaker effect
  car.position.y = Math.abs(Math.sin(car.position.z*0.5))<0.05 && Math.abs(car.position.z%220)<1.5 ? 0.2 : 0;
}

function gameOver(){
  if(!running) return;
  running=false;
  document.getElementById('finalScore').textContent=score;
  document.getElementById('gameover').style.display='flex';
  // crash sound
  try{
    const ctx=new (window.AudioContext||window.webkitAudioContext)();
    const o=ctx.createOscillator(),g=ctx.createGain();
    o.type='sawtooth';o.frequency.setValueAtTime(200,ctx.currentTime);
    o.frequency.exponentialRampToValueAtTime(40,ctx.currentTime+0.5);
    g.gain.setValueAtTime(0.3,ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.01,ctx.currentTime+0.5);
    o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+0.5);
  }catch(e){}
}

function animate(){
  requestAnimationFrame(animate);
  const dt=clock.getDelta();
  update(dt);
  renderer.render(scene,camera);
}

function startGame(){
  document.getElementById('overlay').style.display='none';
  document.getElementById('gameover').style.display='none';
  speed=0;distance=0;score=0;
  car.position.set(-LANE,0,0);
  running=true;
}

document.getElementById('startBtn').onclick=startGame;
document.getElementById('restartBtn').onclick=()=>{
  // reset traffic positions
  traffic.forEach(t=>t.mesh.position.z=Math.random()*800-400);
  startGame();
};

init();
animate();
</script>
</body>
</html>
