    line.position.set(cx, 0.02, z);
    scene.add(line);
  }
  for(const x of intersectionCoords){
    const len = intersectionCoords[i+1]-intersectionCoords[i] - streetWidth;
    const cz = (intersectionCoords[i]+intersectionCoords[i+1])/2;
    const line = new THREE.Mesh(new THREE.PlaneGeometry(0.2, len), lineMat);
    line.rotation.x = -Math.PI/2;
    line.position.set(x, 0.02, cz);
    scene.add(line);
  }
}

// Waypoint system
const dirs = {
  N:{dx:0,dz:-1}, S:{dx:0,dz:1}, E:{dx:1,dz:0}, W:{dx:-1,dz:0}
};
const dirNames = ['N','S','E','W'];
function rightOf(d){ return {dx:-d.dz, dz:d.dx}; }
function leftOf(d){ return {dx:d.dz, dz:-d.dx}; }
function dirName(d){
  for(const n of dirNames) if(dirs[n].dx===d.dx && dirs[n].dz===d.dz) return n;
  return null;
}
const waypoints = {};
const laneOffset = 1.6;
function addWP(key, x, z){
  waypoints[key] = {pos: new THREE.Vector3(x,0,z), targets:[], key};
}
for(const ix of intersectionCoords){
  for(const iz of intersectionCoords){
    for(const dn of dirNames){
      const d = dirs[dn]; const r = rightOf(d);
      addWP(`${ix}_${iz}_${dn}_in`,
        ix - d.dx*halfStreet + r.dx*laneOffset,
        iz - d.dz*halfStreet + r.dz*laneOffset);
      addWP(`${ix}_${iz}_${dn}_out`,
        ix + d.dx*halfStreet + r.dx*laneOffset,
        iz + d.dz*halfStreet + r.dz*laneOffset);
    }
  }
}
for(const ix of intersectionCoords){
  for(const iz of intersectionCoords){
    for(const dn of dirNames){
      const d = dirs[dn];
      const inWP = waypoints[`${ix}_${iz}_${dn}_in`];
      inWP.targets.push(waypoints[`${ix}_${iz}_${dn}_out`]); // straight
      const rn = dirName(rightOf(d));
      if(rn) inWP.targets.push(waypoints[`${ix}_${iz}_${rn}_out`]); // right
      const ln = dirName(leftOf(d));
      if(ln) inWP.targets.push(waypoints[`${ix}_${iz}_${ln}_out`]); // left
      const nx = ix + d.dx*30;
      const nz = iz + d.dz*30;
      const outWP = waypoints[`${ix}_${iz}_${dn}_out`];
      const nextKey = `${nx}_${nz}_${dn}_in`;
      if(waypoints[nextKey]) outWP.targets.push(waypoints[nextKey]);
    }
  }
}

// Cars
const cars = [];
const usableKeys = Object.keys(waypoints).filter(k => waypoints[k].targets.length > 0);
function spawnCar(){
  const wp = waypoints[usableKeys[Math.floor(Math.random()*usableKeys.length)]];
  const target = wp.targets[Math.floor(Math.random()*wp.targets.length)];
  const g = new THREE.Group();
  const body = new THREE.Mesh(
    new THREE.BoxGeometry(1.6, 0.8, 3),
    new THREE.MeshStandardMaterial({color: new THREE.Color().setHSL(Math.random(),0.7,0.5)})
  );
  body.position.y = 0.5; body.castShadow = true;
  g.add(body);
  const top = new THREE.Mesh(
    new THREE.BoxGeometry(1.4, 0.5, 1.5),
    new THREE.MeshStandardMaterial({color:0x222244})
  );
  top.position.set(0, 1.15, -0.2);
  g.add(top);
  g.position.copy(wp.pos);
  scene.add(g);
  cars.push({mesh:g, current:wp, target, speed: 6+Math.random()*4});
}
for(let i=0;i<18;i++) spawnCar();

// Player cylinder
const player = new THREE.Mesh(
  new THREE.CylinderGeometry(0.6, 0.6, 1.8, 24),
  new THREE.MeshStandardMaterial({color:0xff4488, emissive:0x331122})
);
player.position.set(-45, 0.9, -45);
player.castShadow = true;
scene.add(player);

// Coins
const coins = [];
function spawnCoin(){
  const cx = blockCenters[Math.floor(Math.random()*3)] + (Math.random()-0.5)*14;
  const cz = blockCenters[Math.floor(Math.random()*3)] + (Math.random()-0.5)*14;
  const coin = new THREE.Mesh(
    new THREE.CylinderGeometry(0.4,0.4,0.1,18),
    new THREE.MeshStandardMaterial({color:0xffdd00, emissive:0x886600, metalness:0.8, roughness:0.3})
  );
  coin.rotation.x = Math.PI/2;
  coin.position.set(cx, 1, cz);
  coin.castShadow = true;
  scene.add(coin);
  coins.push(coin);
}
for(let i=0;i<10;i++) spawnCoin();

let score = 0;
const scoreEl = document.getElementById('score');

// Camera
let camYaw = 0, camPitch = 0.5, camDist = 11;
let dragging = false, lastX=0, lastY=0;
renderer.domElement.addEventListener('mousedown', e=>{dragging=true; lastX=e.clientX; lastY=e.clientY;});
addEventListener('mouseup', ()=>dragging=false);
addEventListener('mousemove', e=>{
  if(!dragging) return;
  camYaw -= (e.clientX-lastX)*0.005;
  camPitch -= (e.clientY-lastY)*0.005;
  camPitch = Math.max(0.1, Math.min(1.4, camPitch));
  lastX=e.clientX; lastY=e.clientY;
});
addEventListener('wheel', e=>{
  camDist = Math.max(4, Math.min(25, camDist + e.deltaY*0.01));
});
renderer.domElement.addEventListener('touchstart', e=>{
  if(e.touches.length===1){ dragging=true; lastX=e.touches[0].clientX; lastY=e.touches[0].clientY; }
}, {passive:true});
addEventListener('touchend', ()=>dragging=false);
addEventListener('touchmove', e=>{
  if(!dragging||e.touches.length!==1) return;
  camYaw -= (e.touches[0].clientX-lastX)*0.005;
  camPitch -= (e.touches[0].clientY-lastY)*0.005;
  camPitch = Math.max(0.1, Math.min(1.4, camPitch));
  lastX=e.touches[0].clientX; lastY=e.touches[0].clientY;
}, {passive:true});

const keys = {};
addEventListener('keydown', e=>keys[e.key.toLowerCase()]=true);
addEventListener('keyup', e=>keys[e.key.toLowerCase()]=false);

let audioCtx;
function beep(freq, dur, type='sine'){
  try{
    if(!audioCtx) audioCtx = new (window.AudioContext||window.webkitAudioContext)();
    const o = audioCtx.createOscillator(); const g = audioCtx.createGain();
    o.type=type; o.frequency.value = freq;
    o.connect(g); g.connect(audioCtx.destination);
    g.gain.setValueAtTime(0.2, audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime+dur);
    o.start(); o.stop(audioCtx.currentTime+dur);
  }catch(e){}
}

const clock = new THREE.Clock();
function animate(){
  requestAnimationFrame(animate);
  const dt = Math.min(0.05, clock.getDelta());

  // Camera-relative movement
  const forward = new THREE.Vector3(-Math.sin(camYaw), 0, -Math.cos(camYaw));
  const rightV = new THREE.Vector3(forward.z, 0, -forward.x);
  const move = new THREE.Vector3();
  if(keys['w']||keys['arrowup']) move.add(forward);
  if(keys['s']||keys['arrowdown']) move.sub(forward);
  if(keys['d']||keys['arrowright']) move.add(rightV);
  if(keys['a']||keys['arrowleft']) move.sub(rightV);
  if(move.lengthSq()>0){
    move.normalize().multiplyScalar(8*dt);
    player.position.add(move);
    player.rotation.y = Math.atan2(move.x, move.z);
  }
  player.position.x = Math.max(-52, Math.min(52, player.position.x));
  player.position.z = Math.max(-52, Math.min(52, player.position.z));

  // Camera follow
  const camOffset = new THREE.Vector3(
    Math.sin(camYaw)*Math.cos(camPitch)*camDist,
    Math.sin(camPitch)*camDist,
    Math.cos(camYaw)*Math.cos(camPitch)*camDist
  );
  camera.position.copy(player.position).add(camOffset);
  camera.lookAt(player.position.x, player.position.y+1, player.position.z);

  // Cars
  for(const car of cars){
    const toTarget = new THREE.Vector3().subVectors(car.target.pos, car.mesh.position);
    toTarget.y = 0;
    const dist = toTarget.length();
    if(dist < 0.6){
      car.current = car.target;
      const ts = car.current.targets;
      if(ts.length===0){
        car.current = waypoints[usableKeys[Math.floor(Math.random()*usableKeys.length)]];
        car.mesh.position.copy(car.current.pos);
      }
      car.target = car.current.targets[Math.floor(Math.random()*car.current.targets.length)];
    } else {
      toTarget.normalize();
      car.mesh.position.addScaledVector(toTarget, car.speed*dt);
      car.mesh.rotation.y = Math.atan2(toTarget.x, toTarget.z);
    }
    // Collision
    const dp = car.mesh.position.distanceTo(player.position);
    if(dp < 1.6){
      const push = new THREE.Vector3().subVectors(player.position, car.mesh.position).setY(0).normalize().multiplyScalar(2.5);
      player.position.add(push);
      if(score>0){ score = Math.max(0, score-1); scoreEl.textContent=score; beep(140,0.2,'sawtooth'); }
    }
  }

  // Coins
  for(let i=coins.length-1;i>=0;i--){
    const c = coins[i];
    c.rotation.y += dt*3;
    c.position.y = 1 + Math.sin(performance.now()*0.003+i)*0.15;
    if(c.position.distanceTo(player.position) < 1.3){
      scene.remove(c); coins.splice(i,1);
      score++; scoreEl.textContent = score;
      beep(880, 0.1); setTimeout(()=>beep(1320,0.12), 70);
      setTimeout(spawnCoin, 800);
    }
  }

  renderer.render(scene, camera);
}
animate();
</script>
</body>
