      { svc: 'SSH 8.2p1', os: 'Ubuntu 22.04', vuln: false },
      { svc: 'Apache 2.4.49', os: 'CentOS 7', vuln: true, cve: 'CVE-2021-41773 (Path Traversal)' },
      { svc: 'IIS 10', os: 'Win Server 2019', vuln: false },
      { svc: 'OpenSSH 9.1', os: 'Debian 12', vuln: false },
      { svc: 'vsftpd 2.3.4', os: 'Legacy Linux', vuln: true, cve: 'CVE-2011-2523 (Backdoor)' },
      { svc: 'MySQL 8.0', os: 'Ubuntu 20.04', vuln: false },
    ];
    const hosts = hostTypes.sort(() => Math.random()-0.5).map((h, i) => ({
      ...h, ip: `10.0.0.${10 + Math.floor(Math.random()*240)}`
    }));
    // ensure exactly one is the "target" - pick first vuln
    const targetIdx = hosts.findIndex(h => h.vuln);
    hosts.forEach((h, i) => h.isTarget = (i === targetIdx));

    const grid = $('targets'); grid.innerHTML = '';
    let scanned = 0;
    hosts.forEach((h, idx) => {
      const div = document.createElement('div');
      div.className = 'target';
      div.innerHTML = `<div class="ok">${h.ip}</div><div class="dim">[unknown]</div>`;
      div.onclick = () => {
        if (div.classList.contains('scanned')) return this.selectTarget(h, hosts);
        div.classList.add('scanned');
        beep(500+Math.random()*200, 0.06, 'square', 0.04);
        div.innerHTML = `<div class="ok">${h.ip}</div>
          <div>${h.svc}</div><div class="dim">${h.os}</div>
          ${h.vuln ? '<div class="warn">⚠ VULN: '+h.cve+'</div>' : '<div class="dim">no known CVE</div>'}`;
        log(`> scan ${h.ip}: ${h.svc} / ${h.os} ${h.vuln ? '<span class="warn">[VULNERABLE: '+h.cve+']</span>' : ''}`);
        scanned++;
        this.addScore(40);
        if (scanned === hosts.length) {
          log('> Recon complete. Click the VULNERABLE host to exploit.', 'ok');
        }
      };
      grid.appendChild(div);
      h._el = div;
    });
  },
  selectTarget(h, hosts) {
    if (!hosts.every(x => x._el.classList.contains('scanned'))) {
      const t = $('reconTerm');
      const d = document.createElement('div'); d.className='line warn';
      d.textContent = '> Hold up. Recon all hosts first — never engage blind.';
      t.appendChild(d); t.scrollTop = t.scrollHeight; return;
    }
    if (h.vuln) {
      this.addScore(200);
      h._el.classList.add('exploited');
      this.startExploit(h);
    } else {
      beep(120,0.2,'sawtooth',0.08);
      const t = $('reconTerm');
      const d = document.createElement('div'); d.className='line err';
      d.textContent = `> ${h.ip} hardened. Alarms triggered. -50 pts.`;
      t.appendChild(d); t.scrollTop = t.scrollHeight;
      this.score = Math.max(0, this.score - 50); this.updateScore();
    }
  },

  // ============== EXPLOIT ==============
  startExploit(target) {
    $('phase').textContent = 'EXPLOIT';
    show('exploit');
    const payloads = [
      `curl http://${target.ip}/cgi-bin/.%2e/.%2e/etc/passwd`,
      `ssh root@${target.ip} -p 6200 'cat /root/flag'`,
      `python3 exploit.py --target ${target.ip} --payload reverse_shell`,
      `msfconsole -q -x "use exploit/multi/http; set RHOSTS ${target.ip}; run"`,
    ];
    const text = payloads[Math.floor(Math.random()*payloads.length)];
    let pos = 0, ids = 0;
    const render = () => {
      $('typing').innerHTML =
        `<span class="done">${text.slice(0,pos)}</span>` +
        (pos < text.length ? `<span class="cur">${text[pos]}</span>` : '') +
        text.slice(pos+1);
    };
    render();
    const input = $('typeInput');
    input.value = ''; input.focus();
    const idsTimer = setInterval(() => {
      ids += 1.2;
      $('ipsBar').style.width = Math.max(0, 100 - ids) + '%';
      $('ipsPct').textContent = Math.floor(ids);
      if (ids >= 100) { clearInterval(idsTimer); input.onkeydown = null; this.endGame(false); }
    }, 100);
    input.onkeydown = (e) => {
      if (e.key === 'Backspace') return;
      if (e.key.length !== 1) return;
      if (e.key === text[pos]) {
        pos++; render();
        beep(800+pos*5, 0.02, 'square', 0.03);
        if (pos >= text.length) {
          clearInterval(idsTimer);
          input.onkeydown = null;
          this.addScore(Math.floor((100-ids)*10));
          setTimeout(() => this.endGame(true), 400);
        }
      } else {
        ids += 3; beep(180,0.05,'sawtooth',0.05);
        e.preventDefault();
      }
    };
  },

  endGame(success) {
    clearInterval(this.timer);
    show('end');
    $('finalScore').textContent = this.score;
    $('finalTime').textContent = Math.floor((Date.now()-this.startTime)/1000);
    if (success) {
      $('endTitle').textContent = '# ROOT ACCESS';
      $('endTitle').style.color = '#0f0';
      $('endMsg').innerHTML = 'Mindset → Recon → Exploit.<br>You thought like a hacker: <span class="ok">observed patterns</span>, <span class="ok">mapped the surface</span>, then <span class="ok">struck precisely</span>.<br><span class="dim">Now use these powers ethically.</span>';
      beep(660,0.15,'sine',0.06); setTimeout(()=>beep(880,0.2,'sine',0.06), 150);
    } else {
      $('endTitle').textContent = '# DETECTED';
      $('endTitle').style.color = '#f33';
      $('endMsg').innerHTML = 'The IDS caught you. Real hackers know: <span class="warn">stealth and patience</span> matter as much as skill.';
      beep(180,0.3,'sawtooth',0.07);
    }
  }
};
</script>
</body>
