</head>
<body>
<div id="wrap">
  <canvas id="game" width="800" height="500"></canvas>
  <div id="hud">Lokasi: <span id="loc">-</span> | Misi: <span id="mission">-</span> | Pelanggan: <span id="served">0</span>/3</div>
  <div id="ctrls">WASD/Arrow: Gerak | E: Pindah | F: Senter | G: Ambil | H: Pangkas | R: Next Story</div>
  <div id="msg">Selamat datang Dimas!</div>
  <div id="story">
    <h2 id="sTitle"></h2>
    <p id="sText"></p>
    <small>Tekan R untuk lanjut...</small>
  </div>
  <div id="flash"></div>
</div>

<script>
const cvs = document.getElementById('game');
const ctx = cvs.getContext('2d');
const W = cvs.width, H = cvs.height;

const keys = {};
addEventListener('keydown', e => { keys[e.key.toLowerCase()] = true; handleKey(e.key.toLowerCase()); });
addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });

// Audio
const AC = new (window.AudioContext||window.webkitAudioContext)();
function beep(f=440, d=0.1, t='sine', v=0.1) {
  const o = AC.createOscillator(), g = AC.createGain();
  o.type=t; o.frequency.value=f; g.gain.value=v;
  o.connect(g); g.connect(AC.destination);
  o.start(); g.gain.exponentialRampToValueAtTime(0.001, AC.currentTime+d);
  o.stop(AC.currentTime+d);
}

// Player
const player = { x: 400, y: 250, w: 20, h: 28, speed: 2.5, flashlight:false, holding:null };

// Rooms: each has bounds, doors (linked rooms), objects
const rooms = {
  parkir: { name:'Area Parkir', bg:'#3a4a3a', doors:[{x:380,y:200,w:40,h:20,to:'lobbyBarber'}], objs:[] },
  lobbyBarber: { name:'Lobby Barbershop', bg:'#4a4030', doors:[
    {x:30,y:220,w:20,h:40,to:'parkir'},
    {x:750,y:220,w:20,h:40,to:'ruangBarber'},
    {x:380,y:30,w:40,h:20,to:'wcBarber'},
    {x:380,y:450,w:40,h:20,to:'rumahKamar'},
  ], objs:[{type:'customer',x:200,y:300,served:false},{type:'customer',x:400,y:350,served:false},{type:'customer',x:600,y:300,served:false}] },
  ruangBarber: { name:'Ruangan Barbershop', bg:'#553355', doors:[{x:30,y:220,w:20,h:40,to:'lobbyBarber'}], objs:[{type:'chair',x:400,y:250}] },
  wcBarber: { name:'WC Barbershop', bg:'#2a3a4a', doors:[{x:380,y:450,w:40,h:20,to:'lobbyBarber'}], objs:[] },
  rumahKamar: { name:'Kamar Rumah', bg:'#403050', doors:[
    {x:380,y:30,w:40,h:20,to:'lobbyBarber'},
    {x:750,y:220,w:20,h:40,to:'dapur'},
    {x:30,y:220,w:20,h:40,to:'wcRumah'},
  ], objs:[{type:'bed',x:200,y:200}] },
  dapur: { name:'Dapur', bg:'#504030', doors:[{x:30,y:220,w:20,h:40,to:'rumahKamar'}], objs:[] },
  wcRumah: { name:'WC Rumah', bg:'#2a3a4a', doors:[{x:750,y:220,w:20,h:40,to:'rumahKamar'}], objs:[] },
  lobbyRuko: { name:'Lobby Ruko Sebelah', bg:'#2a2a2a', doors:[
    {x:30,y:220,w:20,h:40,to:'lobbyBarber'},
    {x:750,y:220,w:20,h:40,to:'wcRuko'},
  ], objs:[] },
  wcRuko: { name:'WC Ruko Sebelah', bg:'#1a1a2a', doors:[{x:30,y:220,w:20,h:40,to:'lobbyRuko'}], objs:[{type:'ghost',x:400,y:250}] },
};

let current = 'parkir';
let served = 0;
let phase = 0; // 0:intro 1:layani 2:surat 3:susur 4:terror 5:tertangkap 6:berita
let storyIdx = 0;
let surat = false;
const stories = [
  {t:'Hari Pertama', x:'Namaku Dimas. Aku baru saja membuka barbershop kecil di pinggir kota. Hari ini hari pertama buka. Semoga banyak pelanggan datang!'},
  {t:'Misi', x:'Layani 3 pelanggan di Lobby Barbershop. Dekati mereka lalu tekan H untuk memangkas rambut.'},
  {t:'Surat Misterius', x:'Sebuah surat terselip di pintu ruko. Tulisannya... "Datanglah ke ruko sebelah. Ada yang menunggumu."'},
  {t:'Penyelusuran', x:'Aku harus memeriksa ruko sebelah. Tekan F untuk menyalakan senter. Suasananya... dingin sekali.'},
  {t:'Alam Lain', x:'Tiba-tiba dunia berubah merah! Semua jadi aneh! Ada sesuatu mengejarku! LARI!!!'},
  {t:'Tertangkap', x:'Tangan dingin itu... meraih leherku... gelap...'},
  {t:'BERITA TERKINI', x:'"Seorang tukang pangkas rambut bernama Dimas dilaporkan HILANG sejak 3 hari lalu. Polisi masih menyelidiki. Saksi terakhir melihatnya masuk ke ruko kosong sebelah barbershop miliknya..."'},
];

const msg = document.getElementById('msg');
const story = document.getElementById('story');
function showStory(i) {
  if (i>=stories.length) { story.style.display='none'; if(phase===6){location.reload();} return; }
  storyIdx = i;
  document.getElementById('sTitle').textContent = stories[i].t;
  document.getElementById('sText').textContent = stories[i].x;
  story.style.display='flex';
}
function setMsg(s){ msg.textContent = s; }

showStory(0);
phase = 0;

let monster = null;

function handleKey(k) {
  if (k==='r') {
    if (story.style.display==='flex') {
      const next = storyIdx+1;
      if (next>=stories.length) { story.style.display='none'; if(phase===6) setTimeout(()=>location.reload(),500); }
      else showStory(next);
      if (phase===0 && storyIdx===1) phase=1;
    }
  }
  if (story.style.display==='flex') return;
  if (k==='e') tryDoor();
  if (k==='f') { player.flashlight = !player.flashlight; beep(300,0.05); }
  if (k==='g') tryGrab();
  if (k==='h') tryCut();
}

function tryDoor() {
  const r = rooms[current];
  for (const d of r.doors) {
    if (player.x+player.w>d.x && player.x<d.x+d.w && player.y+player.h>d.y && player.y<d.y+d.h) {
      // unlock ruko if surat taken
      if (d.to==='lobbyRuko' && !surat) { setMsg('Pintu terkunci...'); return; }
      current = d.to;
      // place player at opposite door
      const nr = rooms[current];
      const back = nr.doors.find(x=>x.to===Object.keys(rooms).find(k=>rooms[k]===r));
      if (back) { player.x = back.x+back.w/2-10; player.y = back.y+back.h/2-14; }
      beep(500,0.08);
      checkPhase();
      return;
    }
  }
  // special: from lobbyBarber to lobbyRuko door appears after surat
  if (current==='lobbyBarber' && surat && phase===3) {
    // already handled
  }
}

function checkPhase() {
  if (phase===2 && current==='lobbyBarber') {
    // drop surat at door
  }
  if (phase===3 && current==='wcRuko') {
    // trigger horror
    phase = 4;
    document.body.classList.add('red');
    const flash = document.getElementById('flash');
    flash.style.opacity='0.5';
    setTimeout(()=>flash.style.opacity='0', 400);
    beep(80,0.5,'sawtooth',0.2);
    monster = { x: 100, y: 100, speed: 1.4 };
    setMsg('LARI!!! Ada yang mengejarmu!');
    showStory(4);
  }
}

function tryGrab() {
  if (phase===2 && current==='lobbyBarber') {
    // surat near door to ruko? Let's add ruko door now
    const dist = Math.hypot(player.x-100, player.y-100);
    if (dist<60) {
      surat = true;
      // add door to ruko
      rooms.lobbyBarber.doors.push({x:30,y:100,w:20,h:40,to:'lobbyRuko'});
      setMsg('Kamu mengambil surat. Pintu ruko sebelah terbuka...');
      beep(700,0.1);
      phase = 3;
      showStory(3);
    }
  }
}

function tryCut() {
  if (phase!==1) return;
  const r = rooms[current];
  for (const o of r.objs) {
    if (o.type==='customer' && !o.served) {
      if (Math.hypot(player.x-o.x, player.y-o.y) < 50) {
        o.served = true;
        served++;
        beep(800,0.1); setTimeout(()=>beep(1000,0.1),100);
        setMsg('Pelanggan dilayani! ('+served+'/3)');
        if (served>=3) {
          phase = 2;
          setMsg('Semua pelanggan terlayani! Ada surat di lobby...');
          // spawn surat indicator already implicit
          showStory(2);
        }
        return;
      }
    }
  }
}

function update() {
  if (story.style.display==='flex') return;
  let dx=0, dy=0;
  if (keys['w']||keys['arrowup']) dy=-1;
  if (keys['s']||keys['arrowdown']) dy=1;
  if (keys['a']||keys['arrowleft']) dx=-1;
  if (keys['d']||keys['arrowright']) dx=1;
  const sp = player.speed * (phase===4?1.5:1);
  player.x = Math.max(10, Math.min(W-player.w-10, player.x+dx*sp));
  player.y = Math.max(10, Math.min(H-player.h-10, player.y+dy*sp));

  if (monster) {
    const ang = Math.atan2(player.y-monster.y, player.x-monster.x);
    monster.x += Math.cos(ang)*monster.speed;
    monster.y += Math.sin(ang)*monster.speed;
    if (Math.hypot(player.x-monster.x, player.y-monster.y) < 24) {
      phase=5;
      monster=null;
      document.getElementById('flash').style.opacity='1';
      beep(50,1,'sawtooth',0.3);
      setTimeout(()=>{ showStory(5); document.body.classList.remove('red'); document.getElementById('flash').style.opacity='0'; phase=6; setTimeout(()=>showStory(6),100); }, 1000);
    }
  }
}

function drawChar(x,y,color='#f4c87a') {
  // body
  ctx.fillStyle = '#2244aa'; // shirt
  ctx.fillRect(x, y+12, 20, 12);
  ctx.fillStyle = '#333'; // pants
  ctx.fillRect(x+2, y+22, 7, 8);
  ctx.fillRect(x+11, y+22, 7, 8);
  // head
  ctx.fillStyle = color;
  ctx.fillRect(x+4, y, 12, 12);
  // hair
  ctx.fillStyle = '#111';
  ctx.fillRect(x+4, y, 12, 3);
  // eyes
  ctx.fillStyle = '#000';
  ctx.fillRect(x+7, y+5, 2, 2);
  ctx.fillRect(x+11, y+5, 2, 2);
}

function draw() {
  const r = rooms[current];
  ctx.fillStyle = r.bg;
  ctx.fillRect(0,0,W,H);

  // walls
  ctx.fillStyle = '#000';
  ctx.fillRect(0,0,W,10); ctx.fillRect(0,H-10,W,10);
  ctx.fillRect(0,0,10,H); ctx.fillRect(W-10,0,10,H);

  // doors
  for (const d of r.doors) {
    ctx.fillStyle = '#ffce4a';
    ctx.fillRect(d.x,d.y,d.w,d.h);
    ctx.fillStyle='#000'; ctx.font='10px monospace';
    ctx.fillText('E', d.x+d.w/2-3, d.y+d.h/2+3);
  }

  // objects
  for (const o of r.objs) {
    if (o.type==='customer') {
      if (o.served) { ctx.globalAlpha=0.4; }
      drawChar(o.x-10, o.y-14, '#e0a878');
      ctx.globalAlpha=1;
      if (!o.served) { ctx.fillStyle='#fff'; ctx.font='10px monospace'; ctx.fillText('H', o.x-3, o.y-20); }
    } else if (o.type==='chair') {
      ctx.fillStyle='#553'; ctx.fillRect(o.x-15,o.y-15,30,30);
    } else if (o.type==='bed') {
      ctx.fillStyle='#883'; ctx.fillRect(o.x-30,o.y-15,60,30);
    } else if (o.type==='ghost') {
      ctx.fillStyle='rgba(255,255,255,0.3)';
      ctx.beginPath(); ctx.arc(o.x,o.y,20,0,Math.PI*2); ctx.fill();
    }
  }

  // surat
  if (phase===2 && current==='lobbyBarber' && !surat) {
    ctx.fillStyle='#fff'; ctx.fillRect(90,90,20,15);
    ctx.fillStyle='#000'; ctx.font='8px monospace'; ctx.fillText('G',95,101);
  }

  // monster
  if (monster) {
    ctx.fillStyle='#600';
    ctx.beginPath(); ctx.arc(monster.x,monster.y,18,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='#f00';
    ctx.fillRect(monster.x-8,monster.y-5,4,4);
    ctx.fillRect(monster.x+4,monster.y-5,4,4);
  }

  // player
  drawChar(player.x, player.y);

  // flashlight
  if (player.flashlight) {
    const g = ctx.createRadialGradient(player.x+10,player.y+14,10,player.x+10,player.y+14,150);
    g.addColorStop(0,'rgba(255,255,200,0.4)');
    g.addColorStop(1,'rgba(255,255,200,0)');
    ctx.fillStyle=g;
    ctx.fillRect(0,0,W,H);
  }

  // darkness in horror
  if (phase>=3 && (current==='lobbyRuko'||current==='wcRuko'||phase===4)) {
    if (!player.flashlight) {
      ctx.fillStyle='rgba(0,0,0,0.7)';
      ctx.fillRect(0,0,W,H);
    }
  }

  document.getElementById('loc').textContent = r.name;
  document.getElementById('served').textContent = served;
  const missions = ['Baca cerita','Layani 3 pelanggan','Ambil surat di lobby','Selidiki ruko sebelah','LARI!','...','...'];
  document.getElementById('mission').textContent = missions[phase]||'-';
}

function loop() {
  update();
  draw();
  requestAnimationFrame(loop);
}
loop();
</script>
</body>
</html>
