<!DOCTYPE html>
<html lang="ru">
<head>
<meta charset="UTF-8">
<title>REG2 - Battle Royale</title>
<style>
*{margin:0;padding:0;box-sizing:border-box;font-family:'Segoe UI',Arial,sans-serif;user-select:none}
body{background:#000;color:#fff;overflow:hidden}
canvas{display:block}
#app{width:100vw;height:100vh;position:relative}
.screen{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:10}
.hidden{display:none!important}

/* Loading */
#loading{background:radial-gradient(circle,#1a2a3a,#000)}
#loading .logo{font-size:80px;font-weight:900;background:linear-gradient(45deg,#ff6b00,#ffd700);-webkit-background-clip:text;-webkit-text-fill-color:transparent;letter-spacing:8px;animation:pulse 2s infinite}
@keyframes pulse{50%{filter:brightness(1.3)}}
