/* Menu */
#menu{background:linear-gradient(135deg,#0a1929 0%,#1e3a5f 100%)}
#menu::before{content:'';position:absolute;inset:0;background:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="100" height="100"><rect width="100" height="100" fill="none" stroke="%23ffd700" stroke-opacity="0.1"/></svg>');opacity:0.3}
#menu .title{font-size:90px;font-weight:900;background:linear-gradient(45deg,#ff6b00,#ffd700);-webkit-background-clip:text;-webkit-text-fill-color:transparent;letter-spacing:10px;margin-bottom:10px;z-index:2}
.player-info{background:rgba(0,0,0,0.6);padding:15px 30px;border:1px solid #ffd700;border-radius:8px;margin-bottom:30px;z-index:2}
.menu-btn{display:block;width:300px;padding:15px;margin:8px;background:linear-gradient(90deg,rgba(255,107,0,0.3),rgba(255,215,0,0.3));border:2px solid #ff6b00;color:#fff;font-size:20px;letter-spacing:3px;cursor:pointer;transition:all 0.3s;z-index:2}
.menu-btn:hover{background:linear-gradient(90deg,#ff6b00,#ffd700);transform:scale(1.05);box-shadow:0 0 20px #ffd700}

/* Mode select */
.mode-card{display:inline-block;width:280px;margin:15px;padding:25px;background:rgba(0,0,0,0.7);border:2px solid #ff6b00;cursor:pointer;transition:all 0.3s;text-align:center}
.mode-card:hover{transform:translateY(-10px);box-shadow:0 10px 30px rgba(255,107,0,0.6);background:rgba(255,107,0,0.2)}
.mode-card h3{font-size:32px;color:#ffd700;margin-bottom:10px}
.mode-card p{color:#aaa}

/* Game HUD */
#hud{position:absolute;inset:0;pointer-events:none;z-index:5}
#minimap{position:absolute;top:20px;right:20px;width:200px;height:200px;background:rgba(0,0,0,0.7);border:2px solid #ffd700;border-radius:5px}
#bottomBar{position:absolute;bottom:20px;left:20px;background:rgba(0,0,0,0.7);padding:15px;border-left:3px solid #ff6b00;min-width:300px}
.bar{height:18px;background:#222;border-radius:3px;overflow:hidden;margin:5px 0;position:relative}
.bar-fill{height:100%;transition:width 0.3s}
.bar-text{position:absolute;inset:0;text-align:center;font-size:12px;line-height:18px;text-shadow:1px 1px 2px #000}
#slots{position:absolute;bottom:20px;left:50%;transform:translateX(-50%);display:flex;gap:5px}
.slot{width:60px;height:60px;background:rgba(0,0,0,0.7);border:2px solid #555;display:flex;align-items:center;justify-content:center;font-size:11px;text-align:center;padding:2px}
.slot.active{border-color:#ffd700;background:rgba(255,215,0,0.2)}
.slot .num{position:absolute;top:2px;left:4px;font-size:10px;color:#ffd700}
.slot{position:relative}
#topInfo{position:absolute;top:20px;left:20px;background:rgba(0,0,0,0.7);padding:10px 20px;border:1px solid #ffd700}
#crosshair{position:absolute;top:50%;left:50%;width:20px;height:20px;transform:translate(-50%,-50%);pointer-events:none}
#crosshair::before,#crosshair::after{content:'';position:absolute;background:#ffd700}
#crosshair::before{width:2px;height:20px;left:9px}
#crosshair::after{width:20px;height:2px;top:9px}
#dangerOverlay{position:absolute;inset:0;background:radial-gradient(circle,transparent 30%,rgba(255,0,0,0.4));opacity:0;pointer-events:none;transition:opacity 0.5s}
#messages{position:absolute;top:50%;left:50%;transform:translateX(-50%);text-align:center;font-size:24px;color:#ffd700;text-shadow:2px 2px 4px #000;pointer-events:none}

/* End screen */
#endScreen{background:radial-gradient(circle,#1a0000,#000);text-align:center}
#endScreen.win{background:radial-gradient(circle,#1a3a00,#000)}
#endScreen h1{font-size:100px;font-weight:900;letter-spacing:10px;margin-bottom:30px}
#endScreen.win h1{color:#ffd700;text-shadow:0 0 30px #ffd700}
#endScreen.lose h1{color:#ff3333;text-shadow:0 0 30px #ff3333}
.stat-row{display:flex;justify-content:space-between;width:400px;padding:8px 20px;border-bottom:1px solid #444;font-size:18px}
.stat-row span:last-child{color:#ffd700;font-weight:bold}

/* Plane */
#jumpBtn{position:absolute;bottom:50px;left:50%;transform:translateX(-50%);padding:20px 60px;background:linear-gradient(45deg,#ff6b00,#ffd700);border:none;font-size:24px;font-weight:bold;letter-spacing:5px;cursor:pointer;pointer-events:auto;border-radius:5px;animation:pulse 1.5s infinite;color:#000}

.dialog{background:rgba(0,0,0,0.9);padding:30px;border:2px solid #ffd700;border-radius:10px;min-width:400px}
.dialog h2{color:#ffd700;margin-bottom:20px;text-align:center}
.close-x{position:absolute;top:10px;right:15px;cursor:pointer;font-size:20px;color:#ff6b00}
</style>
</head>
<body>
<div id="app">

<!-- LOADING -->
<div id="loading" class="screen">
  <div id="particles"></div>
  <div class="logo">REG2</div>
  <div class="sub">BATTLE ROYALE</div>
  <div id="progressBar"><div id="progressFill"></div></div>
  <div id="progressText">Загрузка... 0%</div>
</div>

<!-- MENU -->
<div id="menu" class="screen hidden">
  <div class="title">REG2</div>
  <div class="player-info">
    <div>Игрок: <span id="playerName" style="color:#ffd700">SOLDIER_01</span></div>
    <div>Уровень: <span id="playerLevel" style="color:#ffd700">1</span> | XP: <span id="playerXP" style="color:#ffd700">0</span></div>
  </div>
  <button class="menu-btn" onclick="showModes()">ИГРАТЬ</button>
  <button class="menu-btn" onclick="showDialog('settings')">НАСТРОЙКИ</button>
  <button class="menu-btn" onclick="showDialog('stats')">СТАТИСТИКА</button>
  <button class="menu-btn" onclick="alert('До свидания!')">ВЫХОД</button>
</div>

<!-- MODES -->
<div id="modes" class="screen hidden">
  <h1 style="font-size:50px;color:#ffd700;margin-bottom:40px;letter-spacing:5px">ВЫБОР РЕЖИМА</h1>
  <div>
    <div class="mode-card" onclick="startGame('solo')"><h3>СОЛО</h3><p>100 игроков</p><p style="margin-top:10px;font-size:14px">Каждый сам за себя</p></div>
    <div class="mode-card" onclick="startGame('duo')"><h3>ДУО</h3><p>50 команд</p><p style="margin-top:10px;font-size:14px">Сражайся с напарником</p></div>
    <div class="mode-card" onclick="startGame('squad')"><h3>ОТРЯД</h3><p>25 отрядов</p><p style="margin-top:10px;font-size:14px">Командная игра 4×25</p></div>
  </div>
  <button class="menu-btn" style="margin-top:30px" onclick="show('menu')">НАЗАД</button>
</div>

<!-- GAME -->
<div id="game" class="screen hidden" style="display:block">
  <canvas id="canvas"></canvas>
  <div id="hud">
    <div id="topInfo">
      <div>Игроков: <span id="playersAlive">100</span> | Зона: <span id="zoneTimer">5:00</span></div>
      <div>Этап: <span id="zoneStage">1</span>/7</div>
    </div>
    <canvas id="minimap" width="200" height="200"></canvas>
    <div id="bottomBar">
      <div>Здоровье</div>
      <div class="bar"><div class="bar-fill" id="hpBar" style="width:100%;background:linear-gradient(90deg,#ff3333,#ff6666)"></div><div class="bar-text" id="hpText">100/100</div></div>
      <div>Броня</div>
      <div class="bar"><div class="bar-fill" id="armorBar" style="width:0%;background:linear-gradient(90deg,#3399ff,#66ccff)"></div><div class="bar-text" id="armorText">0/100</div></div>
      <div style="margin-top:10px">Оружие: <span id="curWeapon" style="color:#ffd700">Кулаки</span></div>
      <div>Патроны: <span id="curAmmo" style="color:#ffd700">∞</span></div>
    </div>
    <div id="slots">
      <div class="slot active" data-slot="0"><span class="num">1</span><div>Кулаки</div></div>
      <div class="slot" data-slot="1"><span class="num">2</span><div>-</div></div>
      <div class="slot" data-slot="2"><span class="num">3</span><div>-</div></div>
      <div class="slot" data-slot="3"><span class="num">4</span><div>Аптечка</div></div>
      <div class="slot" data-slot="4"><span class="num">5</span><div>Граната</div></div>
    </div>
    <div id="crosshair"></div>
    <div id="dangerOverlay"></div>
    <div id="messages"></div>
    <button id="jumpBtn" class="hidden">ПРЫГНУТЬ</button>
  </div>
</div>

<!-- END -->
<div id="endScreen" class="screen hidden">
  <h1 id="endTitle">ПОБЕДА!</h1>
  <div id="endStats"></div>
  <button class="menu-btn" style="margin-top:30px" onclick="show('menu')">В МЕНЮ</button>
</div>

<!-- DIALOG -->
<div id="dialogBox" class="screen hidden" style="background:rgba(0,0,0,0.8)">
  <div class="dialog">
    <span class="close-x" onclick="document.getElementById('dialogBox').classList.add('hidden')">✕</span>
    <h2 id="dialogTitle">Диалог</h2>
    <div id="dialogContent"></div>
  </div>
</div>

</div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
<script>
// ===== State =====
const state = {
  mode:'solo', screen:'loading', gameRunning:false,
  player:{hp:100,armor:0,x:500,y:400,z:500,vx:0,vy:0,vz:0,yaw:0,pitch:0,inPlane:true,parachute:false,onGround:false,slot:0,kills:0,damage:0,items:0,distance:0,startTime:0,longestKill:0},
  enemies:[], buildings:[], trees:[], loot:[], bullets:[],
  zone:{stage:0,r:500,cx:500,cz:500,nextR:400,ncx:500,ncz:500,timer:300},
  keys:{}, weapons:{}, slots:[],
  stats: JSON.parse(localStorage.getItem('reg2_stats')||'{"games":0,"wins":0,"kills":0,"level":1,"xp":0}')
};

// Weapons
const WEAPONS = {
  fists:{name:'Кулаки',dmg:8,ammo:Infinity,rate:0.5,range:3,spread:0,auto:false},
  pistol:{name:'Пистолет',dmg:25,ammo:12,maxAmmo:12,rate:0.3,range:80,spread:0.02,auto:false},
  smg:{name:'ПП',dmg:18,ammo:30,maxAmmo:30,rate:0.08,range:100,spread:0.04,auto:true},
  rifle:{name:'Штурмовка',dmg:30,ammo:30,maxAmmo:30,rate:0.1,range:200,spread:0.03,auto:true},
  sniper:{name:'Снайперка',dmg:90,ammo:5,maxAmmo:5,rate:1.2,range:500,spread:0.005,auto:false},
  shotgun:{name:'Дробовик',dmg:60,ammo:6,maxAmmo:6,rate:0.8,range:30,spread:0.15,auto:false},
};

// ===== Loading =====
function initParticles(){
  const p = document.getElementById('particles');
  for(let i=0;i<50;i++){
    const d=document.createElement('div');
    d.className='particle';
    d.style.left=Math.random()*100+'%';
    d.style.animationDelay=Math.random()*4+'s';
    d.style.animationDuration=(3+Math.random()*3)+'s';
    p.appendChild(d);
  }
}
initParticles();

let prog=0;
const loadInt=setInterval(()=>{
  prog+=2+Math.random()*3;
  if(prog>=100){prog=100;clearInterval(loadInt);setTimeout(()=>show('menu'),400)}
  document.getElementById('progressFill').style.width=prog+'%';
  document.getElementById('progressText').textContent='Загрузка... '+Math.floor(prog)+'%';
},80);

// ===== Screens =====
function show(name){
  ['loading','menu','modes','game','endScreen'].forEach(s=>{
    document.getElementById(s).classList.toggle('hidden',s!==name);
  });
  state.screen=name;
  if(name==='menu'){updateMenuStats();}
}
function showModes(){show('modes')}
function updateMenuStats(){
  document.getElementById('playerLevel').textContent=state.stats.level;
  document.getElementById('playerXP').textContent=state.stats.xp;
}
function showDialog(type){
  const t=document.getElementById('dialogTitle');
  const c=document.getElementById('dialogContent');
  if(type==='settings'){
    t.textContent='Настройки';
    c.innerHTML='<div>Громкость: <input type="range" value="50"></div><div>Чувствительность: <input type="range" value="50"></div><div>Графика: <select><option>Высокая</option><option>Средняя</option><option>Низкая</option></select></div>';
  } else {
    t.textContent='Статистика';
    c.innerHTML=`<div class="stat-row"><span>Игр:</span><span>${state.stats.games}</span></div>
      <div class="stat-row"><span>Побед:</span><span>${state.stats.wins}</span></div>
      <div class="stat-row"><span>Убийств:</span><span>${state.stats.kills}</span></div>
      <div class="stat-row"><span>Уровень:</span><span>${state.stats.level}</span></div>
      <div class="stat-row"><span>Опыт:</span><span>${state.stats.xp}</span></div>`;
  }
  document.getElementById('dialogBox').classList.remove('hidden');
}

// ===== Three.js Game =====
let scene,camera,renderer,playerMesh,planeMesh,clock;

function startGame(mode){
  state.mode=mode;
  show('game');
  initGame();
}

function initGame(){
  // Reset
  state.player={hp:100,armor:0,x:500,y:400,z:500,vx:0,vy:0,vz:0,yaw:0,pitch:0,inPlane:true,parachute:false,onGround:false,slot:0,kills:0,damage:0,items:0,distance:0,startTime:Date.now(),longestKill:0};
  state.enemies=[];state.buildings=[];state.trees=[];state.loot=[];state.bullets=[];
  state.zone={stage:0,r:500,cx:500,cz:500,nextR:400,ncx:500,ncz:500,timer:300};
  state.slots=[{type:'fists',ammo:Infinity},null,null,{type:'medkit',count:2},{type:'grenade',count:3}];
  state.player.slot=0;
  updateSlots();

  scene=new THREE.Scene();
  scene.background=new THREE.Color(0x87ceeb);
  scene.fog=new THREE.Fog(0x87ceeb,200,800);

  camera=new THREE.PerspectiveCamera(75,window.innerWidth/window.innerHeight,0.1,2000);

  const canvas=document.getElementById('canvas');
  renderer=new THREE.WebGLRenderer({canvas,antialias:true});
  renderer.setSize(window.innerWidth,window.innerHeight);
  renderer.shadowMap.enabled=true;

  // Lights
  const sun=new THREE.DirectionalLight(0xffffff,1);
  sun.position.set(500,800,500);
  sun.castShadow=true;
  scene.add(sun);
  scene.add(new THREE.AmbientLight(0xffffff,0.5));

  // Ground biomes (simplified with colored zones)
  const groundGeo=new THREE.PlaneGeometry(1000,1000,32,32);
  const pos=groundGeo.attributes.position;
  for(let i=0;i<pos.count;i++){
    const x=pos.getX(i),y=pos.getY(i);
    // mountains in NW area
    let h=0;
    const dx=x+300,dz=y+300;
    if(Math.sqrt(dx*dx+dz*dz)<200) h=Math.max(0,40-Math.sqrt(dx*dx+dz*dz)*0.2)+Math.random()*5;
    pos.setZ(i,h);
  }
  groundGeo.computeVertexNormals();
  const ground=new THREE.Mesh(groundGeo,new THREE.MeshLambertMaterial({color:0x4a7c3a}));
  ground.rotation.x=-Math.PI/2;
  ground.receiveShadow=true;
  scene.add(ground);

  // Water
  const water=new THREE.Mesh(new THREE.PlaneGeometry(300,300),new THREE.MeshLambertMaterial({color:0x2266aa,transparent:true,opacity:0.8}));
  water.rotation.x=-Math.PI/2;
  water.position.set(350,0.5,-350);
  scene.add(water);

  // Buildings (cities)
  const buildingMat=new THREE.MeshLambertMaterial({color:0x888888});
  for(let i=0;i<30;i++){
    const w=8+Math.random()*8,h=8+Math.random()*15,d=8+Math.random()*8;
    const b=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),new THREE.MeshLambertMaterial({color:new THREE.Color().setHSL(0.1,0.1,0.4+Math.random()*0.3)}));
    const x=-400+Math.random()*200, z=-400+Math.random()*200;
    b.position.set(x,h/2,z);
    b.castShadow=true;b.receiveShadow=true;
    scene.add(b);
    state.buildings.push({x,z,w,h,d});
    // spawn loot near building
    if(Math.random()<0.7){
      for(let j=0;j<3+Math.floor(Math.random()*4);j++) spawnLoot(x+(Math.random()-0.5)*20,z+(Math.random()-0.5)*20);
    }
  }
  // Suburbs - smaller buildings
  for(let i=0;i<25;i++){
    const w=5+Math.random()*4,h=4+Math.random()*4,d=5+Math.random()*4;
    const b=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),new THREE.MeshLambertMaterial({color:0xaa7744}));
    const x=100+Math.random()*300, z=-400+Math.random()*200;
    b.position.set(x,h/2,z);
    b.castShadow=true;
    scene.add(b);
    state.buildings.push({x,z,w,h,d});
    if(Math.random()<0.5) spawnLoot(x+5,z);
  }

  // Trees
  for(let i=0;i<400;i++){
    const x=Math.random()*1000-500,z=Math.random()*1000-500;
    // skip city/water areas
    if(x<-200&&z<-200)continue;
    if(x>200&&z<-200&&x<500&&z>-500)continue;
    const trunk=new THREE.Mesh(new THREE.CylinderGeometry(0.4,0.5,3),new THREE.MeshLambertMaterial({color:0x5a3a1a}));
    trunk.position.set(x,1.5,z);
    const leaves=new THREE.Mesh(new THREE.ConeGeometry(2,4),new THREE.MeshLambertMaterial({color:0x2a6a2a}));
    leaves.position.set(x,5,z);
    scene.add(trunk);scene.add(leaves);
    state.trees.push({x,z,r:1.5});
  }

  // Plane
  planeMesh=new THREE.Group();
  const body=new THREE.Mesh(new THREE.BoxGeometry(15,3,4),new THREE.MeshLambertMaterial({color:0xcccccc}));
  const wing=new THREE.Mesh(new THREE.BoxGeometry(4,0.5,18),new THREE.MeshLambertMaterial({color:0xcccccc}));
  planeMesh.add(body);planeMesh.add(wing);
  scene.add(planeMesh);

  // Player mesh (visible after jumping)
  playerMesh=new THREE.Mesh(new THREE.CapsuleGeometry(0.5,1.5),new THREE.MeshLambertMaterial({color:0x3366ff}));
  playerMesh.castShadow=true;
  scene.add(playerMesh);

  // Enemies (AI)
  for(let i=0;i<99;i++){
    const ex=Math.random()*900+50, ez=Math.random()*900+50;
    const em=new THREE.Mesh(new THREE.CapsuleGeometry(0.5,1.5),new THREE.MeshLambertMaterial({color:0xff3333}));
    em.position.set(ex,1.5,ez);
    em.castShadow=true;
    scene.add(em);
    const diff=Math.random();
    const skill=diff<0.3?0.3:diff<0.8?0.6:1.0;
    state.enemies.push({mesh:em,x:ex,y:1.5,z:ez,hp:100,alive:true,target:null,state:'patrol',patrolTime:0,tx:ex,tz:ez,skill,shootCooldown:0,weapon:'rifle'});
  }
  updatePlayersAlive();

  // Zone visual
  const zoneGeo=new THREE.RingGeometry(498,500,64);
  state.zoneMesh=new THREE.Mesh(zoneGeo,new THREE.MeshBasicMaterial({color:0x3399ff,side:THREE.DoubleSide,transparent:true,opacity:0.8}));
  state.zoneMesh.rotation.x=-Math.PI/2;
  state.zoneMesh.position.set(500,1,500);
  scene.add(state.zoneMesh);

  clock=new THREE.Clock();
  state.gameRunning=true;

  // Plane fly intro
  document.getElementById('jumpBtn').classList.remove('hidden');
  document.getElementById('jumpBtn').onclick=jumpFromPlane;

  setupControls();
  showMessage('Самолет летит... Нажмите ПРЫГНУТЬ',2000);
  animate();
}

function spawnLoot(x,z){
  const types=['pistol','smg','rifle','sniper','shotgun','medkit','armor','grenade'];
  const type=types[Math.floor(Math.random()*types.length)];
  const colors={pistol:0xffffff,smg:0x88ff88,rifle:0x3399ff,sniper:0xaa44ff,shotgun:0xffaa00,medkit:0xff4444,armor:0x4488ff,grenade:0x44ff44};
  const m=new THREE.Mesh(new THREE.BoxGeometry(0.6,0.6,0.6),new THREE.MeshLambertMaterial({color:colors[type]||0xffffff,emissive:colors[type]||0xffffff,emissiveIntensity:0.3}));
  m.position.set(x,1,z);
  scene.add(m);
  state.loot.push({mesh:m,x,z,type});
}

function jumpFromPlane(){
  state.player.inPlane=false;
  state.player.vy=0;
  document.getElementById('jumpBtn').classList.add('hidden');
  showMessage('ПРЫЖОК!',1500);
}

function showMessage(msg,dur=2000){
  const m=document.getElementById('messages');
  m.textContent=msg;
  clearTimeout(m._t);
  m._t=setTimeout(()=>m.textContent='',dur);
}

// Controls
function setupControls(){
  document.onkeydown=e=>{
    state.keys[e.code]=true;
    if(e.code.startsWith('Digit')){
      const n=parseInt(e.code.slice(5))-1;
      if(n>=0&&n<5)selectSlot(n);
    }
    if(e.code==='KeyR')reload();
    if(e.code==='KeyF')interact();
  };
  document.onkeyup=e=>state.keys[e.code]=false;

  const canvas=document.getElementById('canvas');
  canvas.onclick=()=>{
    if(state.player.inPlane||!state.gameRunning)return;
    canvas.requestPointerLock();
  };
  document.onmousemove=e=>{
    if(document.pointerLockElement===canvas){
      state.player.yaw-=e.movementX*0.003;
      state.player.pitch-=e.movementY*0.003;
      state.player.pitch=Math.max(-1.5,Math.min(1.5,state.player.pitch));
    }
  };
  canvas.onmousedown=e=>{
    if(e.button===0&&!state.player.inPlane)shoot();
  };
  window.onresize=()=>{
    if(camera){camera.aspect=window.innerWidth/window.innerHeight;camera.updateProjectionMatrix();renderer.setSize(window.innerWidth,window.innerHeight);}
  };
}

function selectSlot(n){
  state.player.slot=n;
  updateSlots();
  const cur=state.slots[n];
  document.getElementById('curWeapon').textContent=cur?(WEAPONS[cur.type]?WEAPONS[cur.type].name:cur.type):'Пусто';
  document.getElementById('curAmmo').textContent=cur&&cur.ammo!==undefined?(cur.ammo===Infinity?'∞':cur.ammo):(cur&&cur.count?cur.count:'-');
}
function updateSlots(){
  document.querySelectorAll('.slot').forEach((el,i)=>{
    el.classList.toggle('active',i===state.player.slot);
    const s=state.slots[i];
    el.querySelector('div:not(.num)').textContent=s?(WEAPONS[s.type]?WEAPONS[s.type].name:(s.type+(s.count?' x'+s.count:''))):'-';
  });
}

let lastShot=0;
function shoot(){
  const cur=state.slots[state.player.slot];
  if(!cur||!WEAPONS[cur.type])return;
  const w=WEAPONS[cur.type];
  const now=performance.now()/1000;
  if(now-lastShot<w.rate)return;
  if(cur.ammo!==undefined&&cur.ammo<=0){showMessage('Нет патронов!',800);return;}
  lastShot=now;
  if(cur.ammo!==Infinity&&cur.ammo!==undefined)cur.ammo--;
  selectSlot(state.player.slot);

  // Raycast
  const dir=new THREE.Vector3(0,0,-1).applyEuler(new THREE.Euler(state.player.pitch,state.player.yaw,0,'YXZ'));
  dir.x+=(Math.random()-0.5)*w.spread;
  dir.y+=(Math.random()-0.5)*w.spread;
  const origin=new THREE.Vector3(state.player.x,state.player.y+1.5,state.player.z);

  // Tracer
  const tracer=new THREE.Mesh(new THREE.SphereGeometry(0.1),new THREE.MeshBasicMaterial({color:0xffff00}));
  tracer.position.copy(origin);
  scene.add(tracer);
  setTimeout(()=>scene.remove(tracer),100);

  // Check hit enemies
  let closestT=w.range,closestE=null;
  state.enemies.forEach(e=>{
    if(!e.alive)return;
    const ep=new THREE.Vector3(e.x,e.y,e.z);
    const toE=ep.clone().sub(origin);
    const t=toE.dot(dir);
    if(t<0||t>w.range)return;
    const closest=origin.clone().add(dir.clone().multiplyScalar(t));
    const d=closest.distanceTo(ep);
    if(d<1&&t<closestT){closestT=t;closestE=e;}
  });
  if(closestE){
    const dmg=w.dmg*(Math.random()<0.2?2:1); // headshot chance
    closestE.hp-=dmg;
    state.player.damage+=dmg;
    if(closestE.hp<=0&&closestE.alive){
      closestE.alive=false;
      scene.remove(closestE.mesh);
      state.player.kills++;
      const dist=Math.sqrt((closestE.x-state.player.x)**2+(closestE.z-state.player.z)**2);
      if(dist>state.player.longestKill)state.player.longestKill=dist;
      showMessage('УБИЙСТВО! +'+(dist>100?20:10)+' XP',1200);
      updatePlayersAlive();
    } else {
      showMessage('Попадание!',500);
    }
  }
  playSound(180,0.05);
}

function reload(){
  const cur=state.slots[state.player.slot];
  if(!cur||!WEAPONS[cur.type])return;
  const w=WEAPONS[cur.type];
  if(w.maxAmmo){cur.ammo=w.maxAmmo;selectSlot(state.player.slot);showMessage('Перезарядка',800);}
}

function interact(){
  // pickup nearest loot
  let best=null,bd=3;
  state.loot.forEach(l=>{
    const d=Math.sqrt((l.x-state.player.x)**2+(l.z-state.player.z)**2);
    if(d<bd){bd=d;best=l;}
  });
  if(best){
    pickupLoot(best);
  }
}

function pickupLoot(l){
  scene.remove(l.mesh);
  state.loot=state.loot.filter(x=>x!==l);
  state.player.items++;
  if(l.type==='medkit'){
    if(!state.slots[3])state.slots[3]={type:'medkit',count:1};
    else state.slots[3].count=(state.slots[3].count||0)+1;
  } else if(l.type==='grenade'){
    if(!state.slots[4])state.slots[4]={type:'grenade',count:1};
    else state.slots[4].count=(state.slots[4].count||0)+1;
  } else if(l.type==='armor'){
    state.player.armor=100;
  } else if(WEAPONS[l.type]){
    // put in slot 1 or 2
    if(!state.slots[1]||!WEAPONS[state.slots[1].type]) state.slots[1]={type:l.type,ammo:WEAPONS[l.type].maxAmmo};
    else if(!state.slots[2]||!WEAPONS[state.slots[2].type]) state.slots[2]={type:l.type,ammo:WEAPONS[l.type].maxAmmo};
    else state.slots[state.player.slot]={type:l.type,ammo:WEAPONS[l.type].maxAmmo};
  }
  showMessage('Подобрано: '+(WEAPONS[l.type]?WEAPONS[l.type].name:l.type),1000);
  updateSlots();
  selectSlot(state.player.slot);
}

function useMedkit(){
  const m=state.slots[3];
  if(!m||!m.count||m.count<=0)return;
  if(state.player.hp>=100)return;
  state.player.hp=Math.min(100,state.player.hp+50);
  m.count--;
  if(m.count<=0)state.slots[3]=null;
  updateSlots();
  showMessage('Лечение +50 HP',1000);
}

// AI
function updateAI(dt){
  state.enemies.forEach(e=>{
    if(!e.alive)return;
    // simple patrol & shoot
    const toP=Math.sqrt((e.x-state.player.x)**2+(e.z-state.player.z)**2);
    if(toP<150&&!state.player.inPlane){
      // attack
      e.state='attack';
      const dx=state.player.x-e.x,dz=state.player.z-e.z;
      const dist=Math.sqrt(dx*dx+dz*dz);
      if(dist>30){
        e.x+=dx/dist*5*dt;e.z+=dz/dist*5*dt;
      }
      e.shootCooldown-=dt;
      if(e.shootCooldown<=0&&dist<120){
        e.shootCooldown=1.5/e.skill;
        // hit chance
        if(Math.random()<e.skill*0.4){
          const dmg=15;
          if(state.player.armor>0){
            state.player.armor=Math.max(0,state.player.armor-dmg*0.7);
            state.player.hp-=dmg*0.3;
          } else state.player.hp-=dmg;
          showMessage('Получен урон!',500);
          if(state.player.hp<=0)endGame(false);
        }
        playSound(120,0.04);
      }
    } else {
      e.patrolTime-=dt;
      if(e.patrolTime<=0){
        e.patrolTime=3+Math.random()*4;
        e.tx=e.x+(Math.random()-0.5)*30;
        e.tz=e.z+(Math.random()-0.5)*30;
      }
      const dx=e.tx-e.x,dz=e.tz-e.z;
      const d=Math.sqrt(dx*dx+dz*dz);
      if(d>1){e.x+=dx/d*2*dt;e.z+=dz/d*2*dt;}
    }
    // zone damage
    const zd=Math.sqrt((e.x-state.zone.cx)**2+(e.z-state.zone.cz)**2);
    if(zd>state.zone.r)e.hp-=5*dt;
    if(e.hp<=0){e.alive=false;scene.remove(e.mesh);updatePlayersAlive();}

    e.mesh.position.set(e.x,e.y,e.z);
  });
}

function updatePlayersAlive(){
  const alive=state.enemies.filter(e=>e.alive).length+1;
  document.getElementById('playersAlive').textContent=alive;
  if(alive<=1)endGame(true);
}

function updateZone(dt){
  state.zone.timer-=dt;
  if(state.zone.timer<=0&&state.zone.stage<7){
    state.zone.stage++;
    state.zone.r=state.zone.nextR;
    state.zone.cx=state.zone.ncx;
    state.zone.cz=state.zone.ncz;
    state.zone.nextR=state.zone.r*0.6;
    state.zone.ncx=state.zone.cx+(Math.random()-0.5)*100;
    state.zone.ncz=state.zone.cz+(Math.random()-0.5)*100;
    state.zone.timer=180;
    document.getElementById('zoneStage').textContent=state.zone.stage+'/7';
    showMessage('Зона сжимается!',2000);
  }
  // update zone mesh
  state.zoneMesh.scale.set(state.zone.r/499,state.zone.r/499,1);
  state.zoneMesh.position.set(state.zone.cx,1,state.zone.cz);

  const m=Math.floor(state.zone.timer/60),s=Math.floor(state.zone.timer%60);
  document.getElementById('zoneTimer').textContent=m+':'+s.toString().padStart(2,'0');

  // damage if outside zone
  const pd=Math.sqrt((state.player.x-state.zone.cx)**2+(state.player.z-state.zone.cz)**2);
  if(pd>state.zone.r){
    state.player.hp-=5*dt;
    document.getElementById('dangerOverlay').style.opacity=1;
    if(state.player.hp<=0)endGame(false);
  } else {
    document.getElementById('dangerOverlay').style.opacity=0;
  }
}

function updatePlayer(dt){
  if(state.player.inPlane){
    // plane flying
    state.player.x+=Math.cos(state.player.yaw)*150*dt;
    state.player.z+=Math.sin(state.player.yaw)*150*dt;
    state.player.y=400;
    planeMesh.position.set(state.player.x,state.player.y,state.player.z);
    planeMesh.rotation.y=-state.player.yaw+Math.PI/2;
    // camera follows behind plane
    camera.position.set(state.player.x-Math.cos(state.player.yaw)*30,state.player.y+10,state.player.z-Math.sin(state.player.yaw)*30);
    camera.lookAt(state.player.x,state.player.y,state.player.z);
    return;
  }
  // hide plane
  if(planeMesh.parent)planeMesh.position.y=600;

  if(!state.player.onGround){
    // falling
    if(state.player.y<200&&!state.player.parachute){
      state.player.parachute=true;
      showMessage('Парашют открыт!',1500);
    }
    const grav=state.player.parachute?-8:-25;
    state.player.vy+=grav*dt;
    if(state.player.parachute&&state.player.vy<-8)state.player.vy=-8;
    // air control
    const speed=state.player.parachute?15:30;
    if(state.keys.KeyW){state.player.x+=Math.cos(state.player.yaw-Math.PI/2)*speed*dt;state.player.z+=Math.sin(state.player.yaw-Math.PI/2)*speed*dt;}
    if(state.keys.KeyS){state.player.x-=Math.cos(state.player.yaw-Math.PI/2)*speed*dt;state.player.z-=Math.sin(state.player.yaw-Math.PI/2)*speed*dt;}
    if(state.keys.KeyA){state.player.x+=Math.cos(state.player.yaw)*speed*dt;state.player.z+=Math.sin(state.player.yaw)*speed*dt;}
    if(state.keys.KeyD){state.player.x-=Math.cos(state.player.yaw)*speed*dt;state.player.z-=Math.sin(state.player.yaw)*speed*dt;}
    state.player.y+=state.player.vy*dt;
    if(state.player.y<=1.5){
      state.player.y=1.5;state.player.vy=0;state.player.onGround=true;state.player.parachute=false;
      showMessage('Приземление!',1500);
    }
  } else {
    // ground movement
    const run=state.keys.ShiftLeft?1.7:1;
    const speed=8*run;
    let mx=0,mz=0;
    if(state.keys.KeyW){mx+=Math.cos(state.player.yaw-Math.PI/2);mz+=Math.sin(state.player.yaw-Math.PI/2);}
    if(state.keys.KeyS){mx-=Math.cos(state.player.yaw-Math.PI/2);mz-=Math.sin(state.player.yaw-Math.PI/2);}
    if(state.keys.KeyA){mx+=Math.cos(state.player.yaw);mz+=Math.sin(state.player.yaw);}
    if(state.keys.KeyD){mx-=Math.cos(state.player.yaw);mz-=Math.sin(state.player.yaw);}
    const ml=Math.sqrt(mx*mx+mz*mz);
    if(ml>0){
      const newX=state.player.x+mx/ml*speed*dt;
      const newZ=state.player.z+mz/ml*speed*dt;
      // building collision
      let blocked=false;
      for(const b of state.buildings){
        if(Math.abs(newX-b.x)<b.w/2+0.5&&Math.abs(newZ-b.z)<b.d/2+0.5){blocked=true;break;}
      }
      if(!blocked){state.player.x=newX;state.player.z=newZ;}
      state.player.distance+=speed*dt;
    }
    if(state.keys.Space&&state.player.vy===0)state.player.vy=8;
    state.player.vy-=25*dt;
    state.player.y+=state.player.vy*dt;
    if(state.player.y<1.5){state.player.y=1.5;state.player.vy=0;}
    if(state.keys.KeyG&&!state._gthrow){state._gthrow=true;throwGrenade();}
    if(!state.keys.KeyG)state._gthrow=false;
    if(state.keys.Digit4||state.keys.KeyH){if(!state._heal){state._heal=true;useMedkit();}}else state._heal=false;
  }
  state.player.x=Math.max(0,Math.min(1000,state.player.x));
  state.player.z=Math.max(0,Math.min(1000,state.player.z));

  playerMesh.position.set(state.player.x,state.player.y,state.player.z);

  // Camera FPS
  const eye=new THREE.Vector3(state.player.x,state.player.y+1.5,state.player.z);
  camera.position.copy(eye);
  camera.rotation.order='YXZ';
  camera.rotation.y=state.player.yaw;
  camera.rotation.x=state.player.pitch;
}

function throwGrenade(){
  const g=state.slots[4];
  if(!g||!g.count||g.count<=0)return;
  g.count--;
  updateSlots();
  // explosion at player look point
  const dir=new THREE.Vector3(0,0,-1).applyEuler(new THREE.Euler(state.player.pitch,state.player.yaw,0,'YXZ'));
  const tx=state.player.x+dir.x*20,tz=state.player.z+dir.z*20;
  setTimeout(()=>{
    // damage enemies in radius
    state.enemies.forEach(e=>{
      if(!e.alive)return;
      const d=Math.sqrt((e.x-tx)**2+(e.z-tz)**2);
      if(d<8){
        e.hp-=80;
        if(e.hp<=0){e.alive=false;scene.remove(e.mesh);state.player.kills++;updatePlayersAlive();}
      }
    });
    // visual
    const ex=new THREE.Mesh(new THREE.SphereGeometry(5),new THREE.MeshBasicMaterial({color:0xff6600,transparent:true,opacity:0.8}));
    ex.position.set(tx,2,tz);
    scene.add(ex);
    setTimeout(()=>scene.remove(ex),500);
    playSound(60,0.3);
  },1500);
  showMessage('Граната брошена!',1000);
}

function updateMinimap(){
  const ctx=document.getElementById('minimap').getContext('2d');
  ctx.fillStyle='#1a3a1a';
  ctx.fillRect(0,0,200,200);
  // buildings
  ctx.fillStyle='#666';
  state.buildings.forEach(b=>{ctx.fillRect(b.x/5,b.z/5,b.w/5+1,b.d/5+1)});
  // zone
  ctx.strokeStyle='#3399ff';ctx.lineWidth=2;
  ctx.beginPath();ctx.arc(state.zone.cx/5,state.zone.cz/5,state.zone.r/5,0,7);ctx.stroke();
  // enemies
  ctx.fillStyle='#f33';
  state.enemies.forEach(e=>{if(e.alive){
    const d=Math.sqrt((e.x-state.player.x)**2+(e.z-state.player.z)**2);
    if(d<150)ctx.fillRect(e.x/5-2,e.z/5-2,4,4);
  }});
  // player
  ctx.fillStyle='#ffd700';
  ctx.beginPath();ctx.arc(state.player.x/5,state.player.z/5,4,0,7);ctx.fill();
}

function updateHUD(){
  document.getElementById('hpBar').style.width=Math.max(0,state.player.hp)+'%';
  document.getElementById('hpText').textContent=Math.max(0,Math.floor(state.player.hp))+'/100';
  document.getElementById('armorBar').style.width=state.player.armor+'%';
  document.getElementById('armorText').textContent=Math.floor(state.player.armor)+'/100';
}

function animate(){
  if(!state.gameRunning)return;
  requestAnimationFrame(animate);
  const dt=Math.min(0.05,clock.getDelta());

  updatePlayer(dt);
  if(!state.player.inPlane){
    updateAI(dt);
    updateZone(dt);
  }
  updateMinimap();
  updateHUD();

  renderer.render(scene,camera);
}

function endGame(won){
  state.gameRunning=false;
  document.exitPointerLock&&document.exitPointerLock();
  const time=Math.floor((Date.now()-state.player.startTime)/1000);
  let xp=state.player.kills*10+time/60+(won?500:0);
  xp=Math.floor(xp);
  state.stats.games++;
  if(won)state.stats.wins++;
  state.stats.kills+=state.player.kills;
  state.stats.xp+=xp;
  state.stats.level=1+Math.floor(state.stats.xp/1000);
  localStorage.setItem('reg2_stats',JSON.stringify(state.stats));

  const es=document.getElementById('endScreen');
  es.className='screen '+(won?'win':'lose');
  document.getElementById('endTitle').textContent=won?'ПОБЕДА!':'ВЫБЫЛ';
  const alive=state.enemies.filter(e=>e.alive).length+1;
  document.getElementById('endStats').innerHTML=`
    <div class="stat-row"><span>Убийств:</span><span>${state.player.kills}</span></div>
    <div class="stat-row"><span>Урон:</span><span>${Math.floor(state.player.damage)}</span></div>
    <div class="stat-row"><span>Время:</span><span>${Math.floor(time/60)}:${(time%60).toString().padStart(2,'0')}</span></div>
    <div class="stat-row"><span>Дистанция:</span><span>${Math.floor(state.player.distance)} м</span></div>
    <div class="stat-row"><span>Дальний выстрел:</span><span>${Math.floor(state.player.longestKill)} м</span></div>
    <div class="stat-row"><span>Предметов:</span><span>${state.player.items}</span></div>
    <div class="stat-row"><span>Позиция:</span><span>#${alive}</span></div>
    <div class="stat-row"><span>Получено XP:</span><span>+${xp}</span></div>
  `;
  setTimeout(()=>show('endScreen'),500);
}

// Audio
let audioCtx;
function playSound(freq,dur){
  try{
    if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();
    const o=audioCtx.createOscillator(),g=audioCtx.createGain();
    o.frequency.value=freq;o.type='square';
    g.gain.setValueAtTime(0.1,audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.001,audioCtx.currentTime+dur);
    o.connect(g);g.connect(audioCtx.destination);
    o.start();o.stop(audioCtx.currentTime+dur);
  }catch(e){}
}
</script>
</body>
</html>
